INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92553, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公告是写出来告诉大家的消息。", "primary_collocate": null, "pronunciation": "gōng gào", "ipa": "kʊŋ˥ kaʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "门口有一张公告。", "target_word": "公告", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请大家看一下墙上的公告。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在楼下看到一则公告。", "target_word": "公告", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公告上写着明天停水。", "target_word": "公告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把公告贴在教室门上。", "target_word": "公告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的公告说今晚没有电。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看过今天的公告吗？", "target_word": "公告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼里新贴了一张公告，大家都去看。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公告写得很清楚，不用再问。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的公告说下周一休息。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份公告", "label": "量词"}, {"form": "一则公告", "label": "量词"}, {"form": "一张公告", "label": "量词"}, {"form": "公告栏", "label": "复合"}, {"form": "公告牌", "label": "复合"}], "register": "正式", "sense_fingerprint": "贴出或写出来、告诉大家某件事的书面消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92553, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公告", "is_correct": true, "explanation": "正确：“公告”是写出来告诉大家的消息，可以贴在门口，“一张”也搭配。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：门口不会平白放一张邮票，句子说不通。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：门口一般不会放钞票，与常理不符。"}, {"text": "书签", "is_correct": false, "explanation": "语义：书签是用来夹书的，门口放一张书签不合常理。"}], "explanations": {"公告": "正确：“公告”是写出来告诉大家的消息，可以贴在门口，“一张”也搭配。", "邮票": "语义：门口不会平白放一张邮票，句子说不通。", "钞票": "语义：门口一般不会放钞票，与常理不符。", "书签": "语义：书签是用来夹书的，门口放一张书签不合常理。"}, "sentence_index": 0, "correct_answer": "公告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上唱了一首公告，大家都鼓掌。", "explanation": "这里应该用〈歌曲〉。“公告”是书面消息，不能拿来唱，唱的应当是“歌曲”。"}, {"text": "他讲了一个公告，大家都笑了。", "explanation": "这里应该用〈笑话〉。“公告”是正式通知，讲来取乐的内容要用“笑话”，不能用“公告”。"}, {"text": "他给朋友写了一份公告，倾诉了自己的心事。", "explanation": "这里应该用〈书信〉。“公告”是告诉大家的消息，写给朋友倾诉心事要用“书信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92553, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公告", "is_correct": true, "explanation": "正确：“公告”是可以看、可以读的书面消息，与“你看过……吗”搭配自然。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“今天的历史”说不通，历史不是一天之内发生的消息。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：味道要用“闻”或“尝”，不能说“看过味道”。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音要用“听”，不能说“看过声音”。"}], "explanations": {"公告": "正确：“公告”是可以看、可以读的书面消息，与“你看过……吗”搭配自然。", "历史": "语义：“今天的历史”说不通，历史不是一天之内发生的消息。", "味道": "搭配：味道要用“闻”或“尝”，不能说“看过味道”。", "声音": "搭配：声音要用“听”，不能说“看过声音”。"}, "sentence_index": 6, "correct_answer": "公告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上都给女朋友写公告。", "explanation": "这里应该用〈情书〉。“公告”是面向公众的通知，写给恋人的话要用“情书”。"}, {"text": "他在桌上留了一张公告给妈妈。", "explanation": "这里应该用〈便条〉。“公告”是面向公众的，留给家人的话要用“便条”。"}, {"text": "他在网上发了一条公告，分享自己的旅行照片。", "explanation": "这里应该用〈动态〉。“公告”是正式的公开通知，分享个人照片要用“动态”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92553, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上贴着一只公告。", "corrected_sentence": "墙上贴着一张公告。", "error_description": "错误：“一只公告”。正确：“一张公告”。“只”多用于动物等，纸质的公告应该用量词“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92553, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校门口贴着一根公告。", "corrected_sentence": "学校门口贴着一份公告。", "error_description": "错误：“一根公告”。正确：“一份公告”。“根”用于细长的东西，文字类的公告应该用量词“份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
