INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府、机关或团体向公众发布的正式通知。", "primary_collocate": null, "pronunciation": "gōng gào", "ipa": "kʊŋ˥ kaʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "市政府发布了一则公告。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公告说，下月起调整地铁票价。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校发出公告，提醒家长注意安全。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府的公告要求大家少开车。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "银行在网上发布公告，说明新规定。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份公告由公司正式发出。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公安局的公告提醒市民不要相信陌生电话。", "target_word": "公告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里的公告已经在报纸上登出来了。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司公告里说，这个月底会开大会。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车站发布公告，明天有些车次停开。", "target_word": "公告", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一份公告", "label": "量词"}, {"form": "一则公告", "label": "量词"}, {"form": "公告栏", "label": "复合"}, {"form": "招标公告", "label": "复合"}], "register": "正式", "sense_fingerprint": "政府、机关或团体对公众正式发布的通知", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公告", "is_correct": true, "explanation": "正确：“公告”是政府发布的正式通知，与“市政府发布了一则”搭配自然。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：政府不会发布笑话，与句中的“市政府”不相符。"}, {"text": "谣言", "is_correct": false, "explanation": "语义：政府不会发布谣言，与“发布”的正式语境相矛盾。"}, {"text": "小道消息", "is_correct": false, "explanation": "语域：“小道消息”是非正式的传闻，与政府正式发布的语境不符。"}], "explanations": {"公告": "正确：“公告”是政府发布的正式通知，与“市政府发布了一则”搭配自然。", "笑话": "语义：政府不会发布笑话，与句中的“市政府”不相符。", "谣言": "语义：政府不会发布谣言，与“发布”的正式语境相矛盾。", "小道消息": "语域：“小道消息”是非正式的传闻，与政府正式发布的语境不符。"}, "sentence_index": 0, "correct_answer": "公告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天照着公告做饭。", "explanation": "这里应该用〈菜谱〉。“公告”是正式通知，做饭要照着“菜谱”，不能用“公告”。"}, {"text": "孩子们在操场上玩公告。", "explanation": "这里应该用〈游戏〉。“公告”不能用于“玩”，孩子们在操场上玩的是“游戏”。"}, {"text": "他在冰箱上留了一张公告。", "explanation": "这里应该用〈便条〉。“公告”面向公众，给家人留言要用“便条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公告", "is_correct": true, "explanation": "正确：“公告”是面向公众的正式通知，适合用来提醒市民。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是消费或欠款的凭证，不用来提醒市民防骗。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱用于做菜，与提醒市民防骗无关。"}, {"text": "菜单", "is_correct": false, "explanation": "语义：菜单用于点餐，不用来提醒市民防骗。"}], "explanations": {"公告": "正确：“公告”是面向公众的正式通知，适合用来提醒市民。", "账单": "语义：账单是消费或欠款的凭证，不用来提醒市民防骗。", "食谱": "语义：食谱用于做菜，与提醒市民防骗无关。", "菜单": "语义：菜单用于点餐，不用来提醒市民防骗。"}, "sentence_index": 6, "correct_answer": "公告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他写下了一份公告，把房子留给了儿子。", "explanation": "这里应该用〈遗嘱〉。“公告”面向公众，财产的安排要用“遗嘱”。"}, {"text": "他写了一首公告。", "explanation": "这里应该用〈诗〉。“公告”是正式通知，不是诗歌，不能说“写了一首公告”。"}, {"text": "他给我发了一条公告，说今晚一起吃饭。", "explanation": "这里应该用〈短信〉。“公告”面向公众，私人的约饭要用“短信”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市教育局发布了一只公告。", "corrected_sentence": "市教育局发布了一则公告。", "error_description": "错误：“一只公告”。正确：“一则公告”。“只”多用于动物等，通知类的公告应该用量词“则”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92554, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "电视台播出了一根公告。", "corrected_sentence": "电视台播出了一则公告。", "error_description": "错误：“一根公告”。正确：“一则公告”。“根”用于细长的东西，通知类的公告应该用量词“则”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加：与“删除”相反，指把字词加进去。"}, {"text": "打开", "is_correct": false, "explanation": "打开：指使内容可见，与“删除”没有反义关系。"}, {"text": "浏览", "is_correct": false, "explanation": "浏览：指快速看一看，与“删除”没有反义关系。"}, {"text": "复制", "is_correct": false, "explanation": "复制：指做出一份相同的内容，不是“删除”的反义词。"}], "correct_answer": "添加", "explanations": {"添加": "添加：与“删除”相反，指把字词加进去。", "打开": "打开：指使内容可见，与“删除”没有反义关系。", "浏览": "浏览：指快速看一看，与“删除”没有反义关系。", "复制": "复制：指做出一份相同的内容，不是“删除”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加：与“删除”相反，指把字词加进去。"}, {"text": "查找", "is_correct": false, "explanation": "查找：指寻找，与“删除”没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译：指换成另一种语言，与“删除”没有反义关系。"}, {"text": "核对", "is_correct": false, "explanation": "核对：指比较检查，与“删除”没有反义关系。"}], "correct_answer": "添加", "explanations": {"添加": "添加：与“删除”相反，指把字词加进去。", "查找": "查找：指寻找，与“删除”没有反义关系。", "翻译": "翻译：指换成另一种语言，与“删除”没有反义关系。", "核对": "核对：指比较检查，与“删除”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "删除是把不要的字去掉。", "primary_collocate": null, "pronunciation": "shān chú", "ipa": "ʂan˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "请把这个字删除。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我删除这句话。", "target_word": "删除", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "句子里没用的词，要删除。", "target_word": "删除", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把多写的两个字删除了。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话太长，请删除几个字。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明写多了，就把多余的字删除。", "target_word": "删除", "complexity_tier": "T3", "furigana": "xiǎo míng xiě duō le， jiù bǎ duō yú de zì shān chú。", "sentence_source": "generated"}, {"text": "这句话没有用，我删除了它。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你把重复的字都删除。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章时，多余的词要删除。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看了一遍，删除了三个字。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "删除了", "label": "体标"}, {"form": "删除过", "label": "体标"}, {"form": "刪除", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把文章里多余、不要的字词去掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ffa561-fbb8-426b-81b7-350f6bf5c46a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "删除", "is_correct": true, "explanation": "删除：去掉这个多余的字，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象须是食物，“字”不能吃。"}, {"text": "放", "is_correct": false, "explanation": "配价：“放”后要带处所，如“放在……”，句子里没有地点。"}, {"text": "增加", "is_correct": false, "explanation": "搭配：“增加”说数量或程度的变化，不能说把一个字“增加”。"}], "explanations": {"删除": "删除：去掉这个多余的字，符合句意。", "吃": "语义：“吃”的对象须是食物，“字”不能吃。", "放": "配价：“放”后要带处所，如“放在……”，句子里没有地点。", "增加": "搭配：“增加”说数量或程度的变化，不能说把一个字“增加”。"}, "sentence_index": 0, "correct_answer": "删除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把汤里的葱删除了。", "explanation": "这里应该用〈去掉〉。删除用于字词，不用于食材，汤里的葱要说去掉。"}, {"text": "他把地上的垃圾删除了。", "explanation": "这里应该用〈扔掉〉。删除用于字词，不用于实物，地上的垃圾要说扔掉。"}, {"text": "他把坏掉的旧雨伞删除了。", "explanation": "这里应该用〈丢掉〉。删除用于字词，不用于实物，坏掉的旧雨伞要说丢掉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "删除", "is_correct": true, "explanation": "删除：去掉这句话，符合“没有用”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，“它”指一句话，不能喝。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”用于人或作品的优点，与“没有用”的评价矛盾。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”的对象是人或动物，不能拥抱一句话。"}], "explanations": {"删除": "删除：去掉这句话，符合“没有用”的语境。", "喝": "语义：“喝”的对象是液体，“它”指一句话，不能喝。", "赞美": "搭配：“赞美”用于人或作品的优点，与“没有用”的评价矛盾。", "拥抱": "语义：“拥抱”的对象是人或动物，不能拥抱一句话。"}, "sentence_index": 6, "correct_answer": "删除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我删除了那只小猫。", "explanation": "这里删除被当作“让某个生物消失”的意思来用，但删除只指去掉字词或数据，不能用于动物。"}, {"text": "她删除了那张书桌。", "explanation": "这里删除被当作“搬走或丢弃家具”的意思来用，但删除只指去掉字词或数据，不能用于家具。"}, {"text": "爸爸删除了那棵大树。", "explanation": "这里删除被当作“砍掉、移走树木”的意思来用，但删除只指去掉字词或数据，不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你删除了这个错字。", "corrected_sentence": "请你删除这个错字。", "error_description": "错误在“删除”后多加了“了”。祈使句（请你……）不用“了”，应说“请你删除这个错字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没删除了那个错字。", "corrected_sentence": "我没删除过那个错字。", "error_description": "错误在“没”后的“过”被换成了“了”。“没”否定过去的经历时要与“过”搭配，应说“我没删除过那个错字”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
