INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92568, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "添加", "is_correct": true, "explanation": "添加：与“删除”相反，指把文件、数据加进去。"}, {"text": "登录", "is_correct": false, "explanation": "登录：指进入账号，与“删除”没有反义关系。"}, {"text": "备份", "is_correct": false, "explanation": "备份：指另存一份副本，与“删除”不是反义词。"}, {"text": "搜索", "is_correct": false, "explanation": "搜索：指查找信息，与“删除”没有反义关系。"}], "correct_answer": "添加", "explanations": {"添加": "添加：与“删除”相反，指把文件、数据加进去。", "登录": "登录：指进入账号，与“删除”没有反义关系。", "备份": "备份：指另存一份副本，与“删除”不是反义词。", "搜索": "搜索：指查找信息，与“删除”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92568, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去掉文字、文件或数据中不需要的部分。", "primary_collocate": null, "pronunciation": "shān chú", "ipa": "ʂan˥ ʈʂʰu˧˥", "syllable_count": 2, "sentences": [{"text": "请删除电脑里没用的文件。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把手机里的旧照片删除了。", "target_word": "删除", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条短信不重要，你可以删除。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不小心删除了一份重要文件。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "系统会自动删除旧数据。", "target_word": "删除", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请先删除这几行字，再保存。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想删除网上的那条消息。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "文件删除以后，还能找回来吗？", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邮箱满了，我删除了很多旧邮件。", "target_word": "删除", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你删除过聊天记录吗？", "target_word": "删除", "complexity_tier": "T3", "furigana": "nǐ shān chú guo liáo tiān jì lù ma？", "sentence_source": "generated"}], "morphological_forms": [{"form": "删除了", "label": "体标"}, {"form": "删除过", "label": "体标"}, {"form": "刪除", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从电脑、手机里的文件、数据、记录中去掉不需要的内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5ffa561-fbb8-426b-81b7-350f6bf5c46a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92568, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "删除", "is_correct": true, "explanation": "删除：去掉电脑里没用的文件，符合句意。"}, {"text": "下载", "is_correct": false, "explanation": "语义：“下载”是从网络取得文件，与“电脑里”已有的文件矛盾。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体或食物，文件不能喝。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”的对象是人或动物，文件不能拥抱。"}], "explanations": {"删除": "删除：去掉电脑里没用的文件，符合句意。", "下载": "语义：“下载”是从网络取得文件，与“电脑里”已有的文件矛盾。", "喝": "语义：“喝”的对象是液体或食物，文件不能喝。", "拥抱": "语义：“拥抱”的对象是人或动物，文件不能拥抱。"}, "sentence_index": 0, "correct_answer": "删除"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把照片删除到了U盘里。", "explanation": "这里应该用〈复制〉。删除是去掉文件或数据，不表示把文件放到别处，要说复制。"}, {"text": "我把文件删除到了桌面上。", "explanation": "这里应该用〈保存〉。删除是去掉文件或数据，不表示把文件存到某处，要说保存。"}, {"text": "我把视频删除到了网盘。", "explanation": "这里应该用〈上传〉。删除是去掉文件或数据，不表示把文件送到网上，要说上传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92568, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "删除", "is_correct": true, "explanation": "删除：去掉网上的那条消息，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”的对象是器物或设备，不能修理一条消息。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”的对象是人，消息不能被安慰。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”用于动植物或习惯，不说养“消息”。"}], "explanations": {"删除": "删除：去掉网上的那条消息，符合句意。", "修理": "语义：“修理”的对象是器物或设备，不能修理一条消息。", "安慰": "语义：“安慰”的对象是人，消息不能被安慰。", "养": "搭配：“养”用于动植物或习惯，不说养“消息”。"}, "sentence_index": 6, "correct_answer": "删除"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他删除了那座桥。", "explanation": "这里删除被当作“拆除、拆掉建筑物”的意思来用，但删除只指去掉文字、文件或数据，不能用于实物。"}, {"text": "我删除了那辆自行车。", "explanation": "这里删除被当作“丢弃或搬走交通工具”的意思来用，但删除只指去掉文件或数据，不能用于实物。"}, {"text": "奶奶删除了那棵树。", "explanation": "这里删除被当作“砍掉、移走树木”的意思来用，但删除只指去掉文件或数据，不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1071fa9-5c5f-4606-be92-ad8269e26ba5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
