INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92572, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈每天晚上都看这部剧们。", "corrected_sentence": "我妈妈每天晚上都看这部剧。", "error_description": "错误在词尾：“剧”后面不能加“们”，“们”只用于指人的名词。正确说法是“这部剧”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
