INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面向南方时靠西的一边；与“左”相对。", "primary_collocate": null, "pronunciation": "yòu", "ipa": "jou˥˩", "syllable_count": 1, "sentences": [{"text": "前面有红绿灯，请向右转。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行在马路的右，书店在左。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁站出来往右走，就能看到银行。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，汽车一般靠右行驶。", "target_word": "右", "complexity_tier": "T3", "furigana": "zài Zhōngguó, qìchē yìbān kào yòu xíngshǐ.", "sentence_source": "generated"}, {"text": "看地图，北在上，东在右。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "向左走是学校，向右走是公园。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先往右拐，再一直往前走。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红绿灯前不能向右转，要等一等。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在中国，过马路时先看左，再看右。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你站在老师的右，我站在老师的左。", "target_word": "右", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "右边", "label": "复合"}, {"form": "右转", "label": "复合"}], "register": "中性", "sense_fingerprint": "右·面向南时靠西的一边，与左相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "右", "is_correct": true, "explanation": "yòu（第四声）指面向南方时靠西的一边，与“左”相对，是正确答案。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“有”，不是方位。"}, {"text": "游", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，意思是“游览”。"}, {"text": "忧", "is_correct": false, "explanation": "yōu（第一声）与 yòu（第四声）声调不同，意思是“忧愁”。"}], "explanations": {"右": "yòu（第四声）指面向南方时靠西的一边，与“左”相对，是正确答案。", "有": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“有”，不是方位。", "游": "yóu（第二声）与 yòu（第四声）声调不同，意思是“游览”。", "忧": "yōu（第一声）与 yòu（第四声）声调不同，意思是“忧愁”。"}, "sentence_index": null, "correct_answer": "右"}, "level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "“右”表示向这一侧转弯，与“红绿灯”的路口语境相合。"}, {"text": "旁", "is_correct": false, "explanation": "搭配：“旁”单用不表示方向，要说“旁边”。"}, {"text": "下", "is_correct": false, "explanation": "语义：“下”指向下，不是路口拐弯的方向。"}, {"text": "中", "is_correct": false, "explanation": "搭配：“向中”不能单独表示转弯的方向。"}], "explanations": {"右": "“右”表示向这一侧转弯，与“红绿灯”的路口语境相合。", "旁": "搭配：“旁”单用不表示方向，要说“旁边”。", "下": "语义：“下”指向下，不是路口拐弯的方向。", "中": "搭配：“向中”不能单独表示转弯的方向。"}, "sentence_index": 0, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题的解法很右，老师点头表扬了。", "explanation": "这里应该用〈对〉。〈右〉表示方位，不能用来判断解法对错，表示正确要用〈对〉。"}, {"text": "他的成绩比我右，所以排在前面。", "explanation": "这里应该用〈好〉。〈右〉不表示成绩好坏，形容成绩好要用〈好〉。"}, {"text": "这把椅子右得很，坐上去特别舒服。", "explanation": "这里应该用〈舒服〉。〈右〉表示方位，不能形容舒适程度，形容舒适要用〈舒服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "右", "is_correct": true, "explanation": "yòu（第四声）指面向南方时靠西的一边，是正确答案。"}, {"text": "油", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，意思是“油”。"}, {"text": "友", "is_correct": false, "explanation": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“朋友”。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yòu（第四声）声调不同，意思是“优秀”。"}, {"text": "由", "is_correct": false, "explanation": "yóu（第二声）与 yòu（第四声）声调不同，意思是“由于”。"}], "explanations": {"右": "yòu（第四声）指面向南方时靠西的一边，是正确答案。", "油": "yóu（第二声）与 yòu（第四声）声调不同，意思是“油”。", "友": "yǒu（第三声）与 yòu（第四声）声调不同，意思是“朋友”。", "优": "yōu（第一声）与 yòu（第四声）声调不同，意思是“优秀”。", "由": "yóu（第二声）与 yòu（第四声）声调不同，意思是“由于”。"}, "sentence_index": null, "correct_answer": "右"}, "level_3": {"options": [{"text": "右", "is_correct": true, "explanation": "“右”表示向这一侧拐弯，与“请先往…拐”的语境相合。"}, {"text": "上", "is_correct": false, "explanation": "语义：“上”指上方，不是拐弯的方向。"}, {"text": "底", "is_correct": false, "explanation": "搭配：“底”不作方位词，不能说“往底拐”。"}, {"text": "面", "is_correct": false, "explanation": "搭配：“面”不单独表示方向，不能说“往面拐”。"}], "explanations": {"右": "“右”表示向这一侧拐弯，与“请先往…拐”的语境相合。", "上": "语义：“上”指上方，不是拐弯的方向。", "底": "搭配：“底”不作方位词，不能说“往底拐”。", "面": "搭配：“面”不单独表示方向，不能说“往面拐”。"}, "sentence_index": 6, "correct_answer": "右"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他比我右一级，所以他说了算。", "explanation": "这里应该用〈高〉。现代汉语中〈右〉表示方位，一般不用来比较职位高低（“无出其右”等固定说法除外），比较职位要用〈高〉。"}, {"text": "我的电脑比他的右，运行得更快。", "explanation": "这里应该用〈好〉。〈右〉不能比较性能好坏，比较性能要用〈好〉。"}, {"text": "这次比赛他的表现很右，观众都鼓掌。", "explanation": "这里应该用〈精彩〉。〈右〉不能形容表现的精彩程度，形容表现精彩要用〈精彩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前面路口请向右的拐。", "corrected_sentence": "前面路口请向右拐。", "error_description": "错误在“向右”后面多加了“的”。“向右”修饰动词时要直接接动词，应说“向右拐”，“右”和动词之间不能加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站在路口右的，等我们过去。", "corrected_sentence": "他站在路口的右，等我们过去。", "error_description": "错误在方位词“右”后面多加了“的”。应说“路口的右”，“的”接在名词“路口”后面，“右”后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
