INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92581, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国防是保护国家不被别人欺负的事。", "primary_collocate": null, "pronunciation": "guó fáng", "ipa": "kuo˧˥ fɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "国家要有强大的国防。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "国防让人民安心生活。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "保护国家要靠国防。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在军队里工作，为国防出力。", "target_word": "国防", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，国防很重要。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "没有国防，国家就不安全。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个国家都很重视国防。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷当过兵，一直关心国防。", "target_word": "国防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国防强了，别人就不敢欺负我们。", "target_word": "国防", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家的国防很弱。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "國防", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国防：日常说法，指保护国家安全、不让别人欺负的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国防", "is_correct": true, "explanation": "正确：「国防」指保卫国家的工作与力量，可以用「强大的」修饰。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「强大」修饰力量、实力类名词，不能修饰「天气」。"}, {"text": "童话", "is_correct": false, "explanation": "语义：「童话」是虚构的故事，与国家需要的实力无关，「强大的童话」不成立。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：「空气」不能用「强大」来形容，「强大的空气」不成立。"}], "explanations": {"国防": "正确：「国防」指保卫国家的工作与力量，可以用「强大的」修饰。", "天气": "搭配：「强大」修饰力量、实力类名词，不能修饰「天气」。", "童话": "语义：「童话」是虚构的故事，与国家需要的实力无关，「强大的童话」不成立。", "空气": "搭配：「空气」不能用「强大」来形容，「强大的空气」不成立。"}, "sentence_index": 0, "correct_answer": "国防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在国防里工作。", "explanation": "这里应该用〈军队〉。国防是保卫国家的工作，不是单位或场所，说「在……里工作」要用〈军队〉。"}, {"text": "他是一名国防，守卫着边疆。", "explanation": "这里应该用〈军人〉。国防指保卫工作，不能指人，表示人要用〈军人〉。"}, {"text": "国防在山脚下。", "explanation": "这里应该用〈边防站〉。国防是抽象的保卫工作，不是具体的哨所，不能说「在某处」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国防", "is_correct": true, "explanation": "正确：「国防」是国家重视的重要事务，与「每个国家都很重视」相合。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：「盘子」是日常器皿，不是国家层面值得重视的对象。"}, {"text": "闹钟", "is_correct": false, "explanation": "搭配：「重视」多接抽象的事务，「闹钟」不能这样搭配。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：「雨伞」只用于挡雨，与国家层面的重视不搭。"}], "explanations": {"国防": "正确：「国防」是国家重视的重要事务，与「每个国家都很重视」相合。", "盘子": "语义：「盘子」是日常器皿，不是国家层面值得重视的对象。", "闹钟": "搭配：「重视」多接抽象的事务，「闹钟」不能这样搭配。", "雨伞": "语义：「雨伞」只用于挡雨，与国家层面的重视不搭。"}, "sentence_index": 6, "correct_answer": "国防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国防每晚在城墙上站岗。", "explanation": "这里应该用〈哨兵〉。国防是抽象的工作，不能在城墙上站岗，表示站岗的人要用〈哨兵〉。"}, {"text": "国防每天维护街道秩序。", "explanation": "这里应该用〈警察〉。国防针对对外防御，维护街道秩序应用〈警察〉。"}, {"text": "这个国家进行了一次国防。", "explanation": "这里不能用〈次〉计量。国防是抽象概念，不能像一次活动那样计数，应说「加强国防」之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国防了强，我们就更安全了。", "corrected_sentence": "国防强了，我们就更安全了。", "error_description": "错误形式：「国防了强」；正确形式：「国防强了」。「了」应放在形容词「强」之后，表示变化，不能插在「国防」和「强」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个国家一个国防很强。", "corrected_sentence": "那个国家的国防很强。", "error_description": "错误形式：「那个国家一个国防很强」；正确形式：「那个国家的国防很强」。「国防」是抽象概念，不能用「一个」计量；「国家」修饰「国防」时应加「的」，应去掉「一个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
