INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92582, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为保卫国家的领土和主权而进行的防御工作。", "primary_collocate": null, "pronunciation": "guó fáng", "ipa": "kuo˧˥ fɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "政府今年把更多的钱用在国防上。", "target_word": "国防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巩固国防是国家的大事。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "边境的国防工作很辛苦。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一生都在为国防事业工作。", "target_word": "国防", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国防要保卫领土和主权。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "加强国防，才能保卫边境。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "军队是国防的重要力量。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位科学家把一生献给了国防。", "target_word": "国防", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国防安全关系到每个人。", "target_word": "国防", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新闻说，我国的国防不断加强。", "target_word": "国防", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "國防", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国防：书面用语，指为保卫领土和主权而进行的防御工作，常与加强、巩固、经费搭配", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cf42e3e0-3aa5-4213-89fd-9bc9b80dff5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92582, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国防", "is_correct": true, "explanation": "正确：「国防」指为保卫领土和主权而进行的防御工作，是钱可以投入的对象。"}, {"text": "盘子", "is_correct": false, "explanation": "语义：「盘子」是日常器皿，不是国家财政投入的对象。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：「用在……上」接的是事务或项目，「天气」不能这样搭配。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：「闹钟」是提醒时间的小物件，与国家的财政投入无关。"}], "explanations": {"国防": "正确：「国防」指为保卫领土和主权而进行的防御工作，是钱可以投入的对象。", "盘子": "语义：「盘子」是日常器皿，不是国家财政投入的对象。", "天气": "搭配：「用在……上」接的是事务或项目，「天气」不能这样搭配。", "闹钟": "语义：「闹钟」是提醒时间的小物件，与国家的财政投入无关。"}, "sentence_index": 0, "correct_answer": "国防"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一生都在国防里工作。", "explanation": "这里应该用〈军队〉。国防是保卫国家的工作，不是单位或场所，说「在……里工作」要用〈军队〉。"}, {"text": "他是一名国防，一生守卫边疆。", "explanation": "这里应该用〈军人〉。国防指保卫工作，不能指人，表示人要用〈军人〉。"}, {"text": "国防在边境打响了。", "explanation": "这里应该用〈战斗〉。国防是保卫工作，不是一次交战，不能说「打响」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国防", "is_correct": true, "explanation": "正确：「国防」是国家防御的重要力量，与「军队是……的重要力量」相合。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：「重要力量」通常修饰军队、国家这样的主体，「厨房」不能这样搭配。"}, {"text": "花园", "is_correct": false, "explanation": "语义：「花园」是供人观赏的场所，不是军队力量所及的对象。"}, {"text": "病房", "is_correct": false, "explanation": "语义：「病房」是医院里的房间，与军队的力量无关。"}], "explanations": {"国防": "正确：「国防」是国家防御的重要力量，与「军队是……的重要力量」相合。", "厨房": "搭配：「重要力量」通常修饰军队、国家这样的主体，「厨房」不能这样搭配。", "花园": "语义：「花园」是供人观赏的场所，不是军队力量所及的对象。", "病房": "语义：「病房」是医院里的房间，与军队的力量无关。"}, "sentence_index": 6, "correct_answer": "国防"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "国防在城墙上站岗。", "explanation": "这里应该用〈哨兵〉。国防是抽象的工作，不能在城墙上站岗，表示站岗的人要用〈哨兵〉。"}, {"text": "国防负责维护街道秩序。", "explanation": "这里应该用〈警察〉。国防针对对外防御，维护街道秩序应用〈警察〉。"}, {"text": "我们进行了一场国防。", "explanation": "这里不能用〈场〉计量。国防是抽象概念，不能像一场比赛那样计数，应说「加强国防」之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个国家的国防了力量很重要。", "corrected_sentence": "一个国家的国防力量很重要。", "error_description": "错误形式：「一个国家的国防了力量很重要」；正确形式：「一个国家的国防力量很重要」。「了」表示完成或变化，不能紧接在名词「国防」之后，应去掉「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77cc5bb0-c35a-47d3-80b4-8105d26b9f3a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
