INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92593, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "趁就是抓住一个好时候，赶快去做一件事。", "primary_collocate": null, "pronunciation": "chèn", "ipa": "ʈʂʰən˥˩", "syllable_count": 1, "sentences": [{"text": "趁热吃吧，冷了就不好吃了。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁天还没黑，我们快回家。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁现在还有票，我们赶快去买吧。", "target_word": "趁", "complexity_tier": "T3", "furigana": "chèn xiàn zài hái yǒu piào, wǒ men gǎn kuài qù mǎi ba.", "sentence_source": "generated"}, {"text": "趁着年轻，多去看看世界。", "target_word": "趁着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "趁孩子还在睡觉，妈妈做好了饭。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁现在人少，我们快进去吧。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁商店还没关门，他跑去买牛奶。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁雨还不大，快把衣服收进来。", "target_word": "趁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "趁老师没来，大家快把作业写完。", "target_word": "趁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "趁时间还早，我想先去买点水果。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "趁着", "label": "体标"}, {"form": "趁早", "label": "复合"}, {"form": "趁热", "label": "复合"}], "register": "中性", "sense_fingerprint": "抓紧眼前的好时候，赶快做某事，晚了就不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92593, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确答案。趁（chèn）是介词，表示抓住好时机。"}, {"text": "秤", "is_correct": false, "explanation": "秤 chèng 与 趁 chèn 韵尾不同（eng/en），意思是称重的工具。"}, {"text": "阵", "is_correct": false, "explanation": "阵 zhèn 与 趁 chèn 声母不同（zh/ch），意思是一段时间或一股。"}, {"text": "尘", "is_correct": false, "explanation": "尘 chén 与 趁 chèn 声调不同（第二声与第四声），意思是灰尘。"}, {"text": "陈", "is_correct": false, "explanation": "陈 chén 与 趁 chèn 声调不同，意思是陈旧。"}], "explanations": {"趁": "正确答案。趁（chèn）是介词，表示抓住好时机。", "秤": "秤 chèng 与 趁 chèn 韵尾不同（eng/en），意思是称重的工具。", "阵": "阵 zhèn 与 趁 chèn 声母不同（zh/ch），意思是一段时间或一股。", "尘": "尘 chén 与 趁 chèn 声调不同（第二声与第四声），意思是灰尘。", "陈": "陈 chén 与 趁 chèn 声调不同，意思是陈旧。"}, "sentence_index": null, "correct_answer": "趁"}, "level_3": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确。“趁热吃”表示抓住热的时候吃，符合“冷了就不好吃”。"}, {"text": "在", "is_correct": false, "explanation": "搭配：“在热吃吧”不成立，“热”不能跟“在”组成时间短语。"}, {"text": "从", "is_correct": false, "explanation": "配价：“从”要引出起点，“热吃吧”没有起点可言。"}, {"text": "为", "is_correct": false, "explanation": "语义：“为热吃吧”表达的目的不通，与“冷了就不好吃”的意思不符。"}], "explanations": {"趁": "正确。“趁热吃”表示抓住热的时候吃，符合“冷了就不好吃”。", "在": "搭配：“在热吃吧”不成立，“热”不能跟“在”组成时间短语。", "从": "配价：“从”要引出起点，“热吃吧”没有起点可言。", "为": "语义：“为热吃吧”表达的目的不通，与“冷了就不好吃”的意思不符。"}, "sentence_index": 0, "correct_answer": "趁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天趁地铁上班。", "explanation": "这里应该用〈乘〉。趁表示利用时机，不接交通工具；乘地铁才对。"}, {"text": "我们要趁这台电脑学习外语。", "explanation": "这里应该用〈利用〉。趁表示抓住时机、赶快做事，不能表示使用某件工具；要说“利用这台电脑学习外语”。"}, {"text": "孩子们在草地上趁蝴蝶。", "explanation": "这里应该用〈抓〉。趁只表示利用时机，不能表示捕捉；要说“孩子们在草地上抓蝴蝶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92593, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确答案。趁（chèn）是介词，表示抓住好时机。"}, {"text": "镇", "is_correct": false, "explanation": "镇 zhèn 与 趁 chèn 声母不同（zh/ch），意思是城镇。"}, {"text": "晨", "is_correct": false, "explanation": "晨 chén 与 趁 chèn 声调不同，意思是早晨。"}, {"text": "沉", "is_correct": false, "explanation": "沉 chén 与 趁 chèn 声调不同，意思是向下落。"}], "explanations": {"趁": "正确答案。趁（chèn）是介词，表示抓住好时机。", "镇": "镇 zhèn 与 趁 chèn 声母不同（zh/ch），意思是城镇。", "晨": "晨 chén 与 趁 chèn 声调不同，意思是早晨。", "沉": "沉 chén 与 趁 chèn 声调不同，意思是向下落。"}, "sentence_index": null, "correct_answer": "趁"}, "level_3": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确。“趁商店还没关门”表示抓住商店还没关门的时机去买，符合句意。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对商店还没关门，他跑去买牛奶”不成立。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”后要接方向或对象，不能接“商店还没关门”这样的小句。"}, {"text": "凭", "is_correct": false, "explanation": "搭配：“凭”表示依据，“凭商店还没关门，他跑去买牛奶”搭配不当。"}], "explanations": {"趁": "正确。“趁商店还没关门”表示抓住商店还没关门的时机去买，符合句意。", "对": "语义：“对”引出对象，“对商店还没关门，他跑去买牛奶”不成立。", "向": "配价：“向”后要接方向或对象，不能接“商店还没关门”这样的小句。", "凭": "搭配：“凭”表示依据，“凭商店还没关门，他跑去买牛奶”搭配不当。"}, "sentence_index": 6, "correct_answer": "趁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他趁朋友的车回家。", "explanation": "这里应该用〈搭〉。趁不接交通工具，搭朋友的车才对。"}, {"text": "她每天都在趁工作。", "explanation": "这里应该用〈找〉。趁只表示利用时机，不能表示寻找；要说“她每天都在找工作”。"}, {"text": "我们趁在天黑前回家。", "explanation": "这里应该用〈赶〉。趁是介词，不能与“在”连用，“赶在天黑前回家”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92593, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "趁在店里人少，我们快进去吧。", "corrected_sentence": "趁店里人少，我们快进去吧。", "error_description": "错误：“趁在店里人少”。正确：“趁店里人少”。“趁”是介词，后面不能再加“在”，应直接接时机短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92593, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "趁了水还热，快去洗个澡。", "corrected_sentence": "趁水还热，快去洗个澡。", "error_description": "“趁”是介词，后面不能加“了”。应说“趁水还热”，不能说“趁了水还热”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
