INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92594, 1, 'prompt1_core', '{"pos": "介词", "semantic_class": "function", "definition": "利用有利的时间或机会（做某事）。", "primary_collocate": null, "pronunciation": "chèn", "ipa": "ʈʂʰən˥˩", "syllable_count": 1, "sentences": [{"text": "我想趁周末去爬山。", "target_word": "趁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他趁假期去了一次北京。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁着出差，他看望了老朋友。", "target_word": "趁着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "趁大家都在，我说两句话。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们趁中午休息的时候开会。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁学生放假，老师去外地学习。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她趁打折买了一件新衣服。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁这次机会，我要认识更多的朋友。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁天气好，爷爷带孙子去了公园。", "target_word": "趁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "趁着有空，我把房间打扫干净。", "target_word": "趁着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趁着", "label": "体标"}, {"form": "趁机", "label": "复合"}], "register": "中性", "sense_fingerprint": "利用有利的时间或机会去做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92594, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确答案。趁（chèn）是介词，表示利用有利的时机。"}, {"text": "秤", "is_correct": false, "explanation": "秤 chèng 与 趁 chèn 韵尾不同（eng/en），意思是称重的工具。"}, {"text": "阵", "is_correct": false, "explanation": "阵 zhèn 与 趁 chèn 声母不同（zh/ch），意思是一段时间。"}, {"text": "尘", "is_correct": false, "explanation": "尘 chén 与 趁 chèn 声调不同，意思是灰尘。"}, {"text": "陈", "is_correct": false, "explanation": "陈 chén 与 趁 chèn 声调不同，意思是陈旧。"}], "explanations": {"趁": "正确答案。趁（chèn）是介词，表示利用有利的时机。", "秤": "秤 chèng 与 趁 chèn 韵尾不同（eng/en），意思是称重的工具。", "阵": "阵 zhèn 与 趁 chèn 声母不同（zh/ch），意思是一段时间。", "尘": "尘 chén 与 趁 chèn 声调不同，意思是灰尘。", "陈": "陈 chén 与 趁 chèn 声调不同，意思是陈旧。"}, "sentence_index": null, "correct_answer": "趁"}, "level_3": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确。“趁周末去爬山”表示利用周末的时间去做事，符合句意。"}, {"text": "向", "is_correct": false, "explanation": "配价：“向”要接方向或对象，“周末”不能作它的宾语。"}, {"text": "对", "is_correct": false, "explanation": "语义：“对”引出对象，“对周末去爬山”不成立。"}, {"text": "按", "is_correct": false, "explanation": "搭配：“按”要接“照、根据”一类的词，“按周末去爬山”搭配不当。"}], "explanations": {"趁": "正确。“趁周末去爬山”表示利用周末的时间去做事，符合句意。", "向": "配价：“向”要接方向或对象，“周末”不能作它的宾语。", "对": "语义：“对”引出对象，“对周末去爬山”不成立。", "按": "搭配：“按”要接“照、根据”一类的词，“按周末去爬山”搭配不当。"}, "sentence_index": 0, "correct_answer": "趁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他趁这台烤箱烤面包。", "explanation": "这里应该用〈利用〉。趁表示抓住时机，不能指使用某个设备；要说“他利用这台烤箱烤面包”。"}, {"text": "猫在草地上趁老鼠。", "explanation": "这里应该用〈抓〉。趁只表示利用时机，不能表示捕捉；要说“猫在草地上抓老鼠”。"}, {"text": "狗在院子里趁小猫。", "explanation": "这里应该用〈追〉。趁不能表示追赶，只能指利用时机做事；要说“狗在院子里追小猫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92594, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确答案。趁（chèn）是介词，表示利用有利的时机。"}, {"text": "镇", "is_correct": false, "explanation": "镇 zhèn 与 趁 chèn 声母不同（zh/ch），意思是城镇。"}, {"text": "晨", "is_correct": false, "explanation": "晨 chén 与 趁 chèn 声调不同，意思是早晨。"}, {"text": "沉", "is_correct": false, "explanation": "沉 chén 与 趁 chèn 声调不同，意思是向下落。"}], "explanations": {"趁": "正确答案。趁（chèn）是介词，表示利用有利的时机。", "镇": "镇 zhèn 与 趁 chèn 声母不同（zh/ch），意思是城镇。", "晨": "晨 chén 与 趁 chèn 声调不同，意思是早晨。", "沉": "沉 chén 与 趁 chèn 声调不同，意思是向下落。"}, "sentence_index": null, "correct_answer": "趁"}, "level_3": {"options": [{"text": "趁", "is_correct": true, "explanation": "正确。“趁打折买”表示利用打折的机会去买，符合句意。"}, {"text": "由", "is_correct": false, "explanation": "搭配：“由打折买了一件衣服”搭配不当，“由”不能这样用。"}, {"text": "朝", "is_correct": false, "explanation": "配价：“朝”要接方向，“打折”不能作它的宾语。"}, {"text": "经", "is_correct": false, "explanation": "语义：“经打折买”表达的意思不通，与句子所说的利用机会不符。"}], "explanations": {"趁": "正确。“趁打折买”表示利用打折的机会去买，符合句意。", "由": "搭配：“由打折买了一件衣服”搭配不当，“由”不能这样用。", "朝": "配价：“朝”要接方向，“打折”不能作它的宾语。", "经": "语义：“经打折买”表达的意思不通，与句子所说的利用机会不符。"}, "sentence_index": 6, "correct_answer": "趁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天趁公交车上班。", "explanation": "这里应该用〈坐〉。趁不接交通工具，坐公交车上班才对。"}, {"text": "她每天都在趁工作。", "explanation": "这里应该用〈找〉。趁只表示利用时机，不能表示寻找；要说“她每天都在找工作”。"}, {"text": "我们趁在天黑前回家。", "explanation": "这里应该用〈赶〉。趁是介词，不能与“在”连用，“赶在天黑前回家”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "趁了天还亮，我们去河边散步吧。", "corrected_sentence": "趁天还亮，我们去河边散步吧。", "error_description": "“趁”是介词，后面不能加“了”。应说“趁天还亮”，不能说“趁了天还亮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "趁过饭还热，快来吃吧。", "corrected_sentence": "趁饭还热，快来吃吧。", "error_description": "“趁”是介词，后面不能加“过”。应说“趁饭还热”，不能说“趁过饭还热”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
