INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92595, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "婴儿是刚生下来不久的小宝宝。", "primary_collocate": null, "pronunciation": "yīng ér", "ipa": "iŋ˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "这个婴儿刚出生三天。", "target_word": "婴儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "婴儿在床上睡觉。", "target_word": "婴儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈抱着婴儿走进房间。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有几个刚出生的婴儿。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿哭了，妈妈马上去看。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "护士给婴儿洗了一个澡。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个婴儿的眼睛又大又圆。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的婴儿才出生一个月。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "婴儿需要喝牛奶，也需要多睡觉。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚生下一个婴儿，全家都很高兴。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个婴儿", "label": "量词"}, {"form": "婴儿车", "label": "复合"}, {"form": "婴儿床", "label": "复合"}, {"form": "新生婴儿", "label": "复合"}], "register": "中性", "sense_fingerprint": "刚出生不久的小宝宝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92595, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婴儿", "is_correct": true, "explanation": "正确。婴儿指刚出生不久的小孩，与“刚出生三天”相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人指年纪大的人，不可能“刚出生三天”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“出生”只用于人或动物，不能说“桌子刚出生”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生指在校读书的人，不会刚出生三天。"}], "explanations": {"婴儿": "正确。婴儿指刚出生不久的小孩，与“刚出生三天”相符。", "老人": "语义：老人指年纪大的人，不可能“刚出生三天”。", "桌子": "搭配：“出生”只用于人或动物，不能说“桌子刚出生”。", "学生": "语义：学生指在校读书的人，不会刚出生三天。"}, "sentence_index": 0, "correct_answer": "婴儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我侄子今年三岁了，已经是一个婴儿了。", "explanation": "这里应该用〈幼儿〉。婴儿指刚出生不久的孩子，三岁的孩子要说幼儿。"}, {"text": "他已经上小学了，是一名婴儿。", "explanation": "这里应该用〈儿童〉。婴儿只指刚出生不久的孩子，上小学的人要说儿童。"}, {"text": "我们家养了一只婴儿。", "explanation": "这里应该用〈个〉。量词“只”多用于动物，指人要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92595, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婴儿", "is_correct": true, "explanation": "正确。“眼睛又大又圆”描写的是婴儿这样的小孩子。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有眼睛，不能说“眼睛又大又圆”。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“眼睛”只用于有眼睛的人或动物，不能说冰箱的眼睛。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有眼睛，句子描写的是有眼睛的生物。"}], "explanations": {"婴儿": "正确。“眼睛又大又圆”描写的是婴儿这样的小孩子。", "石头": "语义：石头没有眼睛，不能说“眼睛又大又圆”。", "冰箱": "搭配：“眼睛”只用于有眼睛的人或动物，不能说冰箱的眼睛。", "窗户": "语义：窗户没有眼睛，句子描写的是有眼睛的生物。"}, "sentence_index": 6, "correct_answer": "婴儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她还怀着一个婴儿，还没出生呢。", "explanation": "这里应该用〈胎儿〉。婴儿指已经出生的孩子，还在母体里的要说胎儿。"}, {"text": "她刚生下一条婴儿，全家都很高兴。", "explanation": "这里应该用〈个〉。量词“条”用于细长的东西，不能用于人。"}, {"text": "这位大学生已经能自己做饭了，是个婴儿。", "explanation": "这里应该用〈成年人〉。婴儿指刚出生不久的孩子，会自己做饭的大学生已经是成年人，不能叫婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92595, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士抱来了两婴儿。", "corrected_sentence": "护士抱来了两个婴儿。", "error_description": "“两”和名词之间漏了量词。应说“两个婴儿”，不能说“两婴儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92595, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只婴儿刚学会翻身。", "corrected_sentence": "这个婴儿刚学会翻身。", "error_description": "“婴儿”指人，量词应用“个”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
