INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出生不久、还不会走路说话的小孩子。", "primary_collocate": null, "pronunciation": "yīng ér", "ipa": "iŋ˥ ɚ˧˥", "syllable_count": 2, "sentences": [{"text": "婴儿还不会走路。", "target_word": "婴儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个婴儿还不会说话。", "target_word": "婴儿", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "婴儿只会哭，不会告诉你哪里难受。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个婴儿爬着去拿玩具。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿不会自己吃饭，要大人喂。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有个婴儿，正在学着爬。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿听不懂话，但喜欢听妈妈的声音。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位爸爸一只手抱着婴儿，一只手拿包。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婴儿不能自己站起来，需要大人扶。", "target_word": "婴儿", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着对婴儿说话，婴儿也笑了。", "target_word": "婴儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个婴儿", "label": "量词"}, {"form": "婴儿车", "label": "复合"}, {"form": "婴儿床", "label": "复合"}], "register": "中性", "sense_fingerprint": "还不会走路、不会说话、需要大人照顾的小孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "婴儿", "is_correct": true, "explanation": "正确。婴儿指还不会走路的小孩，与“还不会走路”相符。"}, {"text": "大学生", "is_correct": false, "explanation": "语义：大学生早已会走路，不可能“还不会走路”。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“走路”的主语应是人或动物，电脑不能说“走路”。"}, {"text": "运动员", "is_correct": false, "explanation": "语义：运动员不可能还不会走路。"}], "explanations": {"婴儿": "正确。婴儿指还不会走路的小孩，与“还不会走路”相符。", "大学生": "语义：大学生早已会走路，不可能“还不会走路”。", "电脑": "搭配：“走路”的主语应是人或动物，电脑不能说“走路”。", "运动员": "语义：运动员不可能还不会走路。"}, "sentence_index": 0, "correct_answer": "婴儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个婴儿已经能自己走路去上学了。", "explanation": "这里应该用〈小学生〉。婴儿还不会走路，不能自己走路去上学。"}, {"text": "妈妈给我买了一台婴儿。", "explanation": "这里应该用〈个〉。量词“台”用于机器，指人要用“个”。"}, {"text": "我的婴儿已经能自己穿衣服了。", "explanation": "这里应该用〈孩子〉。婴儿还不会自己穿衣，能自己穿衣的要说孩子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "婴儿", "is_correct": true, "explanation": "正确。婴儿听不懂话，但喜欢听妈妈的声音，主语是会听会感觉的小孩。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感觉，不会“喜欢听”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“听不懂话”和“喜欢”的主语必须是有生命的，汽车不能这样说。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会听，也不会喜欢任何声音。"}], "explanations": {"婴儿": "正确。婴儿听不懂话，但喜欢听妈妈的声音，主语是会听会感觉的小孩。", "石头": "语义：石头没有感觉，不会“喜欢听”。", "汽车": "搭配：“听不懂话”和“喜欢”的主语必须是有生命的，汽车不能这样说。", "窗户": "语义：窗户不会听，也不会喜欢任何声音。"}, "sentence_index": 6, "correct_answer": "婴儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她买了一辆婴儿，放在门口。", "explanation": "这里应该用〈个〉。量词“辆”用于车辆，指人要用“个”。"}, {"text": "这个婴儿已经会说很多话了。", "explanation": "这里应该用〈幼儿〉。婴儿还不会说话，已经会说很多话的要说幼儿。"}, {"text": "放学以后，婴儿要自己写作业。", "explanation": "这里应该用〈中学生〉。婴儿还不会写字，写作业的要说中学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那两婴儿还不会说话。", "corrected_sentence": "那两个婴儿还不会说话。", "error_description": "“两”和名词之间漏了量词。应说“两个婴儿”，不能说“两婴儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只婴儿总是要人抱着。", "corrected_sentence": "这个婴儿总是要人抱着。", "error_description": "“婴儿”指人，量词应用“个”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "达不到是怎么努力也没有到那个样子。", "primary_collocate": null, "pronunciation": "dá bú dào", "ipa": "ta˧˥ pu˧˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "我再努力，也达不到他的水平。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个目标太高，我怎么练都达不到。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写得很好，我一直达不到那样。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管怎么学，她的成绩还是达不到九十分。", "target_word": "达不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么难的要求，谁都达不到。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我跑得太慢，怎么也达不到老师的要求。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟想当第一名，可是总达不到。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的汉语说得很好，我还达不到那个样子。", "target_word": "达不到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的画怎么画都达不到爸爸的水平。", "target_word": "达不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这首歌我练了很久，还是达不到原唱的感觉。", "target_word": "达不到", "complexity_tier": "T3", "furigana": "zhè shǒu gē wǒ liàn le hěn jiǔ, hái shì dá bu dào yuán chàng de gǎn jué.", "sentence_source": "generated"}], "morphological_forms": [{"form": "达得到", "label": "可能补语肯定式"}, {"form": "達不到", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词；再努力也够不上某个水平或样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "达不到", "is_correct": true, "explanation": "达不到（dá bú dào）：再努力也够不上某个水平或样子，是本词。"}, {"text": "拿不到", "is_correct": false, "explanation": "拿（ná）与达（dá）声母不同（n 与 d），意思是拿不到东西，不是够不上水平。"}, {"text": "打不到", "is_correct": false, "explanation": "打（dǎ）与达（dá）声调不同（第三声与第二声），意思是打不着，不是达不到水平。"}, {"text": "搭不到", "is_correct": false, "explanation": "搭（dā）与达（dá）声调不同（第一声与第二声），意思是搭不到车，不是达不到水平。"}], "explanations": {"达不到": "达不到（dá bú dào）：再努力也够不上某个水平或样子，是本词。", "拿不到": "拿（ná）与达（dá）声母不同（n 与 d），意思是拿不到东西，不是够不上水平。", "打不到": "打（dǎ）与达（dá）声调不同（第三声与第二声），意思是打不着，不是达不到水平。", "搭不到": "搭（dā）与达（dá）声调不同（第一声与第二声），意思是搭不到车，不是达不到水平。"}, "sentence_index": null, "correct_answer": "达不到"}, "level_3": {"options": [{"text": "达不到", "is_correct": true, "explanation": "“再努力，也”之后需要表示没能达到某个水平，达不到符合。"}, {"text": "看见", "is_correct": false, "explanation": "语义：看见是视觉上的感知，水平不能被看见，句子不通。"}, {"text": "听懂", "is_correct": false, "explanation": "搭配：“听懂”的对象是话语或内容，不能与“水平”搭配。"}, {"text": "摸到", "is_correct": false, "explanation": "语义：摸到指用手碰到具体的东西，水平是抽象的，句子语义不通。"}], "explanations": {"达不到": "“再努力，也”之后需要表示没能达到某个水平，达不到符合。", "看见": "语义：看见是视觉上的感知，水平不能被看见，句子不通。", "听懂": "搭配：“听懂”的对象是话语或内容，不能与“水平”搭配。", "摸到": "语义：摸到指用手碰到具体的东西，水平是抽象的，句子语义不通。"}, "sentence_index": 0, "correct_answer": "达不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想帮你这个忙，可惜达不到。", "explanation": "这里应该用〈做不到〉。“达不到”指没能达到水平或标准，帮忙办不成事要用做不到，不能用达不到。"}, {"text": "这盘菜很好吃，我一口就达不到。", "explanation": "这里应该用〈吃完〉。“达不到”指没能达到水平或标准，一口吃完菜要用吃完，不能用达不到。"}, {"text": "这幅画太大，我一个月也达不到。", "explanation": "这里应该用〈画完〉。“达不到”指没能达到水平或标准，把一幅画画完不能用达不到，要用画完。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "达不到", "is_correct": true, "explanation": "“可是总”之后需要表示没能实现目标，达不到符合。"}, {"text": "吃饱", "is_correct": false, "explanation": "语义：吃饱与想当第一名的追求无关，句子语义不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌是一种活动，不能说明“想当第一名”的结果，句子不通。"}, {"text": "长高", "is_correct": false, "explanation": "体貌：“长高”说的是身体变化，与“想当第一名”这种能力上的追求不符。"}], "explanations": {"达不到": "“可是总”之后需要表示没能实现目标，达不到符合。", "吃饱": "语义：吃饱与想当第一名的追求无关，句子语义不通。", "唱歌": "语义：唱歌是一种活动，不能说明“想当第一名”的结果，句子不通。", "长高": "体貌：“长高”说的是身体变化，与“想当第一名”这种能力上的追求不符。"}, "sentence_index": 6, "correct_answer": "达不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信写得很长，我一晚上就达不到。", "explanation": "这里应该用〈读完〉。“达不到”指没能达到水平或标准，一晚上把一封信读完不能用达不到，要用读完。"}, {"text": "他一个星期就达不到作业。", "explanation": "这里应该用〈完成〉。“达不到”说的是没能达到水平或要求，不能用来说做完作业。"}, {"text": "我终于达不到这个道理。", "explanation": "这里应该用〈理解〉。“达不到”用于水平或标准，不能用来说理解了道理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一直努力，还是达不到过计划的速度。", "corrected_sentence": "我们一直努力，还是达不到计划的速度。", "error_description": "体标错误：“达不到”是可能补语否定式，表示无法实现，不能再带体标“过”；应删去“过”，说“达不到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么快的速度，我们还是达不到那条目标。", "corrected_sentence": "这么快的速度，我们还是达不到那个目标。", "error_description": "量词错误：“目标”应用“个”；“条”多用于细长的东西或某些条目，不能用于目标。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
