INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92599, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "周日是星期天，大家常常在家里休息。", "primary_collocate": null, "pronunciation": "zhōu rì", "ipa": "ʈʂoʊ˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "周日大家常常在家里休息。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周六打球，周日睡懒觉。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这个周日去公园玩吧。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日商店里的人特别多。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上个周日我在家看了一天电影。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天星期六，明天就是周日了。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日早上妈妈常常做面条。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个周日是我的生日，请你来我家吧。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日不上班，爸爸在家做饭。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日晚上我要早点睡，因为周一要上课。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上周日", "label": "复合"}, {"form": "下周日", "label": "复合"}, {"form": "週日", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周日：星期天，大家常在家休息的一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92599, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图书馆", "is_correct": false, "explanation": "配价：“休息”要求人作主语，图书馆是场所，不能作“大家……休息”的施事，也与“在家里”矛盾。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是工作的地方，与“在家里休息”的句意相反。"}, {"text": "周日", "is_correct": true, "explanation": "正确：周日指星期天，是大家常在家休息的日子，符合句意。"}, {"text": "饭店", "is_correct": false, "explanation": "语义：饭店是营业场所，不是家，与“在家里休息”冲突。"}], "explanations": {"图书馆": "配价：“休息”要求人作主语，图书馆是场所，不能作“大家……休息”的施事，也与“在家里”矛盾。", "工厂": "语义：工厂是工作的地方，与“在家里休息”的句意相反。", "周日": "正确：周日指星期天，是大家常在家休息的日子，符合句意。", "饭店": "语义：饭店是营业场所，不是家，与“在家里休息”冲突。"}, "sentence_index": 0, "correct_answer": "周日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周日放了两天假，大家都很开心。", "explanation": "这里应该用〈周末〉。周末包括周六和周日两天，周日只指一天，不能说放了两天假。"}, {"text": "周日只有两天，我们都在家。", "explanation": "这里应该用〈双休日〉。双休日指周六和周日两天，周日只指一天，不能说只有两天。"}, {"text": "这个周日有两周的时间。", "explanation": "这里应该用〈假期〉。假期指一段时间，周日只指一天，不能说有两周的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92599, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不表示时间，不能与“早上”组成时间状语。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是地点，不表示时间，不能作句首的时间词。"}, {"text": "书包", "is_correct": false, "explanation": "配价：“书包”不能作“做面条”的施事，与“妈妈常常做”的结构不协调。"}, {"text": "周日", "is_correct": true, "explanation": "正确：周日指星期天，这里表示时间，符合句意。"}], "explanations": {"冰箱": "语义：冰箱是家电，不表示时间，不能与“早上”组成时间状语。", "教室": "语义：教室是地点，不表示时间，不能作句首的时间词。", "书包": "配价：“书包”不能作“做面条”的施事，与“妈妈常常做”的结构不协调。", "周日": "正确：周日指星期天，这里表示时间，符合句意。"}, "sentence_index": 6, "correct_answer": "周日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周日有三个月，我们可以去旅行。", "explanation": "这里应该用〈寒假〉。寒假指一段时间，周日只指一天，不能说有三个月。"}, {"text": "这个周日只有三天，我们都去了海边。", "explanation": "这里应该用〈节假日〉。节假日指一段假期，周日只指一天，不能说只有三天。"}, {"text": "周日有七天，大家都出去玩。", "explanation": "这里应该用〈黄金周〉。黄金周是一段七天的假期，周日只指一天，不能说有七天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92599, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台周日我们去公园玩吧。", "corrected_sentence": "这个周日我们去公园玩吧。", "error_description": "量词错误：“周日”前应用“个”，说“这个周日”，不能用“台”。“台”多用于机器、电器等，不用来计量日子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92599, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只周日我们去爬山。", "corrected_sentence": "这个周日我们去爬山。", "error_description": "量词错误：“周日”前应用“个”，说“这个周日”，不能用“只”。“只”多用于动物或成对、成只的东西，不用来计量日子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
