INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92600, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "星期日，一周七天中的最后一天，通常为休息日。", "primary_collocate": null, "pronunciation": "zhōu rì", "ipa": "ʈʂoʊ˥ ʐʅ˥˩", "syllable_count": 2, "sentences": [{"text": "周日是一周的最后一天。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日通常不用上班。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周一到周五上班，周六和周日休息。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周日学校不上课。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日图书馆开到晚上八点。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个周日都去爬山。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日下午我们一起去看电影，好吗？", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日那天，她和朋友在咖啡店聊天。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的第一个周日，天气特别好。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日晚上，孩子们要准备下周的作业。", "target_word": "周日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上周日", "label": "复合"}, {"form": "下周日", "label": "复合"}, {"form": "週日", "label": "繁体"}], "register": "中性", "sense_fingerprint": "周日：一周七天中的最后一天，通常为休息日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92600, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "周一", "is_correct": false, "explanation": "语义：周一是一周的第一天，不是最后一天，与句意相反。"}, {"text": "春节", "is_correct": false, "explanation": "搭配：“一周的最后一天”要用表示一周内日子的词，“春节”是节日名称，不能这样搭配。"}, {"text": "月底", "is_correct": false, "explanation": "语义：月底指一个月的末尾，不指一周，与“一周的最后一天”冲突。"}, {"text": "周日", "is_correct": true, "explanation": "正确：周日是一周中的最后一天，符合句意。"}], "explanations": {"周一": "语义：周一是一周的第一天，不是最后一天，与句意相反。", "春节": "搭配：“一周的最后一天”要用表示一周内日子的词，“春节”是节日名称，不能这样搭配。", "月底": "语义：月底指一个月的末尾，不指一周，与“一周的最后一天”冲突。", "周日": "正确：周日是一周中的最后一天，符合句意。"}, "sentence_index": 0, "correct_answer": "周日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个周日有七天。", "explanation": "这里应该用〈长假〉。长假是一段较长的时间，周日只指一天，不能说有七天。"}, {"text": "这个周日只有两天，我们都在家。", "explanation": "这里应该用〈周末〉。周末包括周六和周日两天，周日只指一天，不能说只有两天。"}, {"text": "我们在周日放了两个月的假。", "explanation": "这里应该用〈暑假〉。暑假指一段较长的时间，周日只指一天，不能说放了两个月的假。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不是时间，不能作句首的时间词。"}, {"text": "地铁", "is_correct": false, "explanation": "配价：“我们一起去看电影”的主语应是人，地铁不能作这一动作的主语。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不表示时间，与“下午……去看电影”的句意不通。"}, {"text": "周日", "is_correct": true, "explanation": "正确：周日表示时间，句子是提议在周日下午一起看电影，符合句意。"}], "explanations": {"厨房": "语义：厨房是做饭的地方，不是时间，不能作句首的时间词。", "地铁": "配价：“我们一起去看电影”的主语应是人，地铁不能作这一动作的主语。", "作业": "语义：作业不表示时间，与“下午……去看电影”的句意不通。", "周日": "正确：周日表示时间，句子是提议在周日下午一起看电影，符合句意。"}, "sentence_index": 6, "correct_answer": "周日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周日有三个月，我们可以去旅行。", "explanation": "这里应该用〈寒假〉。寒假指一段时间，周日只指一天，不能说有三个月。"}, {"text": "这个周日有三天，我们都去了海边。", "explanation": "这里应该用〈连休〉。连休指连着休息的几天，周日只指一天，不能说有三天。"}, {"text": "这次假期有一个周日那么长。", "explanation": "这里应该用〈一个月〉。周日只指一天，不能用来衡量一段较长的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只周日我想去看展览。", "corrected_sentence": "这个周日我想去看展览。", "error_description": "量词错误：“周日”前应用“个”，说“这个周日”，不能用“只”，“只”不用来计量日子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92600, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台周日晚上我要洗衣服。", "corrected_sentence": "这个周日晚上我要洗衣服。", "error_description": "量词错误：“周日”前应用“个”，说“这个周日晚上”，不能用“台”。“台”多用于机器、电器等，不用来计量日子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
