INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92605, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "宣言是把自己想做的事大声说出来的话。", "primary_collocate": null, "pronunciation": "xuān yán", "ipa": "ɕɥɛn˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "新年到了，他写下了减肥宣言。", "target_word": "宣言", "complexity_tier": "T3", "furigana": "xuān yán", "sentence_source": "generated"}, {"text": "全班同学一起大声读出了班级宣言。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这是我们小组的宣言：绝不迟到！", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的宣言是：我要当宇航员。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在朋友面前大声说出了自己的宣言。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的新年宣言是每天跑步三十分钟。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛前，队长带大家喊出了队伍的宣言。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们写下自己的宣言，贴在了墙上。", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸听了女儿的宣言，笑着点了点头。", "target_word": "宣言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的宣言很简单：我再也不玩游戏了！", "target_word": "宣言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "独立宣言", "label": "复合"}], "register": "中性", "sense_fingerprint": "把自己想做的事大声说出来的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fda20375-ed58-4eb8-96ba-b11b06ce9777') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92605, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宣言", "is_correct": true, "explanation": "正确。“宣言”指大声说出想做的事，与“写下了减肥……”相符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”是测量结果，不能说“写下了减肥体重”。"}, {"text": "积木", "is_correct": false, "explanation": "语义：“积木”是玩具，与“减肥”毫不相干，句意不通。"}, {"text": "草地", "is_correct": false, "explanation": "语义：“草地”是地面，不能被“写下”作为减肥的内容，句意荒谬。"}], "explanations": {"宣言": "正确。“宣言”指大声说出想做的事，与“写下了减肥……”相符。", "体重": "搭配：“体重”是测量结果，不能说“写下了减肥体重”。", "积木": "语义：“积木”是玩具，与“减肥”毫不相干，句意不通。", "草地": "语义：“草地”是地面，不能被“写下”作为减肥的内容，句意荒谬。"}, "sentence_index": 0, "correct_answer": "宣言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把宣言放进了冰箱。", "explanation": "这里应该用〈饮料〉。宣言是说出来的话，不能放进冰箱。"}, {"text": "妈妈给我们盛了一碗宣言。", "explanation": "这里应该用〈汤〉。宣言是说出来的话，不能盛在碗里。"}, {"text": "他一口气把宣言吃光了。", "explanation": "这里应该用〈饭〉。宣言是说出来的话，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92605, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宣言", "is_correct": true, "explanation": "正确。“宣言”是大声喊出的话，与“队长带大家喊出了队伍的……”相符。"}, {"text": "座位", "is_correct": false, "explanation": "语义：“座位”不能被喊出，句意荒谬。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”不能被喊出，与比赛前喊口号的语境无关。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“喊出”一般搭配口号、声音，不能说“喊出作业”。"}], "explanations": {"宣言": "正确。“宣言”是大声喊出的话，与“队长带大家喊出了队伍的……”相符。", "座位": "语义：“座位”不能被喊出，句意荒谬。", "书包": "语义：“书包”不能被喊出，与比赛前喊口号的语境无关。", "作业": "搭配：“喊出”一般搭配口号、声音，不能说“喊出作业”。"}, "sentence_index": 6, "correct_answer": "宣言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给大家画了一个宣言。", "explanation": "这里应该用〈画〉。宣言是公开发表的主张，不能用“画”来表示。"}, {"text": "妈妈给孩子唱宣言。", "explanation": "这里应该用〈歌〉。宣言是公开发表的主张，不能“唱”。"}, {"text": "小明写了一束宣言，贴在门上。", "explanation": "这里应该用〈份〉。〈束〉用于花、捆扎的东西，宣言是书面文件，量词要用“份”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92605, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班写了一座宣言。", "corrected_sentence": "我们班写了一份宣言。", "error_description": "错误形式：“一座宣言”。正确形式：“一份宣言”。“座”只用于山、桥、楼房等大型固定物，宣言是书面文件，量词要用“份”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92605, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生们把这份宣言们贴在了墙上。", "corrected_sentence": "学生们把这份宣言贴在了墙上。", "error_description": "错误形式：“宣言们”。正确形式：“宣言”。“们”只用于指人的名词，不能加在“宣言”这类书面文件后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ff1b51b-fc56-4f3c-8ea4-2c960b485b7b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
