INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92609, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宝宝是很小的孩子。", "primary_collocate": null, "pronunciation": "bǎo bao", "ipa": "pɑʊ˨˩ pɑʊ", "syllable_count": 2, "sentences": [{"text": "我家的宝宝今年一岁了。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝睡着了，请小声说话。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个宝宝很爱笑。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天给宝宝洗澡。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝饿了，妈妈给他喝牛奶。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有很多刚出生的宝宝。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店卖宝宝穿的衣服。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝会走路以后，家里更热闹了。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她抱着宝宝在公园里散步。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝哭了，爸爸马上去看他。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宝宝们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "寶寶", "label": "繁体"}], "register": "口语", "sense_fingerprint": "很小的孩子，指婴幼儿本人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '230f03da-1729-41ca-a1ac-3cb91ec386f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92609, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宝宝", "is_correct": true, "explanation": "宝宝（bǎo bao）指很小的孩子，是听到的目标词。"}, {"text": "包包", "is_correct": false, "explanation": "bāo（第一声）与 bǎo（第三声）声调不同，包包指包（袋子），不是小孩。"}, {"text": "抱抱", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，抱抱指拥抱，不是小孩。"}, {"text": "泡泡", "is_correct": false, "explanation": "pào（第四声）与 bǎo（第三声）声调不同，泡泡指水或肥皂形成的小泡，不是小孩。"}, {"text": "跑跑", "is_correct": false, "explanation": "pǎo 与 bǎo 声母不同（p 与 b），跑跑指来回跑动，不是小孩。"}], "explanations": {"宝宝": "宝宝（bǎo bao）指很小的孩子，是听到的目标词。", "包包": "bāo（第一声）与 bǎo（第三声）声调不同，包包指包（袋子），不是小孩。", "抱抱": "bào（第四声）与 bǎo（第三声）声调不同，抱抱指拥抱，不是小孩。", "泡泡": "pào（第四声）与 bǎo（第三声）声调不同，泡泡指水或肥皂形成的小泡，不是小孩。", "跑跑": "pǎo 与 bǎo 声母不同（p 与 b），跑跑指来回跑动，不是小孩。"}, "sentence_index": null, "correct_answer": "宝宝"}, "level_3": {"options": [{"text": "宝宝", "is_correct": true, "explanation": "宝宝指很小的孩子，与“今年一岁了”相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人指年纪大的人，与“今年一岁了”矛盾。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是上学的人，一岁的孩子不可能是学生。"}, {"text": "相片", "is_correct": false, "explanation": "搭配：“相片”没有年龄，“一岁了”只能用于有生命的人或动物。"}], "explanations": {"宝宝": "宝宝指很小的孩子，与“今年一岁了”相符。", "老人": "语义：老人指年纪大的人，与“今年一岁了”矛盾。", "学生": "语义：学生是上学的人，一岁的孩子不可能是学生。", "相片": "搭配：“相片”没有年龄，“一岁了”只能用于有生命的人或动物。"}, "sentence_index": 0, "correct_answer": "宝宝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所中学的宝宝每天早上七点到校。", "explanation": "这里应该用〈学生〉。宝宝指很小的婴幼儿，中学生不能叫宝宝。"}, {"text": "宝宝需要在法庭上如实作证。", "explanation": "这里应该用〈证人〉。宝宝指很小的婴幼儿，不能出庭作证。"}, {"text": "在超市的收银台，宝宝正在付款。", "explanation": "这里应该用〈顾客〉。宝宝指很小的婴幼儿，结账付款的人要说“顾客”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92609, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宝宝", "is_correct": true, "explanation": "宝宝指婴幼儿，商店卖的是给婴儿穿的衣服，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不穿衣服，“穿的衣服”不能指给石头穿的衣服。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不穿衣服，这句话说的是给人穿的衣服。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“穿的衣服”要求穿衣服的对象，“课本”不能穿衣服，搭配不当。"}], "explanations": {"宝宝": "宝宝指婴幼儿，商店卖的是给婴儿穿的衣服，与句意相符。", "石头": "语义：石头不穿衣服，“穿的衣服”不能指给石头穿的衣服。", "椅子": "语义：椅子不穿衣服，这句话说的是给人穿的衣服。", "课本": "搭配：“穿的衣服”要求穿衣服的对象，“课本”不能穿衣服，搭配不当。"}, "sentence_index": 6, "correct_answer": "宝宝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位宝宝是国家队的射击选手，刚拿了金牌。", "explanation": "这里应该用〈运动员〉。宝宝指很小的婴幼儿，不能指成年的运动员。"}, {"text": "这篇论文的作者是宝宝，已经发表在核心期刊上。", "explanation": "这里应该用〈研究人员〉。宝宝指很小的婴幼儿，不能作为论文作者。"}, {"text": "公司里的宝宝都要交社保。", "explanation": "这里应该用〈成年人〉。宝宝指很小的婴幼儿，不能用来指成年职工。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家来了一只宝宝。", "corrected_sentence": "我家来了一个宝宝。", "error_description": "量词错误：“宝宝”指人，应说“一个宝宝”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个宝宝们在睡觉。", "corrected_sentence": "三个宝宝在睡觉。", "error_description": "复数错误：“们”不能与数词连用，数量词后直接说“三个宝宝”，不说“宝宝们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
