INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92610, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对婴幼儿的爱称。", "primary_collocate": null, "pronunciation": "bǎo bao", "ipa": "pɑʊ˨˩ pɑʊ", "syllable_count": 2, "sentences": [{"text": "宝宝，别哭了，妈妈在这儿。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝乖，我们该睡觉了。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“宝宝，快来吃饭。”", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝，今天在幼儿园开心吗？", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶笑着叫他“宝宝”。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸对孩子说：“宝宝，你真棒！”", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝，来，妈妈抱抱你。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝，天冷了，把外套穿上。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝，别怕，爸爸陪着你。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝，生日快乐！爸爸妈妈爱你。", "target_word": "宝宝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宝宝们", "label": "复数"}, {"form": "个", "label": "量词"}, {"form": "寶寶", "label": "繁体"}], "register": "口语", "sense_fingerprint": "大人亲昵地称呼小孩的叫法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '230f03da-1729-41ca-a1ac-3cb91ec386f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92610, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宝宝", "is_correct": true, "explanation": "宝宝（bǎo bao）是大人对婴幼儿的爱称，是听到的目标词。"}, {"text": "包包", "is_correct": false, "explanation": "bāo（第一声）与 bǎo（第三声）声调不同，包包指包（袋子），不是爱称。"}, {"text": "抱抱", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，抱抱指拥抱，不是爱称。"}, {"text": "泡泡", "is_correct": false, "explanation": "pào（第四声）与 bǎo（第三声）声调不同，泡泡指水或肥皂形成的小泡。"}, {"text": "跑跑", "is_correct": false, "explanation": "pǎo 与 bǎo 声母不同（p 与 b），跑跑指来回跑动。"}], "explanations": {"宝宝": "宝宝（bǎo bao）是大人对婴幼儿的爱称，是听到的目标词。", "包包": "bāo（第一声）与 bǎo（第三声）声调不同，包包指包（袋子），不是爱称。", "抱抱": "bào（第四声）与 bǎo（第三声）声调不同，抱抱指拥抱，不是爱称。", "泡泡": "pào（第四声）与 bǎo（第三声）声调不同，泡泡指水或肥皂形成的小泡。", "跑跑": "pǎo 与 bǎo 声母不同（p 与 b），跑跑指来回跑动。"}, "sentence_index": null, "correct_answer": "宝宝"}, "level_3": {"options": [{"text": "宝宝", "is_correct": true, "explanation": "宝宝是对小孩的亲昵称呼，与“别哭了，妈妈在这儿”相符。"}, {"text": "同学", "is_correct": false, "explanation": "语义：同学是同龄人，对同学说“妈妈在这儿”不合情理。"}, {"text": "大叔", "is_correct": false, "explanation": "语义：大叔是成年男子，不需要“妈妈在这儿”来安慰。"}, {"text": "老头", "is_correct": false, "explanation": "语域：“老头”口语化且带贬义，不适合用于安慰哭泣的人。"}], "explanations": {"宝宝": "宝宝是对小孩的亲昵称呼，与“别哭了，妈妈在这儿”相符。", "同学": "语义：同学是同龄人，对同学说“妈妈在这儿”不合情理。", "大叔": "语义：大叔是成年男子，不需要“妈妈在这儿”来安慰。", "老头": "语域：“老头”口语化且带贬义，不适合用于安慰哭泣的人。"}, "sentence_index": 0, "correct_answer": "宝宝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宝宝，您好，请问车站在哪儿？", "explanation": "这里应该用〈先生〉。宝宝是亲昵的称呼，对陌生人用它不恰当。"}, {"text": "宝宝，您辛苦了，谢谢您。", "explanation": "这里应该用〈老师〉。宝宝只用于亲昵地称呼小孩，对老师要用尊敬的称呼。"}, {"text": "根据协议第三条，宝宝应于十日内付款。", "explanation": "这里应该用〈乙方〉。宝宝是亲昵的称呼，不能用作合同中的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92610, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宝宝", "is_correct": true, "explanation": "宝宝是对小孩的亲昵称呼，与“来，妈妈抱抱你”相符。"}, {"text": "叔叔", "is_correct": false, "explanation": "语义：叔叔是成年男子，妈妈不会对他说“来，妈妈抱抱你”。"}, {"text": "领导", "is_correct": false, "explanation": "语域：“领导”是正式称呼，不能用于“妈妈抱抱你”这种亲昵语境。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察是成年人，与“妈妈抱抱你”的对象不合。"}], "explanations": {"宝宝": "宝宝是对小孩的亲昵称呼，与“来，妈妈抱抱你”相符。", "叔叔": "语义：叔叔是成年男子，妈妈不会对他说“来，妈妈抱抱你”。", "领导": "语域：“领导”是正式称呼，不能用于“妈妈抱抱你”这种亲昵语境。", "警察": "语义：警察是成年人，与“妈妈抱抱你”的对象不合。"}, "sentence_index": 6, "correct_answer": "宝宝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝宝，欢迎您来我们公司。", "explanation": "这里应该用〈领导〉。宝宝是亲昵称呼，对领导要用正式的称呼。"}, {"text": "宝宝，请给我一杯水。", "explanation": "这里应该用〈服务员〉。宝宝是亲昵的称呼，对陌生的服务员应礼貌称呼。"}, {"text": "据警方通报，宝宝已被抓获。", "explanation": "这里应该用〈嫌疑人〉。宝宝是对婴幼儿的爱称，不能指被抓获的成年嫌疑人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92610, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只宝宝很可爱。", "corrected_sentence": "这个宝宝很可爱。", "error_description": "量词错误：“宝宝”指人，应用量词“个”，不能用“只”（“只”多用于动物或成对之物）。正确说法是“这个宝宝很可爱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92610, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宝宝们，你今天真乖。", "corrected_sentence": "宝宝，你今天真乖。", "error_description": "数的不一致：“宝宝们”是多个孩子，后面的“你”是单数，二者不搭配。称呼一个孩子时应说“宝宝，你……”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
