INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对开是两辆车从两头出发，往中间开。", "primary_collocate": null, "pronunciation": "duì kāi", "ipa": "tweɪ˥˩ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "两列火车从两头对开，中午在这里相遇。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上六点，两辆公交车同时从两个站对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线上的地铁从两头对开，很方便。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两艘船从两岸对开，很快就在河中间见面了。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京和上海各发一列高铁对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两班车从山的两边对开，在山顶相遇。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天早上，两班车从两个城市对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的车从两头对开，三小时后就能见面。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天早上，两列火车会从南北两头对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两趟列车每天都在同一时间对开。", "target_word": "对开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对开了", "label": "体标"}, {"form": "对开过", "label": "体标"}, {"form": "對開", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两辆车从两头出发，朝对方开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '230f03da-1729-41ca-a1ac-3cb91ec386f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对开", "is_correct": true, "explanation": "对开指两车从两头相向开出，与“相遇”相符。"}, {"text": "停靠", "is_correct": false, "explanation": "语义：停靠是停下，不会从两头相向行进而相遇。"}, {"text": "分开", "is_correct": false, "explanation": "语义：分开是朝相反方向离去，与“相遇”矛盾。"}, {"text": "关闭", "is_correct": false, "explanation": "配价：“关闭”要带宾语（如关闭车门），不能单独用在“从两头”后面。"}], "explanations": {"对开": "对开指两车从两头相向开出，与“相遇”相符。", "停靠": "语义：停靠是停下，不会从两头相向行进而相遇。", "分开": "语义：分开是朝相反方向离去，与“相遇”矛盾。", "关闭": "配价：“关闭”要带宾语（如关闭车门），不能单独用在“从两头”后面。"}, "sentence_index": 0, "correct_answer": "对开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两班车同时从同一个车站对开，开往不同的方向。", "explanation": "这里应该用〈发车〉。对开要从两头相向开出，从同一车站开出应说“发车”。"}, {"text": "两只狗从院子的两头对开，跑到了中间。", "explanation": "这里应该用〈奔向〉。对开指两辆车从两头相向开出，狗跑向对方不能用对开。"}, {"text": "两辆车同向对开，一前一后地向北行驶。", "explanation": "这里应该用〈同行〉。对开指两车从两头相向开出，两车同向前进不能用对开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对开", "is_correct": true, "explanation": "对开指两班车从两个城市相向开出，与“每天早上”的定期运行相符。"}, {"text": "报废", "is_correct": false, "explanation": "语义：报废是车辆不能再用，与“每天早上”的定期运行矛盾。"}, {"text": "集合", "is_correct": false, "explanation": "语义：集合是聚到一处，与“从两个城市”各自出发矛盾。"}, {"text": "保养", "is_correct": false, "explanation": "配价：“保养”要带宾语（如保养车辆），不能单独用在“从两个城市”后。"}], "explanations": {"对开": "对开指两班车从两个城市相向开出，与“每天早上”的定期运行相符。", "报废": "语义：报废是车辆不能再用，与“每天早上”的定期运行矛盾。", "集合": "语义：集合是聚到一处，与“从两个城市”各自出发矛盾。", "保养": "配价：“保养”要带宾语（如保养车辆），不能单独用在“从两个城市”后。"}, "sentence_index": 6, "correct_answer": "对开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新司机对开了老司机的班次。", "explanation": "这里应该用〈替班〉。对开指两车从两头相向开出，接替别人的班次应说“替班”。"}, {"text": "三个学生从学校同时对开去郊游。", "explanation": "这里应该用〈出发〉。对开要从两头相向开出，三个学生从同一地点出发应说“出发”。"}, {"text": "这辆车从车库对开，驶上了马路。", "explanation": "这里应该用〈驶出〉。对开要两车从两头朝对方开，单独一辆车从车库开出应说“驶出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两只公交车每天都从两头对开。", "corrected_sentence": "两辆公交车每天都从两头对开。", "error_description": "量词错误：“公交车”是车辆，应用量词“辆”，不能用“只”（“只”多用于动物等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两列车被从两头对开，三小时后在中间会合。", "corrected_sentence": "这两列车从两头对开，三小时后在中间会合。", "error_description": "“被”字句错误：“对开”是不及物动词，不能用“被”引出施事或受事，应去掉“被”，说“这两列车从两头对开”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熟悉", "is_correct": true, "explanation": "「熟悉」与「陌生」构成反义关系，指对某地或某人的情况很了解。"}, {"text": "明亮", "is_correct": false, "explanation": "与「陌生」没有反义关系，「明亮」只说光线或环境亮。"}, {"text": "宽敞", "is_correct": false, "explanation": "与「陌生」没有反义关系，「宽敞」说空间大。"}, {"text": "善良", "is_correct": false, "explanation": "与「陌生」没有反义关系，「善良」说人的品性。"}], "correct_answer": "熟悉", "explanations": {"熟悉": "「熟悉」与「陌生」构成反义关系，指对某地或某人的情况很了解。", "明亮": "与「陌生」没有反义关系，「明亮」只说光线或环境亮。", "宽敞": "与「陌生」没有反义关系，「宽敞」说空间大。", "善良": "与「陌生」没有反义关系，「善良」说人的品性。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "熟悉", "is_correct": true, "explanation": "「熟悉」与「陌生」构成反义关系，指对事物或人很了解。"}, {"text": "丰富", "is_correct": false, "explanation": "与「陌生」没有反义关系，「丰富」说种类或数量多。"}, {"text": "干脆", "is_correct": false, "explanation": "与「陌生」没有反义关系，「干脆」说做事爽快利落。"}, {"text": "大方", "is_correct": false, "explanation": "与「陌生」没有反义关系，「大方」说态度自然、不拘束。"}], "correct_answer": "熟悉", "explanations": {"熟悉": "「熟悉」与「陌生」构成反义关系，指对事物或人很了解。", "丰富": "与「陌生」没有反义关系，「丰富」说种类或数量多。", "干脆": "与「陌生」没有反义关系，「干脆」说做事爽快利落。", "大方": "与「陌生」没有反义关系，「大方」说态度自然、不拘束。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "陌生是你从来没见过，也不认识。", "primary_collocate": null, "pronunciation": "mò shēng", "ipa": "mwɔ˥˩ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这个城市对我很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次来，这里的路都很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人我从来没见过，对我来说很陌生。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Zhè gè rén wǒ cóng lái méi jiàn guo, duì wǒ lái shuō hěn mò shēng.", "sentence_source": "generated"}, {"text": "这条路你很陌生，晚上别一个人走。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Zhè tiáo lù nǐ hěn mò shēng, wǎnshang bié yí gè rén zǒu.", "sentence_source": "generated"}, {"text": "我今天到了一个陌生的地方。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字我从来没听过，很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我一个人坐在陌生的教室里。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上有一个陌生号码。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚搬来时，我对邻居都很陌生。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Gāng bān lái shí, wǒ duì línjū dōu hěn mò shēng.", "sentence_source": "generated"}, {"text": "新环境对孩子来说很陌生，他有点儿怕。", "target_word": "陌生", "complexity_tier": "T3", "furigana": "Xīn huánjìng duì háizi lái shuō hěn mò shēng, tā yǒudiǎnr pà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "陌生人", "label": "复合"}, {"form": "陌生感", "label": "复合"}], "register": "中性", "sense_fingerprint": "从来没见过、不认识的人或事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示对这个城市没有熟悉感，与句中「对我」的说法相符。"}, {"text": "干净", "is_correct": false, "explanation": "语义：「干净」说的是卫生状况，不能用来说城市对「我」的感受。"}, {"text": "明亮", "is_correct": false, "explanation": "搭配：「明亮」多用于光线、房间，不说「对我很明亮」。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：「严肃」说人的态度，不能用来形容城市对「我」的态度。"}], "explanations": {"陌生": "「陌生」表示对这个城市没有熟悉感，与句中「对我」的说法相符。", "干净": "语义：「干净」说的是卫生状况，不能用来说城市对「我」的感受。", "明亮": "搭配：「明亮」多用于光线、房间，不说「对我很明亮」。", "严肃": "语义：「严肃」说人的态度，不能用来形容城市对「我」的态度。"}, "sentence_index": 0, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的游泳技术很陌生，一下水就沉下去了。", "explanation": "这里应该用〈生疏〉。「陌生」多指从没接触过的人或事，说技能不熟练一般用〈生疏〉。"}, {"text": "这个现象很陌生，我们在这里已经见过很多次了。", "explanation": "这里应该用〈奇怪〉。「陌生」指没见过、不认识，与「见过很多次」矛盾；说现象怪异要用〈奇怪〉。"}, {"text": "我每天都走这条路，这里的路对我很陌生。", "explanation": "这里应该用〈熟悉〉。「陌生」指没去过、不认识，与「每天都走这条路」矛盾；对路况很了解要用〈熟悉〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示没来过、不熟悉，与「一个人坐在……的教室里」相符。"}, {"text": "生气", "is_correct": false, "explanation": "语义：「生气」形容人的情绪，教室不会生气，与句子不通。"}, {"text": "拥挤", "is_correct": false, "explanation": "语义：「拥挤」说人多，与句中「一个人」矛盾。"}, {"text": "疲惫", "is_correct": false, "explanation": "语义：「疲惫」形容人的状态，教室不会疲惫，与句子不通。"}], "explanations": {"陌生": "「陌生」表示没来过、不熟悉，与「一个人坐在……的教室里」相符。", "生气": "语义：「生气」形容人的情绪，教室不会生气，与句子不通。", "拥挤": "语义：「拥挤」说人多，与句中「一个人」矛盾。", "疲惫": "语义：「疲惫」形容人的状态，教室不会疲惫，与句子不通。"}, "sentence_index": 6, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一见到我就很陌生，像亲人一样拥抱我。", "explanation": "这里应该用〈亲切〉。「陌生」指不认识，与「像亲人一样拥抱我」矛盾；对人热情亲近要用〈亲切〉。"}, {"text": "一进家门，屋里很陌生，像回到了家一样。", "explanation": "这里应该用〈温暖〉。「陌生」与「像回到了家一样」矛盾；描述家里的暖意要用〈温暖〉。"}, {"text": "我们两个配合得很陌生，一个眼神就明白了对方。", "explanation": "这里应该用〈默契〉。「陌生」只说不认识，与「一个眼神就明白」矛盾；配合心意相通要用〈默契〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市对我的很陌生。", "corrected_sentence": "这个城市对我很陌生。", "error_description": "错误：「对我」后多出结构助词「的」，「对我的」需要带中心语，这里不通。正确：「这个城市对我很陌生」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92621, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇对我来说陌生。", "corrected_sentence": "这个小镇对我来说很陌生。", "error_description": "错误：形容词「陌生」作谓语时前面漏掉了程度副词「很」，说「陌生」显得句子不完整。正确：「这个小镇对我来说很陌生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
