INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "生疏，不熟悉；没有见过或不了解。", "primary_collocate": null, "pronunciation": "mò shēng", "ipa": "mwɔ˥˩ ʂɤŋ˥˥", "syllable_count": 2, "sentences": [{"text": "我离开家乡十年，那里变得很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久没开车，开车的感觉有点陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对电脑很陌生，不会上网。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词对学生来说很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年没见，他的声音变得陌生了。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种新菜我很陌生，没吃过。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说的这个办法，大家都觉得陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回到旧房子，一切都让我觉得陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对城里的生活还很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老年人来说，手机软件很陌生。", "target_word": "陌生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陌生人", "label": "复合"}, {"form": "陌生感", "label": "复合"}], "register": "中性", "sense_fingerprint": "生疏、不熟悉、不了解", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示离开多年后对那里不熟悉，与句中「离开家乡十年」相符。"}, {"text": "幼稚", "is_correct": false, "explanation": "语义：「幼稚」说人的心智不成熟，不能用来形容「那里」。"}, {"text": "调皮", "is_correct": false, "explanation": "语义：「调皮」形容人或孩子的性情，不用于地方。"}, {"text": "狡猾", "is_correct": false, "explanation": "语义：「狡猾」说人的心机，地方变得狡猾不成立。"}], "explanations": {"陌生": "「陌生」表示离开多年后对那里不熟悉，与句中「离开家乡十年」相符。", "幼稚": "语义：「幼稚」说人的心智不成熟，不能用来形容「那里」。", "调皮": "语义：「调皮」形容人或孩子的性情，不用于地方。", "狡猾": "语义：「狡猾」说人的心机，地方变得狡猾不成立。"}, "sentence_index": 0, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这门技术很陌生，已经用了十年。", "explanation": "这里应该用〈熟练〉。「陌生」只说不认识，与「用了十年」矛盾；技术运用得好要用〈熟练〉。"}, {"text": "我们俩一起长大，每天都在一起玩，我对他的一切都很陌生。", "explanation": "这里应该用〈亲密〉。「陌生」指不熟悉，与「一起长大、每天都在一起玩」矛盾；关系亲近、彼此了解要用〈亲密〉。"}, {"text": "这位教授对古代文学很陌生，他研究了三十年，已经发表了很多论文。", "explanation": "这里应该用〈精通〉。「陌生」指不熟悉，与「研究了三十年」矛盾；对学问深入掌握要用〈精通〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陌生", "is_correct": true, "explanation": "「陌生」表示对这个办法没听说过或不了解，与句中「大家都觉得」相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」说地方或场面没有人气，不能用来形容办法。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：「热闹」说场面有人气，不能用来形容办法。"}, {"text": "响亮", "is_correct": false, "explanation": "搭配：「响亮」多形容声音，不能用「觉得」修饰办法。"}], "explanations": {"陌生": "「陌生」表示对这个办法没听说过或不了解，与句中「大家都觉得」相符。", "冷清": "语义：「冷清」说地方或场面没有人气，不能用来形容办法。", "热闹": "语义：「热闹」说场面有人气，不能用来形容办法。", "响亮": "搭配：「响亮」多形容声音，不能用「觉得」修饰办法。"}, "sentence_index": 6, "correct_answer": "陌生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条街每天都很陌生，我们常在这里散步。", "explanation": "这里应该用〈熟悉〉。「陌生」指没去过、不认识，与「常在这里散步」矛盾；对地方很了解要用〈熟悉〉。"}, {"text": "一进家门，屋里很陌生，我闭着眼睛也能找到厨房。", "explanation": "这里应该用〈熟悉〉。「陌生」指不熟悉，与「闭着眼睛也能找到厨房」矛盾；对环境很了解要用〈熟悉〉。"}, {"text": "我们两人配合得很陌生，一个眼神就明白了对方。", "explanation": "这里应该用〈默契〉。「陌生」只说不认识，与「一个眼神就明白」矛盾；配合心意相通要用〈默契〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他对这条路陌生很。", "corrected_sentence": "他对这条路陌生得很。", "error_description": "错误：形容词「陌生」作谓语后面不能直接接「很」，要用补语结构「陌生得很」。正确：「他对这条路陌生得很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些方法老年人来说很陌生。", "corrected_sentence": "这些方法对老年人来说很陌生。", "error_description": "错误：「老年人来说」前面漏掉了介词「对」。「对……来说」引出说话的角度，不能省略「对」。正确：「这些方法对老年人来说很陌生」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
