INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "岛屿是海里四面都是水的小块陆地。", "primary_collocate": null, "pronunciation": "dǎo yǔ", "ipa": "tau˨˩˦ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "飞机飞过海面，下面有一座岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "fēi jī fēi guò hǎi miàn, xià miàn yǒu yí zuò dǎo yǔ.", "sentence_source": "generated"}, {"text": "这片海里有很多岛屿，要坐船才能去。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岛屿四面都是水，没有桥，只能坐船。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边看到远处有个绿色的岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家由几千个岛屿组成。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天我想去热带的岛屿玩儿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风来了，岛屿上的人都回家了。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的蓝色是海，绿色小点是岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个岛屿很小，只住着十几个人。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船到了岛屿，沙滩上有很多贝壳。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "岛屿·海里四面都是水的小块陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”是海里四面环水的小块陆地，与“飞过海面”的语境相合。"}, {"text": "海", "is_correct": false, "explanation": "搭配：“一座”不能修饰“海”，海要说“一片海”。"}, {"text": "海浪", "is_correct": false, "explanation": "量词：“座”不能修饰“海浪”，海浪应说“一排海浪”。"}, {"text": "云", "is_correct": false, "explanation": "量词：“座”不能修饰“云”，云要说“一朵云”。"}], "explanations": {"岛屿": "“岛屿”是海里四面环水的小块陆地，与“飞过海面”的语境相合。", "海": "搭配：“一座”不能修饰“海”，海要说“一片海”。", "海浪": "量词：“座”不能修饰“海浪”，海浪应说“一排海浪”。", "云": "量词：“座”不能修饰“云”，云要说“一朵云”。"}, "sentence_index": 0, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从岛屿的一头步行，就能走到陆地。", "explanation": "这里应该用〈半岛〉。岛屿四面环水，与陆地不相连，不能步行走到陆地；〈半岛〉一端连着陆地。"}, {"text": "他们坐船去了一条绿色的岛屿。", "explanation": "量词用错。〈条〉用于细长的东西，岛屿应用〈座〉。"}, {"text": "远处的海面上浮着一只绿色的岛屿。", "explanation": "量词用错。〈只〉用于动物或单个的小物件，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”是海中四面环水的陆地，与“台风来了”、人要回家的语境相合。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“城市上”不说，应说“城市里”。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“学校上”不说，应说“学校里”。"}, {"text": "岩石", "is_correct": false, "explanation": "语义：岩石上不住人，句子说的是人回家，与之不符。"}], "explanations": {"岛屿": "“岛屿”是海中四面环水的陆地，与“台风来了”、人要回家的语境相合。", "城市": "搭配：“城市上”不说，应说“城市里”。", "学校": "搭配：“学校上”不说，应说“学校里”。", "岩石": "语义：岩石上不住人，句子说的是人回家，与之不符。"}, "sentence_index": 6, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们坐船到了一棵岛屿，沙滩上有很多贝壳。", "explanation": "量词用错。〈棵〉用于树，岛屿应用〈座〉。"}, {"text": "台风过后，海面上多了一本岛屿。", "explanation": "量词用错。〈本〉用于书，岛屿应用〈座〉。"}, {"text": "沙滩上有很多贝壳，我们坐船到了一辆岛屿。", "explanation": "量词用错。〈辆〉用于车，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们坐船去了一本岛屿。", "corrected_sentence": "我们坐船去了一座岛屿。", "error_description": "量词错误：“岛屿”应搭配量词“座”，“本”用于书籍。应说“一座岛屿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92623, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些岛屿们都很美。", "corrected_sentence": "这些岛屿都很美。", "error_description": "错误在“岛屿”后面多加了“们”。“们”只用于人或拟人的名词，岛屿是无生命的事物，不能加“们”。应说“这些岛屿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
