INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海洋、湖泊或河流中四面环水的小块陆地。", "primary_collocate": null, "pronunciation": "dǎo yǔ", "ipa": "tau˨˩˦ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "湖中间有一个岛屿，鸟都住在那里。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "hú zhōng jiān yǒu yí gè dǎo yǔ, niǎo dōu zhù zài nà lǐ.", "sentence_source": "generated"}, {"text": "长江里有一个岛屿，船从两边过去。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "Cháng jiāng lǐ yǒu yí gè dǎo yǔ, chuán cóng liǎng biān guò qù.", "sentence_source": "generated"}, {"text": "海洋中有很多岛屿，有的大，有的小。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水围住了这块地，它成了岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖里的岛屿四面环水，只能坐船去。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在山上，能看到湖里的几个岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "furigana": "zhàn zài shān shàng, néng kàn dào hú lǐ de jǐ gè dǎo yǔ.", "sentence_source": "generated"}, {"text": "这个岛屿在河中间，上面有很多树。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地理课上，老师讲了海洋和湖泊里的岛屿。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖中的岛屿春天特别漂亮，花开了。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水涨了，河中的岛屿变小了。", "target_word": "岛屿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "岛屿·海洋湖泊河流中四面环水的小块陆地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”指湖中四面环水的小块陆地，与“湖中间”和“鸟住在那里”相合。"}, {"text": "海", "is_correct": false, "explanation": "语义：湖中间不可能是海，句子说的是湖里的陆地。"}, {"text": "岸", "is_correct": false, "explanation": "语义：“岸”在湖边，不在湖中间，与“湖中间有一个”的位置不符。"}, {"text": "湖泊", "is_correct": false, "explanation": "语义：“湖中间”已指明在湖内，再说“湖中间有一个湖泊”语义重复，不自然。"}], "explanations": {"岛屿": "“岛屿”指湖中四面环水的小块陆地，与“湖中间”和“鸟住在那里”相合。", "海": "语义：湖中间不可能是海，句子说的是湖里的陆地。", "岸": "语义：“岸”在湖边，不在湖中间，与“湖中间有一个”的位置不符。", "湖泊": "语义：“湖中间”已指明在湖内，再说“湖中间有一个湖泊”语义重复，不自然。"}, "sentence_index": 0, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着岛屿的小路一直走到了海边。", "explanation": "这里应该用〈半岛〉。岛屿四面环水，与陆地不相连，不能沿路走到海边；〈半岛〉一端连着陆地，才能步行过去。"}, {"text": "湖边的渔民每天划船去一条岛屿打鱼。", "explanation": "量词用错。〈条〉用于细长的东西，岛屿应用〈座〉。"}, {"text": "他站在湖边，看见一只岛屿，上面长着很多树。", "explanation": "量词用错。〈只〉用于动物或单个的小物件，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "岛屿", "is_correct": true, "explanation": "“岛屿”是河中四面环水的小块陆地，与“在河中间”和“上面有很多树”相合。"}, {"text": "河岸", "is_correct": false, "explanation": "搭配：“河岸”不说“在河中间”，只能说在河边。"}, {"text": "码头", "is_correct": false, "explanation": "语义：码头在岸边，不在河中间，与句中的位置不符。"}, {"text": "船", "is_correct": false, "explanation": "语义：船上不会长很多树，与“上面有很多树”的描述冲突。"}], "explanations": {"岛屿": "“岛屿”是河中四面环水的小块陆地，与“在河中间”和“上面有很多树”相合。", "河岸": "搭配：“河岸”不说“在河中间”，只能说在河边。", "码头": "语义：码头在岸边，不在河中间，与句中的位置不符。", "船": "语义：船上不会长很多树，与“上面有很多树”的描述冲突。"}, "sentence_index": 6, "correct_answer": "岛屿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河中间有一棵岛屿，上面长满了草。", "explanation": "量词用错。〈棵〉用于树，岛屿应用〈座〉。"}, {"text": "河里有一本岛屿，岛上有很多鸟。", "explanation": "量词用错。〈本〉用于书，岛屿应用〈座〉。"}, {"text": "河水涨了，河中一辆岛屿变小了。", "explanation": "量词用错。〈辆〉用于车，岛屿应用〈座〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "游客坐船来到湖中的一条岛屿，这里很安静。", "corrected_sentence": "游客坐船来到湖中的一座岛屿，这里很安静。", "error_description": "量词错误：“岛屿”应搭配量词“座”，“条”用于细长的东西。应说“一座岛屿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92624, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们坐船到了河中的岛屿的，岛上有很多鸟。", "corrected_sentence": "我们坐船到了河中的岛屿，岛上有很多鸟。", "error_description": "错误在“岛屿”后多加了“的”。“岛屿”是中心语，后面不能再接“的”；“的”只接在“河中”后面，应说“河中的岛屿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
