INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92639, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一个个是一个接着一个，不是一起。", "primary_collocate": null, "pronunciation": "yí gè gè", "ipa": "i˧˥ kɤ˥˩ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "请大家一个个进来，不要一起进。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们一个个走进教室。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把苹果一个个放进盒子里。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人一个个到了，我们开始吃饭。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让病人一个个进去检查。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一个个排好队上车。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要一个个回答问题，别着急。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把名字一个个念了一遍。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个个打开了箱子。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一个个站起来唱歌。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一個個", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动作按顺序一个接一个地进行，不是同时", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一个个", "is_correct": true, "explanation": "“一个个”表示一个接一个地进入，与“不要一起进”形成对照，句意通顺。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示同时，与后句“不要一起进”直接矛盾，句子不通。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已完成，与“请…进来”的祈使语气矛盾。"}, {"text": "一齐", "is_correct": false, "explanation": "语义：“一齐”与“一起”同义，与后句“不要一起进”矛盾，句子不通。"}], "explanations": {"一个个": "“一个个”表示一个接一个地进入，与“不要一起进”形成对照，句意通顺。", "一起": "语义：“一起”表示同时，与后句“不要一起进”直接矛盾，句子不通。", "已经": "语义：“已经”表示动作已完成，与“请…进来”的祈使语气矛盾。", "一齐": "语义：“一齐”与“一起”同义，与后句“不要一起进”矛盾，句子不通。"}, "sentence_index": 0, "correct_answer": "一个个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三个人一个个抬起这个大箱子。", "explanation": "这里应该用〈一起〉。这箱子要几个人同时用力才抬得起，“一个个”表示依次进行，不能用于合力的动作。"}, {"text": "两个女孩一个个坐着，肩并肩地看书。", "explanation": "这里应该用〈并排〉。“肩并肩地看书”要求两人同时并坐，“一个个”表示依次进行，两者矛盾。"}, {"text": "他们一个个开口唱歌，声音很整齐。", "explanation": "这里应该用〈同时〉。“声音很整齐”要求大家同时发声，“一个个”表示依次进行，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一个个", "is_correct": true, "explanation": "“一个个”表示逐一进行，与“别着急”相容，填入后句意通顺。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：“赶紧”表示急着做，与后句“别着急”矛盾。"}, {"text": "偶然", "is_correct": false, "explanation": "语义：“偶然”表示偶尔发生，与“要回答问题”的要求不合。"}, {"text": "拼命", "is_correct": false, "explanation": "语义：“拼命”表示竭尽全力，与后句“别着急”矛盾。"}], "explanations": {"一个个": "“一个个”表示逐一进行，与“别着急”相容，填入后句意通顺。", "赶紧": "语义：“赶紧”表示急着做，与后句“别着急”矛盾。", "偶然": "语义：“偶然”表示偶尔发生，与“要回答问题”的要求不合。", "拼命": "语义：“拼命”表示竭尽全力，与后句“别着急”矛盾。"}, "sentence_index": 6, "correct_answer": "一个个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞蹈演员一个个转身，像一个人似的。", "explanation": "这里应该用〈一齐〉。“像一个人似的”要求动作同时完成，“一个个”表示依次进行，句意矛盾。"}, {"text": "两台机器一个个运行，数据才能对上。", "explanation": "这里应该用〈同步〉。数据要对得上，两台机器必须同步运行，“一个个”表示依次进行，无法保证对齐。"}, {"text": "同学们一个个朗读，齐刷刷地停下来。", "explanation": "这里应该用〈齐声〉。“齐刷刷地停下来”要求大家同时停，“一个个”表示依次进行，与句意矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "乘客们一个个走一个个下火车。", "corrected_sentence": "乘客们一个个走下火车。", "error_description": "副词“一个个”只出现一次，修饰动词“走”，不能在“走”与补语“下”之间重复。错误形式：一个个走一个个下火车；正确形式：一个个走下火车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客们一个个走一个个进博物馆。", "corrected_sentence": "游客们一个个走进博物馆。", "error_description": "副词“一个个”只出现一次，修饰动词“走”，不能在“走”与补语“进”之间重复。错误形式：一个个走一个个进博物馆；正确形式：一个个走进博物馆。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
