INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92640, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每一个；各个（多与“都”连用）。", "primary_collocate": null, "pronunciation": "yí gè gè", "ipa": "i˧˥ kɤ˥˩ kɤ˥˩", "syllable_count": 3, "sentences": [{"text": "孩子们一个个都很高兴。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一个个身体都很好。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些学生一个个都很努力。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些苹果一个个又大又红。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员们一个个跑得很快。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几只小狗一个个都很可爱。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人一个个都吃得很饱。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜一个个都很好吃。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一个个都笑着说话。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的人一个个都很紧张。", "target_word": "一个个", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一個個", "label": "繁体"}], "register": "口语", "sense_fingerprint": "指一群人或事物中的每一个，常与“都”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92640, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一个个", "is_correct": true, "explanation": "“一个个”表示群体中的每一个，与“都”连用，说明每个孩子都很高兴。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：“慢慢”表示缓慢进行，不修饰心情，与“都很高兴”不搭。"}, {"text": "轮流", "is_correct": false, "explanation": "搭配：“轮流”说交替进行，不用来描述大家的心情。"}, {"text": "连忙", "is_correct": false, "explanation": "语义：“连忙”表示急忙行动，与“很高兴”这种状态不符。"}], "explanations": {"一个个": "“一个个”表示群体中的每一个，与“都”连用，说明每个孩子都很高兴。", "慢慢": "语义：“慢慢”表示缓慢进行，不修饰心情，与“都很高兴”不搭。", "轮流": "搭配：“轮流”说交替进行，不用来描述大家的心情。", "连忙": "语义：“连忙”表示急忙行动，与“很高兴”这种状态不符。"}, "sentence_index": 0, "correct_answer": "一个个"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一个个都很高兴。", "explanation": "这里应该用〈我们〉。“一个个”指群体中的每一个，须以复数或群体作主语，“我”只指一人。"}, {"text": "这个苹果一个个都很红。", "explanation": "这里应该用〈那些〉。“这个苹果”只指一个，“一个个”需要复数的群体。"}, {"text": "这间屋子一个个都很大。", "explanation": "这里应该用〈这些〉。“这间屋子”只指一间，“一个个”需要多个对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一个个", "is_correct": true, "explanation": "“一个个”表示群体中的每一个，与“都”连用，说明每位客人都吃饱了。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“都”所表示的全部含义矛盾。"}, {"text": "悄悄", "is_correct": false, "explanation": "搭配：“悄悄”说动作的隐秘方式，不修饰“吃饱”的结果。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“都吃得很饱”这种持续的状态不符。"}], "explanations": {"一个个": "“一个个”表示群体中的每一个，与“都”连用，说明每位客人都吃饱了。", "偶尔": "语义：“偶尔”表示不常发生，与“都”所表示的全部含义矛盾。", "悄悄": "搭配：“悄悄”说动作的隐秘方式，不修饰“吃饱”的结果。", "突然": "语义：“突然”表示事情忽然发生，与“都吃得很饱”这种持续的状态不符。"}, "sentence_index": 6, "correct_answer": "一个个"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位选手一个个都很紧张。", "explanation": "这里应该用〈这些〉。“这位选手”只指一人，“一个个”须指群体。"}, {"text": "他一个个都很紧张。", "explanation": "这里应该用〈他们〉。“他”只指一人，“一个个”须以复数或群体作主语。"}, {"text": "这辆车一个个都很快。", "explanation": "这里应该用〈这些〉。“这辆车”只指一辆，“一个个”需要多个对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些苹果一个个长一个个大了。", "corrected_sentence": "这些苹果一个个长大了。", "error_description": "副词“一个个”只出现一次，修饰“长大”，不能在动词“长”与结果补语“大”之间重复。错误形式：一个个长一个个大了；正确形式：一个个长大了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些同学一个个一个个都很开心。", "corrected_sentence": "这些同学一个个都很开心。", "error_description": "副词“一个个”只出现一次，不能连续重复。错误形式：一个个一个个都很开心；正确形式：一个个都很开心。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
