INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92641, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "性别是说一个人是男的还是女的。", "primary_collocate": null, "pronunciation": "xìng bié", "ipa": "ɕiŋ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "表格上要写姓名、年龄和性别。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问您的性别是男还是女？", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的性别，医生还没告诉我们。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的性别是男，今年二十岁。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "填表时，性别这一栏他选了女。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字男女都能用，听不出性别。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们班有不同性别的同学。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的身份证上写着他的性别是男。", "target_word": "性别", "complexity_tier": "T3", "furigana": "péng yǒu de shēn fèn zhèng shàng xiě zhe tā de xìng bié shì nán", "sentence_source": "generated"}, {"text": "不管性别，大家都可以参加比赛。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报名时，请写清楚你的性别和电话。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性别歧视", "label": "复合"}, {"form": "性别比例", "label": "复合"}], "register": "中性", "sense_fingerprint": "性别·一个人是男还是女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性别", "is_correct": true, "explanation": "正确：「性别」指一个人是男是女，填表时要写。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是表格上要填写的个人信息，不能和姓名、年龄并列。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是个人信息项目，姓名、年龄和颜色并列不合逻辑。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是个人的情绪，不是表格上要填写的个人信息，与姓名、年龄并列不合逻辑。"}], "explanations": {"性别": "正确：「性别」指一个人是男是女，填表时要写。", "天气": "语义：天气是自然现象，不是表格上要填写的个人信息，不能和姓名、年龄并列。", "颜色": "语义：颜色不是个人信息项目，姓名、年龄和颜色并列不合逻辑。", "心情": "语义：心情是个人的情绪，不是表格上要填写的个人信息，与姓名、年龄并列不合逻辑。"}, "sentence_index": 0, "correct_answer": "性别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性别很开朗，今年二十岁。", "explanation": "这里应该用〈性格〉。性别只说男或女，不能用来形容开朗这类性情。"}, {"text": "他的性别是二十岁。", "explanation": "这里应该用〈年龄〉。性别指男或女，不能用来表示岁数。"}, {"text": "他的性别是中国人。", "explanation": "这里应该用〈国籍〉。性别只分男女，不能表示一个人属于哪个国家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性别", "is_correct": true, "explanation": "正确：「不同性别」指男女之别，与「不同」搭配自然，句意通顺。"}, {"text": "味道", "is_correct": false, "explanation": "语义：同学之间不按味道区分，「不同味道的同学」说不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是区分同学的标准，「不同天气的同学」说不通。"}, {"text": "形状", "is_correct": false, "explanation": "语义：「形状」指物体的外形，不用来区分同学，「不同形状的同学」说不通。"}], "explanations": {"性别": "正确：「不同性别」指男女之别，与「不同」搭配自然，句意通顺。", "味道": "语义：同学之间不按味道区分，「不同味道的同学」说不通。", "天气": "语义：天气不是区分同学的标准，「不同天气的同学」说不通。", "形状": "语义：「形状」指物体的外形，不用来区分同学，「不同形状的同学」说不通。"}, "sentence_index": 6, "correct_answer": "性别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性别是A型。", "explanation": "这里应该用〈血型〉。性别指男或女，不能用来表示血液类型。"}, {"text": "他的性别是医生。", "explanation": "这里应该用〈职业〉。性别只分男女，不能说成某种职业。"}, {"text": "他的性别是游泳。", "explanation": "这里应该用〈爱好〉。性别不能表示一个人喜欢做的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的性别女。", "corrected_sentence": "她的性别是女。", "error_description": "漏掉判断动词「是」。“她的性别女”结构不完整，应说“她的性别是女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份问卷要写清楚你性别。", "corrected_sentence": "这份问卷要写清楚你的性别。", "error_description": "漏掉定语标记「的」。“你性别”不成词组，应说“你的性别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
