INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "男女或雌雄的区别。", "primary_collocate": null, "pronunciation": "xìng bié", "ipa": "ɕiŋ˥˩ pje˧˥", "syllable_count": 2, "sentences": [{"text": "这种小鸟的性别很难分清。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同性别的小狗，长大后样子不一样。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司不能因为性别不同给不同工资。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物的性别分雌和雄。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两只猫性别不同，一只雌一只雄。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "性别的区别，不影响工作能力。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的性别不同，但都爱画画。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查后，说小马的性别是雄。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条鱼的性别要长大后才看得出。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生的性别不同，但学习机会应该一样。", "target_word": "性别", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "性别歧视", "label": "复合"}, {"form": "性别比例", "label": "复合"}], "register": "中性", "sense_fingerprint": "性别·男女或雌雄的区别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "性别", "is_correct": true, "explanation": "正确：「性别」指雌雄之别，正好说明小鸟的雌雄难以分清。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：小鸟没有国籍，「国籍」与这里的语境不合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：小鸟不具备学历，「学历」这里说不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「分清」后接的是可以辨认的区别，「工资」是报酬，不说分清工资。"}], "explanations": {"性别": "正确：「性别」指雌雄之别，正好说明小鸟的雌雄难以分清。", "国籍": "语义：小鸟没有国籍，「国籍」与这里的语境不合。", "学历": "语义：小鸟不具备学历，「学历」这里说不通。", "工资": "搭配：「分清」后接的是可以辨认的区别，「工资」是报酬，不说分清工资。"}, "sentence_index": 0, "correct_answer": "性别"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "动物的性别分温顺和凶猛。", "explanation": "这里应该用〈性格〉。性别指雌雄，不能用来说温顺、凶猛这类性情。"}, {"text": "这只狗的性别是拉布拉多。", "explanation": "这里应该用〈品种〉。性别只指雌或雄，不能说成品种。"}, {"text": "这只鸟的性别很漂亮。", "explanation": "这里应该用〈外貌〉。性别是雌雄之别，不能用来形容“漂亮”这类外貌特征。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "性别", "is_correct": true, "explanation": "正确：「性别」指男女或雌雄之别，与前面的「不同」搭配，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能作为人群之间的区别，这里说不通。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」是食物或气味的特征，不能说「他们的味道不同」。"}, {"text": "形状", "is_correct": false, "explanation": "语义：「形状」指物体的外形，人与人之间不用形状区分，「他们的形状不同」说不通。"}], "explanations": {"性别": "正确：「性别」指男女或雌雄之别，与前面的「不同」搭配，句意通顺。", "天气": "语义：天气不能作为人群之间的区别，这里说不通。", "味道": "语义：「味道」是食物或气味的特征，不能说「他们的味道不同」。", "形状": "语义：「形状」指物体的外形，人与人之间不用形状区分，「他们的形状不同」说不通。"}, "sentence_index": 6, "correct_answer": "性别"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只狗的性别是三岁。", "explanation": "这里应该用〈年龄〉。性别只指雌雄，不能表示岁数。"}, {"text": "这只狗的性别是十公斤。", "explanation": "这里应该用〈体重〉。性别不能用来表示重量。"}, {"text": "这只猫的性别是三十厘米。", "explanation": "这里应该用〈身高〉。性别不能用来表示长度或身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只鸡的性别雌的。", "corrected_sentence": "这只鸡的性别是雌的。", "error_description": "漏掉判断动词「是」。“性别雌的”结构不完整，应说“性别是雌的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条鱼要长大后才能看出它性别。", "corrected_sentence": "这条鱼要长大后才能看出它的性别。", "error_description": "漏掉定语标记「的」。“它性别”不成词组，应说“它的性别”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。"}, {"text": "杯子", "is_correct": false, "explanation": "杯子是器具，与惩罚没有反义关系。"}, {"text": "风景", "is_correct": false, "explanation": "风景是自然或城市的景色，与惩罚没有反义关系。"}, {"text": "计划", "is_correct": false, "explanation": "计划是打算和安排，与惩罚没有反义关系。"}], "correct_answer": "奖励", "explanations": {"奖励": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。", "杯子": "杯子是器具，与惩罚没有反义关系。", "风景": "风景是自然或城市的景色，与惩罚没有反义关系。", "计划": "计划是打算和安排，与惩罚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奖励", "is_correct": true, "explanation": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户是建筑的构件，与惩罚没有反义关系。"}, {"text": "节日", "is_correct": false, "explanation": "节日是特定的纪念日，与惩罚没有反义关系。"}, {"text": "方法", "is_correct": false, "explanation": "方法是做事的途径，与惩罚没有反义关系。"}], "correct_answer": "奖励", "explanations": {"奖励": "奖励与惩罚是一对反义词：奖励是对做得好的事给予的好处，惩罚是做错事后要承受的事。", "窗户": "窗户是建筑的构件，与惩罚没有反义关系。", "节日": "节日是特定的纪念日，与惩罚没有反义关系。", "方法": "方法是做事的途径，与惩罚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "惩罚是做错事以后，被要求做不喜欢的事。", "primary_collocate": null, "pronunciation": "chéng fá", "ipa": "ʈʂʰɤŋ˧˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "做错事要接受惩罚。", "target_word": "惩罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天的惩罚是洗碗。", "target_word": "惩罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他迟到了，老师的惩罚是打扫教室。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟打破了杯子，受到了妈妈的惩罚。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个游戏输的人要接受惩罚，比如唱歌。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我最怕的惩罚是不能看电视。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对孩子来说，罚站是一种很难受的惩罚。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "作业没写完，他的惩罚是放学后留下来。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把手机弄坏了，爸爸的惩罚是一个月不能玩游戏。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸让孩子自己决定惩罚的内容，他选了跑步。", "target_word": "惩罚", "complexity_tier": "T3", "furigana": "bà ba ràng hái zi zì jǐ jué dìng chéng fá de nèi róng, tā xuǎn le pǎo bù.", "sentence_source": "generated"}], "morphological_forms": [{"form": "一次惩罚", "label": "量词：次"}, {"form": "惩罚措施", "label": "复合"}, {"form": "懲罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做错事后被要求做不喜欢的事（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：做错事后要承受的处分，与“接受”搭配。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是发给表现好的人的钱，做错事不会得到奖金。"}, {"text": "荣誉", "is_correct": false, "explanation": "语义：荣誉是因成绩而得到的光荣，与“做错事”相矛盾。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“接受”不与“作业”搭配，作业应说完成或布置。"}], "explanations": {"惩罚": "惩罚：做错事后要承受的处分，与“接受”搭配。", "奖金": "语义：奖金是发给表现好的人的钱，做错事不会得到奖金。", "荣誉": "语义：荣誉是因成绩而得到的光荣，与“做错事”相矛盾。", "作业": "搭配：“接受”不与“作业”搭配，作业应说完成或布置。"}, "sentence_index": 0, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的自行车需要惩罚。", "explanation": "这里应该用〈修理〉。修理用于坏了的物品，惩罚的对象是做错事的人，不能用于自行车。"}, {"text": "他因为超速，去交了惩罚。", "explanation": "这里应该用〈罚款〉。交的是钱款，惩罚指做错事后要承受的事，不能用“交”来表示。"}, {"text": "他很快就吃完了惩罚。", "explanation": "这里应该用〈午饭〉。吃完的是饭食，惩罚是做错事后要承受的事，不能被“吃完”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：罚站这种做错事后承受的处分，与“一种很难受的”搭配。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物是令人高兴的东西，与“很难受”相矛盾。"}, {"text": "享受", "is_correct": false, "explanation": "语义：享受是愉快的体验，与“很难受”的说法相矛盾。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏是供人娱乐的活动，“很难受的游戏”说不通。"}], "explanations": {"惩罚": "惩罚：罚站这种做错事后承受的处分，与“一种很难受的”搭配。", "礼物": "语义：礼物是令人高兴的东西，与“很难受”相矛盾。", "享受": "语义：享受是愉快的体验，与“很难受”的说法相矛盾。", "游戏": "语义：游戏是供人娱乐的活动，“很难受的游戏”说不通。"}, "sentence_index": 6, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在晚会上唱了惩罚。", "explanation": "这里应该用〈歌〉。唱的是歌，惩罚是做错事后要承受的事，不能被“唱”。"}, {"text": "这个惩罚很可爱。", "explanation": "这里应该用〈孩子〉。“可爱”用于形容人或动物，惩罚是事情，不能用“可爱”来形容。"}, {"text": "他从这次失败中吸取了惩罚。", "explanation": "这里应该用〈教训〉。吸取的是教训，惩罚是做错事后要承受的事，不能被吸取。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他以前受到过一条惩罚，这次要留下来打扫教室。", "corrected_sentence": "他以前受到过一次惩罚，这次要留下来打扫教室。", "error_description": "量词错误：“惩罚”应用量词“次”，说“一次惩罚”；“条”用于长条形事物，不能修饰“惩罚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92647, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他惩罚是一周不能看电视。", "corrected_sentence": "他的惩罚是一周不能看电视。", "error_description": "错误在于定语标记“的”被漏掉。应说“他的惩罚”，“他惩罚是”不符合汉语的名词修饰结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
