INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对犯错或犯罪的人给予处分。", "primary_collocate": null, "pronunciation": "chéng fá", "ipa": "ʈʂʰɤŋ˧˥ fa˧˥", "syllable_count": 2, "sentences": [{"text": "老师惩罚了迟到的学生。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律会惩罚犯罪的人。", "target_word": "惩罚", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司决定惩罚泄露秘密的员工。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈没有惩罚弟弟，只是批评了他。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国王惩罚了偷东西的人，把他关进监狱。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判因为犯规惩罚了那名球员。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官依法惩罚了这个骗子。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做错了事，爸爸却从来不惩罚他。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不应该随便惩罚做错事的孩子。", "target_word": "惩罚", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府已经惩罚过那家排放污水的工厂。", "target_word": "惩罚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "惩罚了", "label": "体标：了"}, {"form": "惩罚过", "label": "体标：过"}, {"form": "懲罰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对犯错或犯罪者给予处分（动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：对迟到这种过错给予处分，与“迟到的学生”搭配。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定好的行为，与“迟到”这一过错相矛盾。"}, {"text": "赞赏", "is_correct": false, "explanation": "语义：赞赏是欣赏优点，不能用来说对迟到学生的处理。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：批改用于作业、试卷，不能说“批改学生”。"}], "explanations": {"惩罚": "惩罚：对迟到这种过错给予处分，与“迟到的学生”搭配。", "表扬": "语义：表扬是肯定好的行为，与“迟到”这一过错相矛盾。", "赞赏": "语义：赞赏是欣赏优点，不能用来说对迟到学生的处理。", "批改": "搭配：批改用于作业、试卷，不能说“批改学生”。"}, "sentence_index": 0, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在报告里惩罚了当时的政策。", "explanation": "这里应该用〈批评〉。惩罚针对犯错的人，政策是事物，不能被惩罚；批评可以用于政策和观点。"}, {"text": "他惩罚了这个错误的说法。", "explanation": "这里应该用〈纠正〉。纠正的对象可以是错误的说法，惩罚的对象只能是犯错的人。"}, {"text": "我们要尽快惩罚这个问题。", "explanation": "这里应该用〈处理〉。处理问题是设法解决，惩罚只用于犯错的人，不能用于“问题”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "惩罚", "is_correct": true, "explanation": "惩罚：依法对骗子给予处分，与“依法”的语境一致。"}, {"text": "招待", "is_correct": false, "explanation": "语义：招待是款待客人，“依法招待骗子”说不通。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢是表达谢意，法官不会对骗子表示谢意。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是讥讽，与法官依法办案的身份不符。"}], "explanations": {"惩罚": "惩罚：依法对骗子给予处分，与“依法”的语境一致。", "招待": "语义：招待是款待客人，“依法招待骗子”说不通。", "感谢": "语义：感谢是表达谢意，法官不会对骗子表示谢意。", "嘲笑": "语义：嘲笑是讥讽，与法官依法办案的身份不符。"}, "sentence_index": 6, "correct_answer": "惩罚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他惩罚了房东的损失。", "explanation": "这里应该用〈赔偿〉。赔偿是对损失给予补偿，惩罚的对象只能是做错事的人，“损失”不能被惩罚。"}, {"text": "工人惩罚了那台坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。修理是使坏了的物品恢复正常，惩罚的对象只能是做错事的人，不能用于洗衣机。"}, {"text": "医生惩罚了他的感冒。", "explanation": "这里应该用〈治疗〉。惩罚的对象只能是做错事的人，感冒是疾病，不能被惩罚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校对打架的学生惩罚的很严厉。", "corrected_sentence": "学校对打架的学生惩罚得很严厉。", "error_description": "结构助词错误：程度补语前应用“得”，“惩罚的很严厉”中的“的”应为“得”，正确说法是“惩罚得很严厉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察惩罚了过这个小偷。", "corrected_sentence": "警察惩罚过这个小偷。", "error_description": "错误在于“过”前多加了“了”。经历态“过”应紧跟动词，说“惩罚过这个小偷”，“惩罚了过这个小偷”不符合汉语的体标用法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不若的意思是不如，说这样做比那样做更好。", "primary_collocate": null, "pronunciation": "bù ruò", "ipa": "pu˥˩ ʐuo˥˩", "syllable_count": 2, "sentences": [{"text": "与其生气，不若笑一笑。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐车太挤，不若走路去学校。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其买新手机，不若把旧的修好。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想了一天，不若马上去做。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其看电视，不若出去跑跑步。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下得这么大，不若明天再去。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一直等下去，不若换个办法。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其说得多，不若做得好。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人去太无聊，不若叫上朋友。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其点外卖，不若自己煮碗面。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与其……不若……", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "不若：不如，说这样做比那样做更好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，与“与其生气”的比较关系不符。"}, {"text": "虽然", "is_correct": false, "explanation": "搭配：“虽然”要与后面的“但/却”呼应，不能与“与其”配合。"}, {"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进，与“与其……”表示的比较关系不符。"}, {"text": "不若", "is_correct": true, "explanation": "正确：“与其……不若……”表示比较，笑一笑比生气更好，符合句意。"}], "explanations": {"因此": "语义：“因此”表示因果，与“与其生气”的比较关系不符。", "虽然": "搭配：“虽然”要与后面的“但/却”呼应，不能与“与其”配合。", "而且": "语义：“而且”表示递进，与“与其……”表示的比较关系不符。", "不若": "正确：“与其……不若……”表示比较，笑一笑比生气更好，符合句意。"}, "sentence_index": 0, "correct_answer": "不若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想去，不若没有时间。", "explanation": "这里应该用〈但是〉。但是表示转折，不若表示比较，不能用来表示转折。"}, {"text": "他努力练习，不若提高了成绩。", "explanation": "这里应该用〈从而〉。从而引出结果，不若表示比较，不能引出结果。"}, {"text": "他说了很多，不若没有做。", "explanation": "这里应该用〈却〉。却是副词，表示转折，不若是连词，表示比较，不能用在这里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽管", "is_correct": false, "explanation": "语义：“尽管”表示让步，与“一直等下去”之后换办法的因果关系不符。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与后面的“就”呼应，这里没有条件关系，不能用“只要”。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示递进补充，与“一直等下去”的句意不协调。"}, {"text": "不若", "is_correct": true, "explanation": "正确：“一直等下去，不若换个办法”表示比较，继续等不如换办法，符合句意。"}], "explanations": {"尽管": "语义：“尽管”表示让步，与“一直等下去”之后换办法的因果关系不符。", "只要": "搭配：“只要”要与后面的“就”呼应，这里没有条件关系，不能用“只要”。", "况且": "语义：“况且”表示递进补充，与“一直等下去”的句意不协调。", "不若": "正确：“一直等下去，不若换个办法”表示比较，继续等不如换办法，符合句意。"}, "sentence_index": 6, "correct_answer": "不若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天很冷，不若我穿了厚衣服。", "explanation": "这里应该用〈所以〉。所以表示因果，不若表示比较，不能引出结果。"}, {"text": "他很努力，不若很快就成功了。", "explanation": "这里应该用〈因此〉。因此表示因果，不若表示比较，不能引出结果。"}, {"text": "我们去了公园，不若拍了照。", "explanation": "这里应该用〈并且〉。并且表示并列，不若表示比较，不能用在这两个动作的并列关系中。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "与其熬夜，不若的早点睡。", "corrected_sentence": "与其熬夜，不若早点睡。", "error_description": "助词错误：“不若”是连词，后面不能加“的”，应说“不若早点睡”，不能说“不若的早点睡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92651, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "与其等待，不若了主动联系他。", "corrected_sentence": "与其等待，不若主动联系他。", "error_description": "体貌错误：“不若”是连词，后面不能加“了”，应说“不若主动联系他”，不能说“不若了主动联系他”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
