INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92652, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不如；比不上（用于比较，引出更好的选择）。", "primary_collocate": null, "pronunciation": "bù ruò", "ipa": "pu˥˩ ʐuo˥˩", "syllable_count": 2, "sentences": [{"text": "与其在家等，不若出去走走。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其花钱买药，不若多运动。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走路太慢，不若坐地铁去。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么热，不若在家看书。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其一个人想，不若问问老师。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在外面吃饭太贵，不若自己做饭。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其抱怨天气，不若带把伞出门。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说得再好听，不若做出一点成绩。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "与其等朋友来，不若我们先去。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车堵得很，不若坐火车去北京。", "target_word": "不若", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "与其……不若……", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "不若：不如，比不上，引出更好的选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92652, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "而且", "is_correct": false, "explanation": "语义：“而且”表示递进，与“与其……”表示的比较关系不符。"}, {"text": "不过", "is_correct": false, "explanation": "搭配：“与其”要求后一分句用“不若”一类比较词，不能与“不过”配合。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果，这里是在两种做法之间比较选择，不能用因果关系。"}, {"text": "不若", "is_correct": true, "explanation": "正确：“与其……不若……”表示比较，后一种做法更好，符合句意。"}], "explanations": {"而且": "语义：“而且”表示递进，与“与其……”表示的比较关系不符。", "不过": "搭配：“与其”要求后一分句用“不若”一类比较词，不能与“不过”配合。", "所以": "语义：“所以”表示因果，这里是在两种做法之间比较选择，不能用因果关系。", "不若": "正确：“与其……不若……”表示比较，后一种做法更好，符合句意。"}, "sentence_index": 0, "correct_answer": "不若"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气很好，不若有点冷。", "explanation": "这里应该用〈不过〉。不过表示转折，不若表示比较，不能用来表示转折。"}, {"text": "快点走吧，不若要迟到了。", "explanation": "这里应该用〈否则〉。否则引出不这样做的后果，不若表示比较，不能引出后果。"}, {"text": "他努力复习，不若考了第一名。", "explanation": "这里应该用〈结果〉。结果引出动作的结局，不若表示比较，不能表示结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92652, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "然而", "is_correct": false, "explanation": "搭配：“与其”要用比较句式，不能与转折连词“然而”配合。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示因果，与“与其抱怨天气”的比较关系不符。"}, {"text": "并且", "is_correct": false, "explanation": "语义：“并且”表示并列，与“与其……”的比较关系不符。"}, {"text": "不若", "is_correct": true, "explanation": "正确：“与其……不若……”表示比较，句子说明带伞出门比抱怨更好，符合句意。"}], "explanations": {"然而": "搭配：“与其”要用比较句式，不能与转折连词“然而”配合。", "因此": "语义：“因此”表示因果，与“与其抱怨天气”的比较关系不符。", "并且": "语义：“并且”表示并列，与“与其……”的比较关系不符。", "不若": "正确：“与其……不若……”表示比较，句子说明带伞出门比抱怨更好，符合句意。"}, "sentence_index": 6, "correct_answer": "不若"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他很聪明，不若很努力。", "explanation": "这里应该用〈而且〉。而且表示并列或递进，不若表示比较，不能用在这里。"}, {"text": "票卖完了，不若没买到。", "explanation": "这里应该用〈可惜〉。可惜表示遗憾，不若表示比较，句子里不能表达遗憾。"}, {"text": "下雨了，不若比赛取消了。", "explanation": "这里应该用〈因此〉。因此引出结果，不若表示比较，不能引出结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92652, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "与其在家干等，不若的出去找找工作。", "corrected_sentence": "与其在家干等，不若出去找找工作。", "error_description": "助词错误：“不若”是连词，后面不能加“的”，应说“不若出去找找工作”，不能说“不若的出去找找工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92652, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "与其坐车，不若了骑车去。", "corrected_sentence": "与其坐车，不若骑车去。", "error_description": "体貌错误：“不若”是连词，后面不能加“了”，应说“不若骑车去”，不能说“不若了骑车去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
