INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "预先确定；规定。", "primary_collocate": null, "pronunciation": "zhǐ dìng", "ipa": "ʈʂɨ˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "学校指定了新的上课时间。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司指定了这次活动的时间和地点。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教育部指定了这门课程的统一教材。", "target_word": "指定", "complexity_tier": "T3", "furigana": "教育部<ruby>指定<rt>zhǐ dìng</rt></ruby>了这门课程的统一教材。", "sentence_source": "generated"}, {"text": "医生为病人指定了每天吃药的时间。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师提前指定了考试的范围。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大会指定十月一日为开会日期。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛的时间是由组织者提前指定的。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们早就指定好了旅行路线。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家指定这条河为保护区。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校为每个班指定了打扫的区域。", "target_word": "指定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指定了", "label": "完成体"}, {"form": "指定过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "事先确定时间、范围、计划等并作出规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92654, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "指定", "is_correct": true, "explanation": "“指定”表示学校预先确定上课时间，符合句意。"}, {"text": "购买", "is_correct": false, "explanation": "语义：时间不能被购买，“购买”与“上课时间”不搭。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，时间不能被打扫。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”要求食物做宾语，不能以“新的上课时间”为宾语。"}], "explanations": {"指定": "“指定”表示学校预先确定上课时间，符合句意。", "购买": "语义：时间不能被购买，“购买”与“上课时间”不搭。", "打扫": "搭配：“打扫”的对象是场所或物品，时间不能被打扫。", "吃": "配价：“吃”要求食物做宾语，不能以“新的上课时间”为宾语。"}, "sentence_index": 0, "correct_answer": "指定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我指定下个月辞职。", "explanation": "这里应该用〈决定〉。指定是由某方选定或规定，不用于个人自己拿主意。"}, {"text": "我指定明天会下雨。", "explanation": "这里应该用〈希望〉。指定的对象是人或事物，不能用来表达对事情的愿望。"}, {"text": "医生指定病人的病情。", "explanation": "这里应该用〈诊断〉。指定是预先确定或规定，不能用来判断病情，应说“诊断病人的病情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "指定", "is_correct": true, "explanation": "“指定”表示事先确定，符合“比赛时间由组织者提前确定”的句意。"}, {"text": "制造", "is_correct": false, "explanation": "搭配：“制造”用于产品或物品，不能用来确定比赛时间。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指把物体烧坏，与“比赛时间”不搭。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是艺术或景色，不能用来确定时间。"}], "explanations": {"指定": "“指定”表示事先确定，符合“比赛时间由组织者提前确定”的句意。", "制造": "搭配：“制造”用于产品或物品，不能用来确定比赛时间。", "烧毁": "语义：“烧毁”指把物体烧坏，与“比赛时间”不搭。", "欣赏": "语义：“欣赏”的对象是艺术或景色，不能用来确定时间。"}, "sentence_index": 6, "correct_answer": "指定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家指定了这个问题。", "explanation": "这里应该用〈讨论〉。指定是选定或规定，不能用于讨论问题。"}, {"text": "我向老师指定问题。", "explanation": "这里应该用〈请教〉。指定是事先选定或规定，不表示向人求教，向老师求教应说“请教”。"}, {"text": "我指定他的消息。", "explanation": "这里应该用〈打听〉。指定不能用于探问消息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "领导已经指定了好开会的地点。", "corrected_sentence": "领导已经指定好了开会的地点。", "error_description": "结果补语“好”要紧跟动词，应说“指定好了”，不能说“指定了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些作业是由组长指定。", "corrected_sentence": "这些作业是由组长指定的。", "error_description": "“由……指定的”是固定结构，缺少“的”，句子不完整，应补上“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
