INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不过如此是说一件事没有想的那么好，也没有想的那么难。", "primary_collocate": null, "pronunciation": "bú guò rú cǐ", "ipa": "pu˧˥ kuɔ˥˩ ʐu˧˥ tsʰɹ̩˨˩˦", "syllable_count": 4, "sentences": [{"text": "我以为汉语考试很难，其实不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听别人说骑马很可怕，试了以后觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜看起来很难做，做完觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐飞机我以前很怕，现在觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个大学很有名，进去看了看，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说工作很累，我做了一个月，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说搬家很麻烦，我搬完觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次住五星酒店，我觉得也不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕这次比赛，对手的水平不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说学游泳很难，我学了几天，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "事情没想的那么好或那么难", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不过如此", "is_correct": true, "explanation": "“不过如此”表示事情没有想象的那么难，与前句“我以为很难”形成转折，符合语境。"}, {"text": "很冷", "is_correct": false, "explanation": "语义：“冷”说的是温度，用来形容考试的难易说不通。"}, {"text": "很圆", "is_correct": false, "explanation": "搭配：“圆”不用来描述考试的难易，与“其实”后的评价不搭。"}, {"text": "很瘦", "is_correct": false, "explanation": "体貌：“瘦”描述人的身材，不能用来评价考试。"}], "explanations": {"不过如此": "“不过如此”表示事情没有想象的那么难，与前句“我以为很难”形成转折，符合语境。", "很冷": "语义：“冷”说的是温度，用来形容考试的难易说不通。", "很圆": "搭配：“圆”不用来描述考试的难易，与“其实”后的评价不搭。", "很瘦": "体貌：“瘦”描述人的身材，不能用来评价考试。"}, "sentence_index": 0, "correct_answer": "不过如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位歌手的嗓音真是不过如此，观众都听得入迷。", "explanation": "褒贬误用：这里把“不过如此”当成了夸奖，但它表示平常，与“听得入迷”的赞美相矛盾。"}, {"text": "这部电影我看了三遍，每次都觉得不过如此。", "explanation": "这里应该用〈感人〉。“不过如此”表示没有想的那么好，与“看了三遍”的反复欣赏相矛盾。"}, {"text": "这次考试比我想的难多了，我觉得不过如此。", "explanation": "这里应该用〈棘手〉。“不过如此”表示没有想的那么难，与“比我想的难多了”正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不过如此", "is_correct": true, "explanation": "“不过如此”表示搬完后觉得并没有想象的那么麻烦，与前句“搬家很麻烦”形成转折，符合语境。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，与搬家的感受无关。"}, {"text": "很胖", "is_correct": false, "explanation": "体貌：“胖”描述人的体型，不能用来形容搬家后的感觉。"}, {"text": "很亮", "is_correct": false, "explanation": "搭配：“亮”多描述光线或颜色，用来说搬完后的感受搭配不当。"}], "explanations": {"不过如此": "“不过如此”表示搬完后觉得并没有想象的那么麻烦，与前句“搬家很麻烦”形成转折，符合语境。", "很甜": "语义：“甜”说的是味道，与搬家的感受无关。", "很胖": "体貌：“胖”描述人的体型，不能用来形容搬家后的感觉。", "很亮": "搭配：“亮”多描述光线或颜色，用来说搬完后的感受搭配不当。"}, "sentence_index": 6, "correct_answer": "不过如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老师的讲解很精彩，学生们却都觉得不过如此，频频鼓掌。", "explanation": "褒贬误用：“不过如此”只表示平常，这里却与“很精彩”和“频频鼓掌”相矛盾，把它当成了赞美。"}, {"text": "这道题的难度不过如此，我绞尽脑汁也做不出来。", "explanation": "这里应该用〈棘手〉。“不过如此”表示没有想的那么难，与“绞尽脑汁也做不出来”正相反。"}, {"text": "这份作业不过如此，我们熬了一整夜。", "explanation": "这里应该用〈吃力〉。“不过如此”表示没有想的那么难，与“熬了一整夜”的辛苦正相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次体检的流程我以前很担心，走完一遍觉得很不过如此。", "corrected_sentence": "这次体检的流程我以前很担心，走完一遍觉得不过如此。", "error_description": "错误形式：“很不过如此”；正确形式：“不过如此”。“不过如此”已经表示平常，前面不能加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92657, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新搬的小区环境我原来很担心，住了几天觉得很不过如此。", "corrected_sentence": "新搬的小区环境我原来很担心，住了几天觉得不过如此。", "error_description": "错误形式：“很不过如此”；正确形式：“不过如此”。“不过如此”本身已表示没有想的那么好或那么难，前面不能加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
