INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92658, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不过是这样而已；形容事物平常，并不像预期的那样特别。", "primary_collocate": null, "pronunciation": "bú guò rú cǐ", "ipa": "pu˧˥ kuɔ˥˩ ʐu˧˥ tsʰɹ̩˨˩˦", "syllable_count": 4, "sentences": [{"text": "大家都说那个地方很美，我看不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店这么有名，吃了以后觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听朋友说这家店的蛋糕全城第一，我尝了一口，不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我以为那部电影多好看，结果不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的本事也不过如此，不用怕他。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山看起来很高，爬上去才知道不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名气很大的手机，用了几天，也不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个游戏很好玩，我玩了觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "见到那位明星，我觉得他也不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人夸这本书，可是我觉得不过如此。", "target_word": "不过如此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "事物平常，不如预期特别", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不过如此", "is_correct": true, "explanation": "“不过如此”表示不过是这样而已，与前句“大家都说很美”形成转折，符合语境。"}, {"text": "很高", "is_correct": false, "explanation": "语义：“高”说的是高度，不用来评价一个地方的整体观感，“我看很高”与“很美”的评价无关。"}, {"text": "很重", "is_correct": false, "explanation": "搭配：“重”多指分量或严重程度，不能用来表示对地方的观感。"}, {"text": "很硬", "is_correct": false, "explanation": "语义：“硬”描述质地，用来说一个地方的观感说不通。"}], "explanations": {"不过如此": "“不过如此”表示不过是这样而已，与前句“大家都说很美”形成转折，符合语境。", "很高": "语义：“高”说的是高度，不用来评价一个地方的整体观感，“我看很高”与“很美”的评价无关。", "很重": "搭配：“重”多指分量或严重程度，不能用来表示对地方的观感。", "很硬": "语义：“硬”描述质地，用来说一个地方的观感说不通。"}, "sentence_index": 0, "correct_answer": "不过如此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座小城的风景真是不过如此，让每个游客都流连忘返。", "explanation": "褒贬误用：这里把“不过如此”当成了赞美，但它表示事物平常、没有特别之处，不能用来夸风景，与“流连忘返”相矛盾。"}, {"text": "这份礼物让我觉得不过如此，我感动得说不出话来。", "explanation": "这里应该用〈令人动容〉。“不过如此”只说事物平常，用来评价礼物时与“感动得说不出话”的深受触动正相反。"}, {"text": "这家餐厅的菜真是不过如此，大家都赞不绝口。", "explanation": "这里把“不过如此”当成了夸奖，但它表示平常，与“赞不绝口”相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不过如此", "is_correct": true, "explanation": "“不过如此”表示不过这样而已，与前句“名气很大”形成落差，符合语境。"}, {"text": "很胖", "is_correct": false, "explanation": "体貌：“胖”描述人的体型，不用来形容手机，读起来不通。"}, {"text": "很辣", "is_correct": false, "explanation": "语义：“辣”说的是味道，与手机的使用体验无关。"}, {"text": "很偏僻", "is_correct": false, "explanation": "语义：“偏僻”描述的是地方，不适用于评价手机。"}], "explanations": {"不过如此": "“不过如此”表示不过这样而已，与前句“名气很大”形成落差，符合语境。", "很胖": "体貌：“胖”描述人的体型，不用来形容手机，读起来不通。", "很辣": "语义：“辣”说的是味道，与手机的使用体验无关。", "很偏僻": "语义：“偏僻”描述的是地方，不适用于评价手机。"}, "sentence_index": 6, "correct_answer": "不过如此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课的内容很精彩，同学们却都觉得不过如此，纷纷称赞。", "explanation": "褒贬误用：“不过如此”只表示平常，这里却与“精彩”和“纷纷称赞”相矛盾，把它当成了赞美。"}, {"text": "这场比赛的结果不过如此，全场观众都站了起来。", "explanation": "这里应该用〈惊人〉。“不过如此”表示平常，不能用来形容让全场观众站起来的结果。"}, {"text": "这次考试的题目不过如此，大家都交了白卷。", "explanation": "这里应该用〈很难〉。“不过如此”表示平常、没有那么难，与“大家都交了白卷”的困境相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部新出的动画片我看了，觉得很不过如此。", "corrected_sentence": "这部新出的动画片我看了，觉得不过如此。", "error_description": "错误形式：“很不过如此”；正确形式：“不过如此”。“不过如此”本身已经表示平常、不特别，前面不能再加“很”修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家新开的咖啡店我去过，感觉很不过如此。", "corrected_sentence": "这家新开的咖啡店我去过，感觉不过如此。", "error_description": "错误形式：“很不过如此”；正确形式：“不过如此”。“不过如此”本身已表示平常，前面不能加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
