INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92659, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搬是把东西从一个地方拿到另一个地方。", "primary_collocate": null, "pronunciation": "bān", "ipa": "pan˥", "syllable_count": 1, "sentences": [{"text": "请把这些书搬到我的房间。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把小凳子搬到了窗户旁边。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我把花搬进屋里。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，快把外面的椅子搬进来。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把一盆花从阳台搬到客厅。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们帮我搬了几箱水果。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把电视搬到别的房间去。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把空盒子搬出了办公室。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸搬来了一把椅子让我坐。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能把这些杯子搬到厨房吗？", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搬了", "label": "体标（了）"}, {"form": "搬着", "label": "体标（着）"}, {"form": "搬过", "label": "体标（过）"}, {"form": "搬运", "label": "复合"}], "register": "中性", "sense_fingerprint": "把东西从一处拿到另一处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92659, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：搬（bān），指把东西从一处拿到另一处。"}, {"text": "翻", "is_correct": false, "explanation": "声母不同：fān（翻）与 bān（搬）的声母一个是 f、一个是 b，意思是翻转、翻译。"}, {"text": "担", "is_correct": false, "explanation": "声母不同：dān（担）与 bān（搬）的声母一个是 d、一个是 b，意思是挑、承担。"}, {"text": "帮", "is_correct": false, "explanation": "韵尾不同：bāng（帮）与 bān（搬）的韵尾一个是 ng、一个是 n，意思是帮助。"}, {"text": "半", "is_correct": false, "explanation": "声调不同：bàn（半）与 bān（搬）声调不同，分别是第四声和第一声，意思是一半。"}, {"text": "干", "is_correct": false, "explanation": "声母不同：gān（干）与 bān（搬）的声母一个是 g、一个是 b，意思是干燥、做。"}], "explanations": {"搬": "正确：搬（bān），指把东西从一处拿到另一处。", "翻": "声母不同：fān（翻）与 bān（搬）的声母一个是 f、一个是 b，意思是翻转、翻译。", "担": "声母不同：dān（担）与 bān（搬）的声母一个是 d、一个是 b，意思是挑、承担。", "帮": "韵尾不同：bāng（帮）与 bān（搬）的韵尾一个是 ng、一个是 n，意思是帮助。", "半": "声调不同：bàn（半）与 bān（搬）声调不同，分别是第四声和第一声，意思是一半。", "干": "声母不同：gān（干）与 bān（搬）的声母一个是 g、一个是 b，意思是干燥、做。"}, "sentence_index": null, "correct_answer": "搬"}, "level_3": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：「搬」表示把书从一处移到另一处，句意通顺。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，书不能唱到房间去。"}, {"text": "哭", "is_correct": false, "explanation": "配价：「哭」是不及物动词，不能带「把这些书」作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，书不能吃到房间去。"}], "explanations": {"搬": "正确：「搬」表示把书从一处移到另一处，句意通顺。", "唱": "语义：唱的对象是歌曲，书不能唱到房间去。", "哭": "配价：「哭」是不及物动词，不能带「把这些书」作宾语。", "吃": "语义：吃的对象是食物，书不能吃到房间去。"}, "sentence_index": 0, "correct_answer": "搬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "快去把客人搬进来。", "explanation": "这里应该用〈接〉。搬是搬运物体，不能用于接人。"}, {"text": "他把脸搬干净了。", "explanation": "这里应该用〈擦〉。搬是搬运物体，脸不能搬；擦脸才说擦干净。"}, {"text": "他把话搬清楚了。", "explanation": "这里应该用〈说〉。搬用于物体的移动，不能说把话搬清楚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92659, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：搬（bān），指把东西从一处拿到另一处。"}, {"text": "办", "is_correct": false, "explanation": "声调不同：bàn（办）与 bān（搬）声调不同，分别是第四声和第一声，意思是办理。"}, {"text": "摊", "is_correct": false, "explanation": "声母不同：tān（摊）与 bān（搬）的声母一个是 t、一个是 b，意思是摊开、摊位。"}, {"text": "版", "is_correct": false, "explanation": "声调不同：bǎn（版）与 bān（搬）声调不同，分别是第三声和第一声，意思是版面。"}, {"text": "伴", "is_correct": false, "explanation": "声调不同：bàn（伴）与 bān（搬）声调不同，分别是第四声和第一声，意思是陪同。"}, {"text": "扮", "is_correct": false, "explanation": "声调不同：bàn（扮）与 bān（搬）声调不同，分别是第四声和第一声，意思是扮演。"}], "explanations": {"搬": "正确：搬（bān），指把东西从一处拿到另一处。", "办": "声调不同：bàn（办）与 bān（搬）声调不同，分别是第四声和第一声，意思是办理。", "摊": "声母不同：tān（摊）与 bān（搬）的声母一个是 t、一个是 b，意思是摊开、摊位。", "版": "声调不同：bǎn（版）与 bān（搬）声调不同，分别是第三声和第一声，意思是版面。", "伴": "声调不同：bàn（伴）与 bān（搬）声调不同，分别是第四声和第一声，意思是陪同。", "扮": "声调不同：bàn（扮）与 bān（搬）声调不同，分别是第四声和第一声，意思是扮演。"}, "sentence_index": null, "correct_answer": "搬"}, "level_3": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：「搬」表示把电视移到别的房间，句意通顺。"}, {"text": "笑", "is_correct": false, "explanation": "配价：「笑」是不及物动词，不能带「把电视」作宾语。"}, {"text": "写", "is_correct": false, "explanation": "语义：写的对象是文字，不能把电视写到别的房间。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮的对象是食物，电视不能煮，句意不通。"}], "explanations": {"搬": "正确：「搬」表示把电视移到别的房间，句意通顺。", "笑": "配价：「笑」是不及物动词，不能带「把电视」作宾语。", "写": "语义：写的对象是文字，不能把电视写到别的房间。", "煮": "语义：煮的对象是食物，电视不能煮，句意不通。"}, "sentence_index": 6, "correct_answer": "搬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把头发搬短了。", "explanation": "这里应该用〈剪〉。搬用于移动物体，不能说把头发搬短。"}, {"text": "他搬到了钥匙。", "explanation": "这里应该用〈找〉。搬是把东西移到别处，不能用来表示找到东西。"}, {"text": "他把字搬得很漂亮。", "explanation": "这里应该用〈写〉。搬用于搬运物体，不能用来形容写字的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
