INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92660, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "移动较重或较大的物体，使其离开原来位置；也指迁移。", "primary_collocate": null, "pronunciation": "bān", "ipa": "pan˥", "syllable_count": 1, "sentences": [{"text": "他一个人搬了一张大桌子。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子太重，我搬不动。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我把沙发搬到楼上。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在搬新买的冰箱。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下个月要搬到新家去。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬着一个大箱子走进了教室。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生把椅子搬出去。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时搬过很多石头。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李搬到北京以后，工作很忙。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块大石头两个人都搬不起来。", "target_word": "搬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搬了", "label": "体标（了）"}, {"form": "搬着", "label": "体标（着）"}, {"form": "搬过", "label": "体标（过）"}, {"form": "搬运", "label": "复合"}], "register": "中性", "sense_fingerprint": "移动较重较大的物体离开原位，也指迁居", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92660, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：搬（bān），指把较重较大的物体移到别处，也指迁居。"}, {"text": "翻", "is_correct": false, "explanation": "声母不同：fān（翻）与 bān（搬）的声母一个是 f、一个是 b，意思是翻转、翻译。"}, {"text": "担", "is_correct": false, "explanation": "声母不同：dān（担）与 bān（搬）的声母一个是 d、一个是 b，意思是挑、承担。"}, {"text": "帮", "is_correct": false, "explanation": "韵尾不同：bāng（帮）与 bān（搬）的韵尾一个是 ng、一个是 n，意思是帮助。"}, {"text": "半", "is_correct": false, "explanation": "声调不同：bàn（半）与 bān（搬）声调不同，分别是第四声和第一声，意思是一半。"}, {"text": "板", "is_correct": false, "explanation": "声调不同：bǎn（板）与 bān（搬）声调不同，分别是第三声和第一声，意思是木板。"}, {"text": "干", "is_correct": false, "explanation": "声母不同：gān（干）与 bān（搬）的声母一个是 g、一个是 b，意思是干燥、做。"}], "explanations": {"搬": "正确：搬（bān），指把较重较大的物体移到别处，也指迁居。", "翻": "声母不同：fān（翻）与 bān（搬）的声母一个是 f、一个是 b，意思是翻转、翻译。", "担": "声母不同：dān（担）与 bān（搬）的声母一个是 d、一个是 b，意思是挑、承担。", "帮": "韵尾不同：bāng（帮）与 bān（搬）的韵尾一个是 ng、一个是 n，意思是帮助。", "半": "声调不同：bàn（半）与 bān（搬）声调不同，分别是第四声和第一声，意思是一半。", "板": "声调不同：bǎn（板）与 bān（搬）声调不同，分别是第三声和第一声，意思是木板。", "干": "声母不同：gān（干）与 bān（搬）的声母一个是 g、一个是 b，意思是干燥、做。"}, "sentence_index": null, "correct_answer": "搬"}, "level_3": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：「搬」用于搬运较重的物体，与「一张大桌子」搭配。"}, {"text": "读", "is_correct": false, "explanation": "语义：读的对象是文字，不能读一张大桌子。"}, {"text": "哭", "is_correct": false, "explanation": "配价：「哭」是不及物动词，不能带「一张大桌子」这样的宾语。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱的对象是歌曲，不能唱一张桌子。"}], "explanations": {"搬": "正确：「搬」用于搬运较重的物体，与「一张大桌子」搭配。", "读": "语义：读的对象是文字，不能读一张大桌子。", "哭": "配价：「哭」是不及物动词，不能带「一张大桌子」这样的宾语。", "唱": "语义：唱的对象是歌曲，不能唱一张桌子。"}, "sentence_index": 0, "correct_answer": "搬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈搬着孩子睡觉。", "explanation": "这里应该用〈抱〉。搬用于较重的物体，抱孩子才是双臂环抱，不说搬孩子。"}, {"text": "他搬着老人过马路。", "explanation": "这里应该用〈扶〉。搬指搬运物体，扶老人过马路要搀扶，不能说搬老人。"}, {"text": "他搬着一封信走进了办公室。", "explanation": "这里应该用〈拿〉。搬用于较重或较大的物体，信件很轻，应说拿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92660, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：搬（bān），指把较重较大的物体移到别处，也指迁居。"}, {"text": "办", "is_correct": false, "explanation": "声调不同：bàn（办）与 bān（搬）声调不同，分别是第四声和第一声，意思是办理。"}, {"text": "摊", "is_correct": false, "explanation": "声母不同：tān（摊）与 bān（搬）的声母一个是 t、一个是 b，意思是摊开、摊位。"}, {"text": "版", "is_correct": false, "explanation": "声调不同：bǎn（版）与 bān（搬）声调不同，分别是第三声和第一声，意思是版面。"}, {"text": "伴", "is_correct": false, "explanation": "声调不同：bàn（伴）与 bān（搬）声调不同，分别是第四声和第一声，意思是陪同。"}, {"text": "扮", "is_correct": false, "explanation": "声调不同：bàn（扮）与 bān（搬）声调不同，分别是第四声和第一声，意思是扮演。"}], "explanations": {"搬": "正确：搬（bān），指把较重较大的物体移到别处，也指迁居。", "办": "声调不同：bàn（办）与 bān（搬）声调不同，分别是第四声和第一声，意思是办理。", "摊": "声母不同：tān（摊）与 bān（搬）的声母一个是 t、一个是 b，意思是摊开、摊位。", "版": "声调不同：bǎn（版）与 bān（搬）声调不同，分别是第三声和第一声，意思是版面。", "伴": "声调不同：bàn（伴）与 bān（搬）声调不同，分别是第四声和第一声，意思是陪同。", "扮": "声调不同：bàn（扮）与 bān（搬）声调不同，分别是第四声和第一声，意思是扮演。"}, "sentence_index": null, "correct_answer": "搬"}, "level_3": {"options": [{"text": "搬", "is_correct": true, "explanation": "正确：「搬」表示把椅子移到别处，句意通顺。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃的对象是食物，不能把椅子吃出去。"}, {"text": "笑", "is_correct": false, "explanation": "配价：「笑」是不及物动词，不能带「把椅子」作宾语。"}, {"text": "写", "is_correct": false, "explanation": "语义：写的对象是文字，不能把椅子写出去。"}], "explanations": {"搬": "正确：「搬」表示把椅子移到别处，句意通顺。", "吃": "语义：吃的对象是食物，不能把椅子吃出去。", "笑": "配价：「笑」是不及物动词，不能带「把椅子」作宾语。", "写": "语义：写的对象是文字，不能把椅子写出去。"}, "sentence_index": 6, "correct_answer": "搬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她搬了一首歌。", "explanation": "这里应该用〈唱〉。搬是搬运有形的重物，不能用于歌曲。"}, {"text": "他搬了一脚球。", "explanation": "这里应该用〈踢〉。搬指搬运物体，不能用来表示踢球这类动作。"}, {"text": "他搬着一碗热汤走进了厨房。", "explanation": "这里应该用〈端〉。搬用于较重或较大的物体，端碗、端汤这类轻小的东西要说端，不说搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92660, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子不重，我搬动得。", "corrected_sentence": "这个箱子不重，我搬得动。", "error_description": "可能补语的肯定形式应为“搬得动”，“得”在“搬”和“动”之间；“搬动得”不成词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92660, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他沙发搬进了客厅。", "corrected_sentence": "他把沙发搬进了客厅。", "error_description": "漏掉处置介词「把」。「沙发」是被搬动的对象，需用「把」引出，应说「他把沙发搬进了客厅」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
