INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92662, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "我国行使审判权的国家机关，负责审理各类案件。", "primary_collocate": null, "pronunciation": "rén mín fǎ yuàn", "ipa": "ʐən˧˥ min˧˥ fa˨˩˦ ɥɛn˥˩", "syllable_count": 4, "sentences": [{"text": "人民法院依法审理这起案件。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不服判决，向人民法院提出上诉。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院是国家的审判机关。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院已经受理了他的起诉。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院公开审理了这个案子。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公民可以到人民法院起诉。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院根据法律作出了判决。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院要保护每个人的合法权利。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子由人民法院负责审理。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民法院判他赔偿对方五万元。", "target_word": "人民法院", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "行使审判权、审理案件的国家机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5defac78-781a-4fa9-9921-04631e3ba9d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人民法院", "is_correct": true, "explanation": "正确：审理案件是人民法院的职能，“依法审理”符合司法机关的性质。"}, {"text": "律师", "is_correct": false, "explanation": "语义：律师代理案件，不审理案件。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不承担审理案件的职能。"}, {"text": "公司", "is_correct": false, "explanation": "配价：“审理”的主语必须是司法机关，公司不能作审理案件的主语。"}], "explanations": {"人民法院": "正确：审理案件是人民法院的职能，“依法审理”符合司法机关的性质。", "律师": "语义：律师代理案件，不审理案件。", "学校": "语义：学校不承担审理案件的职能。", "公司": "配价：“审理”的主语必须是司法机关，公司不能作审理案件的主语。"}, "sentence_index": 0, "correct_answer": "人民法院"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人民法院已经受理了他的报案。", "explanation": "这里应该用〈公安局〉。报案要向公安机关提出，人民法院审理案件，不受理报案。"}, {"text": "我去人民法院交了个人所得税。", "explanation": "这里应该用〈税务局〉。交个人所得税要去税务局，人民法院是审判机关，不负责征税。"}, {"text": "我去人民法院办了户口。", "explanation": "这里应该用〈派出所〉。办户口要去派出所，人民法院是审判机关，不办户籍手续。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人民法院", "is_correct": true, "explanation": "正确：“作出判决”是人民法院的职能，“根据法律”指依法裁判。"}, {"text": "警察", "is_correct": false, "explanation": "语义：警察负责侦查和执法，不作出判决。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是违法的人，不能根据法律作出判决。"}, {"text": "幼儿园", "is_correct": false, "explanation": "配价：“作出判决”的施事必须是司法机关或法官，幼儿园不能作主语。"}], "explanations": {"人民法院": "正确：“作出判决”是人民法院的职能，“根据法律”指依法裁判。", "警察": "语义：警察负责侦查和执法，不作出判决。", "小偷": "语义：小偷是违法的人，不能根据法律作出判决。", "幼儿园": "配价：“作出判决”的施事必须是司法机关或法官，幼儿园不能作主语。"}, "sentence_index": 6, "correct_answer": "人民法院"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人民法院今天早上去超市买了菜。", "explanation": "此句把“人民法院”当成了去超市买菜的人，但它指国家审判机关，不能做购物这类动作。"}, {"text": "人民法院每周末都去电影院看电影。", "explanation": "此句把“人民法院”当成了看电影的观众，但它指国家审判机关，不能去电影院看电影。"}, {"text": "人民法院下班后去健身房锻炼身体。", "explanation": "此句把“人民法院”当成了去健身房锻炼的人，但它指国家审判机关，不能做这类个人活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "当事人可以给人民法院起诉。", "corrected_sentence": "当事人可以向人民法院起诉。", "error_description": "错误：“向”写成了“给”。起诉的对象是法院，应用“向＋对象”，说“向人民法院起诉”；“给人民法院起诉”不通。正确说法：当事人可以向人民法院起诉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔欠款已人民法院强制执行。", "corrected_sentence": "这笔欠款已由人民法院强制执行。", "error_description": "错误：漏掉了介词“由”。“已由人民法院强制执行”是规范说法，“由”引出执行的施事；省略后“已人民法院强制执行”不够规范。正确说法：这笔欠款已由人民法院强制执行。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9b9ee37d-0391-46fc-ae73-27972dbd9808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
