INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92671, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "曝光是原来藏着的事被大家知道了。", "primary_collocate": null, "pronunciation": "bào guāng", "ipa": "pɑʊ˥˩ kuɑŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这件丑闻终于曝光了。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的秘密曝光后，朋友们都很吃惊。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的问题一曝光，股价就下跌。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个骗局昨天才曝光。", "target_word": "曝光", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "隐瞒多年的质量问题终于曝光了，引起大家关注。", "target_word": "曝光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事情曝光以后，经理马上向大家道歉。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家工厂的污染问题曝光过好几次。", "target_word": "曝光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怕假文凭曝光，所以不敢去上班。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个明星的私生活曝光后，粉丝很失望。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "骗人的事一旦曝光，他就没有朋友了。", "target_word": "曝光", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "曝光了", "label": "体标：了"}, {"form": "曝光过", "label": "体标：过"}, {"form": "曝光率", "label": "复合"}], "register": "中性", "sense_fingerprint": "隐藏的事被公众知道（不及物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92671, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "曝光", "is_correct": true, "explanation": "曝光：原本隐藏的丑闻被大家知道，与“终于”搭配。"}, {"text": "种植", "is_correct": false, "explanation": "语义：种植是栽培植物，丑闻不能被种植。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长指植物或生物长大，与丑闻无关。"}, {"text": "摆放", "is_correct": false, "explanation": "语义：摆放是把物品放置到某处，丑闻不能被摆放。"}], "explanations": {"曝光": "曝光：原本隐藏的丑闻被大家知道，与“终于”搭配。", "种植": "语义：种植是栽培植物，丑闻不能被种植。", "生长": "语义：生长指植物或生物长大，与丑闻无关。", "摆放": "语义：摆放是把物品放置到某处，丑闻不能被摆放。"}, "sentence_index": 0, "correct_answer": "曝光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天曝光了。", "explanation": "这里应该用〈下雨〉。曝光指原本隐藏的事被大家知道，天气不能“曝光”。"}, {"text": "公司正在曝光招聘新员工。", "explanation": "这里应该用〈公开〉。曝光指原本隐藏的坏事被揭出来，正常的招聘是公开进行的，不能说“曝光”。"}, {"text": "他每天曝光三公里。", "explanation": "这里应该用〈跑步〉。曝光指隐蔽的事被大家知道，跑三公里与隐蔽无关，不能用“曝光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92671, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "曝光", "is_correct": true, "explanation": "曝光：污染问题被揭露，可以发生好几次，与“过”搭配。"}, {"text": "生产", "is_correct": false, "explanation": "语义：生产指制造产品，污染问题不能被生产。"}, {"text": "批准", "is_correct": false, "explanation": "搭配：批准用于计划、申请，不能说“污染问题批准过”。"}, {"text": "参加", "is_correct": false, "explanation": "语义：参加指加入某项活动，污染问题不会参加活动，句子不通。"}], "explanations": {"曝光": "曝光：污染问题被揭露，可以发生好几次，与“过”搭配。", "生产": "语义：生产指制造产品，污染问题不能被生产。", "批准": "搭配：批准用于计划、申请，不能说“污染问题批准过”。", "参加": "语义：参加指加入某项活动，污染问题不会参加活动，句子不通。"}, "sentence_index": 6, "correct_answer": "曝光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "组委会曝光了比赛的赛程。", "explanation": "这里应该用〈公布〉。曝光指原本隐藏的坏事被揭出来，赛程是正常公布的信息，不能说“曝光”。"}, {"text": "政府曝光了新的交通规则。", "explanation": "这里应该用〈宣布〉。曝光要求事情原本隐蔽，正式发布的规定不能说“曝光”。"}, {"text": "我早上六点曝光。", "explanation": "这里应该用〈起床〉。曝光指原本隐藏的事被大家知道，起床是日常动作，不能用“曝光”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92671, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个谎言终于了曝光了。", "corrected_sentence": "这个谎言终于曝光了。", "error_description": "错误在于动词前多加了“了”。“了”应放在动词后，说“终于曝光了”，“终于了曝光了”不符合汉语语序。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92671, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事曝光的很快，大家都吃了一惊。", "corrected_sentence": "这件事曝光得很快，大家都吃了一惊。", "error_description": "错误在于补语标记。“曝光”后应用“得”引出补语“很快”，说“曝光得很快”，不能用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
