INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把物品、信息等从一处传递输送到另一处。", "primary_collocate": null, "pronunciation": "chuán sòng", "ipa": "ʈʂʰwan˧˥ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "网络可以很快传送信息。", "target_word": "传送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这份文件传送给我。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卫星把电视画面传送到千家万户。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话线能传送声音。", "target_word": "传送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手机把照片传送给朋友。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数据已经传送到公司了。", "target_word": "传送", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电脑正在传送着一份很大的文件。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业传送到学生的邮箱里。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条线路传送过很多重要的消息。", "target_word": "传送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手机把好消息传送给了全家人。", "target_word": "传送", "complexity_tier": "T3", "furigana": "tā yòng shǒu jī bǎ hǎo xiāo xi chuán sòng gěi le quán jiā rén", "sentence_source": "generated"}], "morphological_forms": [{"form": "传送了", "label": "体标"}, {"form": "传送着", "label": "体标"}, {"form": "传送过", "label": "体标"}, {"form": "传送带", "label": "复合"}], "register": "中性", "sense_fingerprint": "把物品或信息传递输送到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59765317-1277-4541-a33b-efb6288b49af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传送", "is_correct": true, "explanation": "传送：网络把信息从一处送到另一处，符合“网络”“很快”的语境。"}, {"text": "烤", "is_correct": false, "explanation": "语义：烤是用火加热食物，不能烤信息。"}, {"text": "咬", "is_correct": false, "explanation": "配价：咬要求具体的咬的动作对象，信息不能被咬。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：搬多用于具体物件，不说“搬信息”。"}], "explanations": {"传送": "传送：网络把信息从一处送到另一处，符合“网络”“很快”的语境。", "烤": "语义：烤是用火加热食物，不能烤信息。", "咬": "配价：咬要求具体的咬的动作对象，信息不能被咬。", "搬": "搭配：搬多用于具体物件，不说“搬信息”。"}, "sentence_index": 0, "correct_answer": "传送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "感冒会通过飞沫传送。", "explanation": "这里应该用〈传染〉。传送用于物品或信号，病毒通过飞沫扩散要用传染。"}, {"text": "伤口被细菌传送了。", "explanation": "这里应该用〈感染〉。伤口受细菌作用要用感染，传送不能这样用。"}, {"text": "他把礼物传送给了朋友。", "explanation": "这里应该用〈送〉。亲手交给朋友的礼物要用送，传送指借机器或信号输送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传送", "is_correct": true, "explanation": "传送：电脑把文件发送到别处，符合“电脑正在”“一份很大的文件”的语境。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：洗的对象是衣物、器皿，不说洗文件。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是用水加热，不能煮文件。"}, {"text": "喂", "is_correct": false, "explanation": "配价：喂要求有生命的受喂对象，文件不能被喂。"}], "explanations": {"传送": "传送：电脑把文件发送到别处，符合“电脑正在”“一份很大的文件”的语境。", "洗": "搭配：洗的对象是衣物、器皿，不说洗文件。", "煮": "语义：煮是用水加热，不能煮文件。", "喂": "配价：喂要求有生命的受喂对象，文件不能被喂。"}, "sentence_index": 6, "correct_answer": "传送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把孩子传送到了幼儿园。", "explanation": "这里应该用〈带〉。传送用于物品或信号，带孩子去幼儿园要用带。"}, {"text": "老师把学生传送到了操场。", "explanation": "这里应该用〈领〉。传送不用于人，领学生到操场要用领。"}, {"text": "我把奶奶传送到了椅子上。", "explanation": "这里应该用〈扶〉。传送用于物品，扶人坐下要用扶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92678, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用手机把照片传送了给同学。", "corrected_sentence": "他用手机把照片传送给了同学。", "error_description": "错误：“了”放在“传送”和“给”之间，位置不对。“了”应放在“给”之后，正确为“传送给了同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务器已经把日志全部传送了完。", "corrected_sentence": "服务器已经把日志全部传送完了。", "error_description": "错误：结果补语“完”与“了”顺序颠倒。“完”应紧跟动词，“了”放在句末，正确为“传送完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fb59baf-f1d9-4e45-a732-985786d797f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
