INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "正面是东西朝向我们的那一边。", "primary_collocate": null, "pronunciation": "zhèng miàn", "ipa": "tʂəŋ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这座房子的正面有一扇大门。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把卡片正面朝上放在桌子上。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片要从正面拍，才看得清楚。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张纸的正面写着我的名字。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在汽车的正面，向我挥手。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "硬币的正面是一朵花。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的正面有一只小猫。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你从正面看，这个杯子很漂亮。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校正面有一棵很高的大树。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把画的正面对着墙放好。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "东西朝向我们的主要一面，与背面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：zhèng miàn，指物体朝向我们的那一边。"}, {"text": "证件", "is_correct": false, "explanation": "证件（zhèngjiàn）与正面只有第二音节声母不同（j 与 m），意思是证件。"}, {"text": "政变", "is_correct": false, "explanation": "政变（zhèngbiàn）与正面只有第二音节声母不同（b 与 m），意思是政变。"}, {"text": "正念", "is_correct": false, "explanation": "正念（zhèngniàn）与正面只有第二音节声母不同（n 与 m），意思是专注于当下的心念。"}], "explanations": {"正面": "正确：zhèng miàn，指物体朝向我们的那一边。", "证件": "证件（zhèngjiàn）与正面只有第二音节声母不同（j 与 m），意思是证件。", "政变": "政变（zhèngbiàn）与正面只有第二音节声母不同（b 与 m），意思是政变。", "正念": "正念（zhèngniàn）与正面只有第二音节声母不同（n 与 m），意思是专注于当下的心念。"}, "sentence_index": null, "correct_answer": "正面"}, "level_3": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：“房子的正面有一扇大门”指房子朝向外面的一边，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不指位置，“颜色有一扇大门”不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指发出的声响，房子的声音不能“有一扇大门”，与句意不符。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”一般只用于人或动物，不说房子的身高。"}], "explanations": {"正面": "正确：“房子的正面有一扇大门”指房子朝向外面的一边，与句意相符。", "颜色": "语义：“颜色”指色彩，不指位置，“颜色有一扇大门”不通。", "声音": "语义：“声音”指发出的声响，房子的声音不能“有一扇大门”，与句意不符。", "身高": "搭配：“身高”一般只用于人或动物，不说房子的身高。"}, "sentence_index": 0, "correct_answer": "正面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个问题有三个正面需要解决。", "explanation": "这里应该用〈方面〉。“正面”指物体朝前的一面或事情积极的一面，问题的各个方面要用“方面”。"}, {"text": "他的正面很好听。", "explanation": "这里应该用〈嗓子〉。“正面”指物体朝向我们的一面或事情积极的一面，不能指人的声音，说声音好听要用“嗓子”。"}, {"text": "我们要开一场正面的比赛。", "explanation": "这里应该用〈正式〉。“正面”不能修饰比赛，表示按规定、规范的要说“正式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：zhèng miàn，指物体朝向我们的那一边。"}, {"text": "正片", "is_correct": false, "explanation": "正片（zhèngpiàn）与正面只有第二音节声母不同（p 与 m），意思是正片。"}, {"text": "账面", "is_correct": false, "explanation": "账面（zhàngmiàn）与正面只有第一音节韵母不同（ang 与 eng），意思是账目上的记载。"}, {"text": "正电", "is_correct": false, "explanation": "正电（zhèngdiàn）与正面只有第二音节声母不同（d 与 m），意思是正电荷。"}], "explanations": {"正面": "正确：zhèng miàn，指物体朝向我们的那一边。", "正片": "正片（zhèngpiàn）与正面只有第二音节声母不同（p 与 m），意思是正片。", "账面": "账面（zhàngmiàn）与正面只有第一音节韵母不同（ang 与 eng），意思是账目上的记载。", "正电": "正电（zhèngdiàn）与正面只有第二音节声母不同（d 与 m），意思是正电荷。"}, "sentence_index": null, "correct_answer": "正面"}, "level_3": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：“衣服的正面有一只小猫”指衣服朝前的一面印有图案，与句意相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，衣服的味道不能“有一只小猫”，与句意不符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指物体的长短，“长度有一只小猫”不通，与句意不符。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”一般用于人或动物，不说衣服的体重。"}], "explanations": {"正面": "正确：“衣服的正面有一只小猫”指衣服朝前的一面印有图案，与句意相符。", "味道": "语义：“味道”指气味或滋味，衣服的味道不能“有一只小猫”，与句意不符。", "长度": "语义：“长度”指物体的长短，“长度有一只小猫”不通，与句意不符。", "体重": "搭配：“体重”一般用于人或动物，不说衣服的体重。"}, "sentence_index": 6, "correct_answer": "正面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块木板的一只正面很光滑。", "explanation": "这里应该用〈个〉。“只”不用于“正面”这种表面的一边，应说“一个正面”。"}, {"text": "这本书的一条正面印着名字。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，不用于“正面”。"}, {"text": "这张卡片的一把正面写着字。", "explanation": "这里应该用〈个〉。“把”多用于有柄的物件，不用于“正面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座楼有一只正面朝南。", "corrected_sentence": "这座楼有一个正面朝南。", "error_description": "量词错误：“正面”作为物体的一面，量词应用“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92683, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "椅子的正面们朝向门口，很显眼。", "corrected_sentence": "椅子的正面朝向门口，很显眼。", "error_description": "词缀错误：“们”只用于指人，不能加在“正面”后，应去掉，说“椅子的正面朝向门口”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负面", "is_correct": true, "explanation": "反义：“负面”指事物消极、不好的一面，与“正面”相对。"}, {"text": "方向", "is_correct": false, "explanation": "无关：“方向”指位置或去向，与“正面”的反义无关。"}, {"text": "清晨", "is_correct": false, "explanation": "无关：“清晨”指一天的早晨时段，与“正面”没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "无关：“窗户”指建筑上透光通风的部分，与“正面”的反义无关。"}], "correct_answer": "负面", "explanations": {"负面": "反义：“负面”指事物消极、不好的一面，与“正面”相对。", "方向": "无关：“方向”指位置或去向，与“正面”的反义无关。", "清晨": "无关：“清晨”指一天的早晨时段，与“正面”没有反义关系。", "窗户": "无关：“窗户”指建筑上透光通风的部分，与“正面”的反义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "负面", "is_correct": true, "explanation": "反义：“负面”指事物消极、不好的一面，与“正面”相对。"}, {"text": "季节", "is_correct": false, "explanation": "无关：“季节”指一年中按气候划分的时段，与“正面”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "无关：“河流”指地表有水流动的水道，与“正面”的反义无关。"}, {"text": "课本", "is_correct": false, "explanation": "无关：“课本”指供学习用的书，与“正面”的反义无关。"}], "correct_answer": "负面", "explanations": {"负面": "反义：“负面”指事物消极、不好的一面，与“正面”相对。", "季节": "无关：“季节”指一年中按气候划分的时段，与“正面”没有反义关系。", "河流": "无关：“河流”指地表有水流动的水道，与“正面”的反义无关。", "课本": "无关：“课本”指供学习用的书，与“正面”的反义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物积极好的一面，与反面、负面相对。", "primary_collocate": null, "pronunciation": "zhèng miàn", "ipa": "tʂəŋ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "遇到问题，要多看事情的正面。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事也有它的正面作用。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看问题不要只看反面，也要看正面。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是看到生活的正面。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事对孩子有很多正面的影响。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上的消息，有正面的，也有负面的。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说这次失败也有正面的意义。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为给年轻人树立了正面的榜样。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书对学生有正面的帮助。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用正面的态度面对每一天。", "target_word": "正面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物积极好的一面，与反面、负面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：zhèng miàn，指事物积极好的一面。"}, {"text": "证件", "is_correct": false, "explanation": "证件（zhèngjiàn）与正面（zhèngmiàn）只有第二音节声母不同（j 与 m），意思是证件，不是正面。"}, {"text": "政变", "is_correct": false, "explanation": "政变（zhèngbiàn）与正面只有第二音节声母不同（b 与 m），意思是政变。"}, {"text": "正念", "is_correct": false, "explanation": "正念（zhèngniàn）与正面只有第二音节声母不同（n 与 m），意思是专注于当下的心念。"}], "explanations": {"正面": "正确：zhèng miàn，指事物积极好的一面。", "证件": "证件（zhèngjiàn）与正面（zhèngmiàn）只有第二音节声母不同（j 与 m），意思是证件，不是正面。", "政变": "政变（zhèngbiàn）与正面只有第二音节声母不同（b 与 m），意思是政变。", "正念": "正念（zhèngniàn）与正面只有第二音节声母不同（n 与 m），意思是专注于当下的心念。"}, "sentence_index": null, "correct_answer": "正面"}, "level_3": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：“多看事情的正面”指事情积极的一面，与“遇到问题”的语境相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，事情没有颜色，与句意不符。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，不用来说事情，与句意不符。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”指平面的大小，一般不说事情的面积。"}], "explanations": {"正面": "正确：“多看事情的正面”指事情积极的一面，与“遇到问题”的语境相符。", "颜色": "语义：“颜色”指色彩，事情没有颜色，与句意不符。", "形状": "语义：“形状”指物体的外形，不用来说事情，与句意不符。", "面积": "搭配：“面积”指平面的大小，一般不说事情的面积。"}, "sentence_index": 0, "correct_answer": "正面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们从很多正面讨论这个问题。", "explanation": "这里应该用〈方面〉。正面专指事情积极好的一面，这里只是说从多个角度讨论，不分好坏，应该用“方面”。"}, {"text": "我们从经济正面分析这个问题。", "explanation": "这里应该用〈角度〉。“正面”指物体朝向我们的一面或事情积极的一面，不能指分析问题的角度，应说“从经济角度”。"}, {"text": "我们要举行正面的会议。", "explanation": "这里应该用〈正式〉。“正面”不能修饰会议，表示按规定、规范的要说“正式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：zhèng miàn，指事物积极好的一面。"}, {"text": "正片", "is_correct": false, "explanation": "正片（zhèngpiàn）与正面只有第二音节声母不同（p 与 m），意思是正片，指冲印出的正像照片或影片。"}, {"text": "账面", "is_correct": false, "explanation": "账面（zhàngmiàn）与正面只有第一音节韵母不同（ang 与 eng），意思是账目上的记载。"}, {"text": "正电", "is_correct": false, "explanation": "正电（zhèngdiàn）与正面只有第二音节声母不同（d 与 m），意思是正电荷。"}], "explanations": {"正面": "正确：zhèng miàn，指事物积极好的一面。", "正片": "正片（zhèngpiàn）与正面只有第二音节声母不同（p 与 m），意思是正片，指冲印出的正像照片或影片。", "账面": "账面（zhàngmiàn）与正面只有第一音节韵母不同（ang 与 eng），意思是账目上的记载。", "正电": "正电（zhèngdiàn）与正面只有第二音节声母不同（d 与 m），意思是正电荷。"}, "sentence_index": null, "correct_answer": "正面"}, "level_3": {"options": [{"text": "正面", "is_correct": true, "explanation": "正确：“有正面的意义”指失败中积极的一面，与“失败”的语境相符。"}, {"text": "长度", "is_correct": false, "explanation": "语义：“长度”指物体的长短，失败没有长度，与句意不符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”指气味或滋味，与“失败的意义”无关，与句意不符。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体所占的空间，一般不说失败的体积。"}], "explanations": {"正面": "正确：“有正面的意义”指失败中积极的一面，与“失败”的语境相符。", "长度": "语义：“长度”指物体的长短，失败没有长度，与句意不符。", "味道": "语义：“味道”指气味或滋味，与“失败的意义”无关，与句意不符。", "体积": "搭配：“体积”指物体所占的空间，一般不说失败的体积。"}, "sentence_index": 6, "correct_answer": "正面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事的一只正面很值得大家学习。", "explanation": "这里应该用〈个〉。“只”用于动物或成对物品中的一个，不用于“正面”这种抽象的方面。"}, {"text": "他身上的一条正面让我很佩服。", "explanation": "这里应该用〈个〉。“条”多用于细长的东西，不用于“正面”。"}, {"text": "这次比赛的一把正面给我们留下了深刻印象。", "explanation": "这里应该用〈个〉。“把”多用于有柄的物件，不用于“正面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事有一只正面，也有一个负面。", "corrected_sentence": "这件事有一个正面，也有一个负面。", "error_description": "量词错误：“正面”作名词指一个方面，应该用量词“个”，不能用“只”。“只”不用于这类抽象的方面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92684, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她用正面地心态看待每件事。", "corrected_sentence": "她用正面的心态看待每件事。", "error_description": "助词错误：“正面”修饰名词“心态”时应用结构助词“的”，不能用“地”；“地”用于动词、形容词前作状语，如“正面地看待”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
