INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92687, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "毁是把东西弄坏，弄没有了。", "primary_collocate": null, "pronunciation": "huǐ", "ipa": "xweɪ˨˩˦", "syllable_count": 1, "sentences": [{"text": "一场大火毁了那间小木屋。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心毁了我的新手机。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大水毁了河边的几座桥。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把花园里的花毁掉了。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画已经毁了，不能再用。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震毁了很多老房子。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雨毁了我们的帐篷。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗毁了他新买的鞋。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大风毁了农民的麦子。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把我的玩具毁了。", "target_word": "毁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毁了", "label": "体标（了）"}, {"form": "毁掉", "label": "复合"}, {"form": "毁坏", "label": "复合"}], "register": "中性", "sense_fingerprint": "把具体的东西弄坏、弄没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27ad2dfa-3af2-4ed1-82b2-523ba080286e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92687, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：huǐ，指把东西弄坏、弄没有。"}, {"text": "会", "is_correct": false, "explanation": "会（huì）与毁只有声调不同（第四声与第三声），意思是会合或会议。"}, {"text": "回", "is_correct": false, "explanation": "回（huí）与毁只有声调不同（第二声与第三声），意思是回来或回去。"}, {"text": "火", "is_correct": false, "explanation": "火（huǒ）与毁只有韵母不同（o 与 ei），声调相同，意思是火。"}, {"text": "灰", "is_correct": false, "explanation": "灰（huī）与毁只有声调不同（第一声与第三声），意思是灰尘或灰色。"}], "explanations": {"毁": "正确：huǐ，指把东西弄坏、弄没有。", "会": "会（huì）与毁只有声调不同（第四声与第三声），意思是会合或会议。", "回": "回（huí）与毁只有声调不同（第二声与第三声），意思是回来或回去。", "火": "火（huǒ）与毁只有韵母不同（o 与 ei），声调相同，意思是火。", "灰": "灰（huī）与毁只有声调不同（第一声与第三声），意思是灰尘或灰色。"}, "sentence_index": null, "correct_answer": "毁"}, "level_3": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：“大火毁了那间小木屋”指把房屋烧坏、弄没有，与句意相符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”是发出歌声，大火不能“唱”小木屋，与句意不符。"}, {"text": "搬", "is_correct": false, "explanation": "语义：“搬”是移动东西，与“大火”后的破坏义不符，句意不通。"}, {"text": "砸", "is_correct": false, "explanation": "搭配：“砸”多指用重物撞击，一般不与“大火”搭配。"}], "explanations": {"毁": "正确：“大火毁了那间小木屋”指把房屋烧坏、弄没有，与句意相符。", "唱": "语义：“唱”是发出歌声，大火不能“唱”小木屋，与句意不符。", "搬": "语义：“搬”是移动东西，与“大火”后的破坏义不符，句意不通。", "砸": "搭配：“砸”多指用重物撞击，一般不与“大火”搭配。"}, "sentence_index": 0, "correct_answer": "毁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把衣服毁干净了。", "explanation": "这里应该用〈洗〉。“毁”是弄坏、弄没有，不能表示洗涤，洗衣服要说“洗干净”。"}, {"text": "他把桌子毁好了。", "explanation": "这里应该用〈修〉。“毁”是弄坏、弄没有，不能表示修理，修好的东西要说“修好”。"}, {"text": "工人毁好了这座桥。", "explanation": "这里应该用〈建〉。“毁”是弄坏、弄没有，不能表示建造，建桥要说“建好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92687, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：huǐ，指把东西弄坏、弄没有。"}, {"text": "水", "is_correct": false, "explanation": "水（shuǐ）与毁只有声母不同（sh 与 h），声调相同，意思是水。"}, {"text": "鬼", "is_correct": false, "explanation": "鬼（guǐ）与毁只有声母不同（g 与 h），声调相同，意思是鬼。"}, {"text": "辉", "is_correct": false, "explanation": "辉（huī）与毁只有声调不同（第一声与第三声），意思是光辉。"}, {"text": "惠", "is_correct": false, "explanation": "惠（huì）与毁只有声调不同（第四声与第三声），意思是恩惠。"}], "explanations": {"毁": "正确：huǐ，指把东西弄坏、弄没有。", "水": "水（shuǐ）与毁只有声母不同（sh 与 h），声调相同，意思是水。", "鬼": "鬼（guǐ）与毁只有声母不同（g 与 h），声调相同，意思是鬼。", "辉": "辉（huī）与毁只有声调不同（第一声与第三声），意思是光辉。", "惠": "惠（huì）与毁只有声调不同（第四声与第三声），意思是恩惠。"}, "sentence_index": null, "correct_answer": "毁"}, "level_3": {"options": [{"text": "毁", "is_correct": true, "explanation": "正确：“这场大雨毁了我们的帐篷”指大雨把帐篷弄坏，与句意相符。"}, {"text": "叠", "is_correct": false, "explanation": "语义：“叠”指把东西折起来，大雨不能“叠”帐篷，与句意不符。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布等摩擦去掉污物，与“大雨”的破坏义不符，句意不通。"}, {"text": "缝", "is_correct": false, "explanation": "搭配：“缝”指用针线连接，一般不与“大雨”搭配。"}], "explanations": {"毁": "正确：“这场大雨毁了我们的帐篷”指大雨把帐篷弄坏，与句意相符。", "叠": "语义：“叠”指把东西折起来，大雨不能“叠”帐篷，与句意不符。", "擦": "语义：“擦”指用布等摩擦去掉污物，与“大雨”的破坏义不符，句意不通。", "缝": "搭配：“缝”指用针线连接，一般不与“大雨”搭配。"}, "sentence_index": 6, "correct_answer": "毁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把书毁走了。", "explanation": "这里应该用〈搬〉。“毁”是弄坏、弄没有，不能表示搬走，搬东西要说“搬走”。"}, {"text": "她很会毁歌。", "explanation": "这里应该用〈唱〉。“毁”是弄坏、弄没有，不能表示唱歌，唱歌要说“唱”。"}, {"text": "他在河边毁鱼。", "explanation": "这里应该用〈钓〉。“毁”是弄坏、弄没有，不能表示捕捞，钓鱼要说“钓”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大风把麦子毁了了。", "corrected_sentence": "大风把麦子毁了。", "error_description": "体标错误：“毁了”后多加了一个“了”，应只用一个“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b68a9db-e228-42b3-97dc-437b05aaca7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
