INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92701, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确。“正常”与“疯”相对：疯指脑子不清楚，正常指精神状态合乎常态。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”指头脑好，与“疯”不构成反义关系。"}, {"text": "干净", "is_correct": false, "explanation": "“干净”指不脏，与“疯”不构成反义关系。"}, {"text": "暖和", "is_correct": false, "explanation": "“暖和”指温度适宜，与“疯”不构成反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确。“正常”与“疯”相对：疯指脑子不清楚，正常指精神状态合乎常态。", "聪明": "“聪明”指头脑好，与“疯”不构成反义关系。", "干净": "“干净”指不脏，与“疯”不构成反义关系。", "暖和": "“暖和”指温度适宜，与“疯”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
