INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92701, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "疯是人的脑子不清楚，做事很奇怪。", "primary_collocate": null, "pronunciation": "fēng", "ipa": "fɤŋ˥", "syllable_count": 1, "sentences": [{"text": "他一个人在街上又哭又笑，大家都说他疯了。", "target_word": "疯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你疯了吗？这么冷的天还去河里游泳。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有疯，只是工作太累，睡得太少。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人疯了，见人就说自己是皇帝。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别理他，他疯了，说的话都没有道理。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要是不疯，怎么会把新车送给陌生人？", "target_word": "疯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人好像疯了，整天对着墙壁说话。", "target_word": "疯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大声喊叫，还把盘子摔在地上，真像疯了一样。", "target_word": "疯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都以为他疯了，其实他只是在演戏。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说要走路去北京，我觉得他疯了。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "疯了", "label": "体标"}, {"form": "瘋", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疯|形容词|脑子不清楚，言行奇怪", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a27985d7-ed1e-45a0-89a0-5af58ad339f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92701, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确答案。疯读作 fēng（第一声），指人脑子不清楚、做事奇怪。"}, {"text": "方", "is_correct": false, "explanation": "韵母不同：方读 fāng（ang），疯读 fēng（eng）。方意思是方向。"}, {"text": "哼", "is_correct": false, "explanation": "声母不同：哼读 hēng（h），疯读 fēng（f）。哼意思是哼唱。"}, {"text": "缝", "is_correct": false, "explanation": "声调不同：缝读 fèng（第四声），疯读 fēng（第一声）。缝意思是缝补。"}, {"text": "逢", "is_correct": false, "explanation": "声调不同：逢读 féng（第二声），疯读 fēng（第一声）。逢意思是遇到。"}], "explanations": {"疯": "正确答案。疯读作 fēng（第一声），指人脑子不清楚、做事奇怪。", "方": "韵母不同：方读 fāng（ang），疯读 fēng（eng）。方意思是方向。", "哼": "声母不同：哼读 hēng（h），疯读 fēng（f）。哼意思是哼唱。", "缝": "声调不同：缝读 fèng（第四声），疯读 fēng（第一声）。缝意思是缝补。", "逢": "声调不同：逢读 féng（第二声），疯读 fēng（第一声）。逢意思是遇到。"}, "sentence_index": null, "correct_answer": "疯"}, "level_3": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确。“疯了”指精神失常，与“又哭又笑”的表现相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”说头脑好，与在街上又哭又笑的行为相矛盾。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”说身材变化，与又哭又笑的行为无关。"}, {"text": "勤快", "is_correct": false, "explanation": "语义：“勤快”说爱干活，与在街上又哭又笑的表现不符。"}], "explanations": {"疯": "正确。“疯了”指精神失常，与“又哭又笑”的表现相符。", "聪明": "语义：“聪明”说头脑好，与在街上又哭又笑的行为相矛盾。", "胖": "体貌：“胖”说身材变化，与又哭又笑的行为无关。", "勤快": "语义：“勤快”说爱干活，与在街上又哭又笑的表现不符。"}, "sentence_index": 0, "correct_answer": "疯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "窗外疯风大作，树枝被吹得乱响。", "explanation": "这里应该用〈狂〉。狂可以形容风、雨等猛烈，疯表示人精神失常或行为失控，不能用来修饰风。"}, {"text": "他的脚疯了，走路都很困难。", "explanation": "这里应该用〈伤〉。疯只用于人的精神失常，不说身体受伤；脚受伤要说“伤”。"}, {"text": "这道菜有一股疯味，我吃不下去。", "explanation": "这里应该用〈怪〉。怪形容奇怪、不正常的气味，疯只形容人的精神或行为，不能用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92701, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确答案。疯读作 fēng（第一声），指人脑子不清楚、做事奇怪。"}, {"text": "讽", "is_correct": false, "explanation": "声调不同：讽读 fěng（第三声），疯读 fēng（第一声）。讽意思是讽刺。"}, {"text": "奉", "is_correct": false, "explanation": "声调不同：奉读 fèng（第四声），疯读 fēng（第一声）。奉意思是奉献。"}, {"text": "蒙", "is_correct": false, "explanation": "声母不同：蒙读 mēng（m），疯读 fēng（f）。蒙意思是蒙住。"}, {"text": "分", "is_correct": false, "explanation": "韵母不同：分读 fēn（en），疯读 fēng（eng）。分意思是分开。"}], "explanations": {"疯": "正确答案。疯读作 fēng（第一声），指人脑子不清楚、做事奇怪。", "讽": "声调不同：讽读 fěng（第三声），疯读 fēng（第一声）。讽意思是讽刺。", "奉": "声调不同：奉读 fèng（第四声），疯读 fēng（第一声）。奉意思是奉献。", "蒙": "声母不同：蒙读 mēng（m），疯读 fēng（f）。蒙意思是蒙住。", "分": "韵母不同：分读 fēn（en），疯读 fēng（eng）。分意思是分开。"}, "sentence_index": null, "correct_answer": "疯"}, "level_3": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确。“好像疯了”说老人的精神状态，与整天对着墙壁说话相符。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄小，与“老人”矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：“漂亮”说外貌好看，与整天对着墙壁说话的状态不符。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”说有钱，与整天对着墙壁说话的状态无关，句意不通。"}], "explanations": {"疯": "正确。“好像疯了”说老人的精神状态，与整天对着墙壁说话相符。", "年轻": "语义：“年轻”说年龄小，与“老人”矛盾。", "漂亮": "语义：“漂亮”说外貌好看，与整天对着墙壁说话的状态不符。", "富有": "语义：“富有”说有钱，与整天对着墙壁说话的状态无关，句意不通。"}, "sentence_index": 6, "correct_answer": "疯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里的东西很疯，我找了半天也没找到钥匙。", "explanation": "这里应该用〈乱〉。乱形容东西摆放杂乱，疯只形容人的精神或行为，不能用来形容东西。"}, {"text": "他的胃很疯，不能吃辣的。", "explanation": "这里应该用〈疼〉。疼形容身体的痛感，疯不指身体不适，不能用在胃上。"}, {"text": "雨声很疯，吵得我睡不着觉。", "explanation": "这里应该用〈响〉。响形容声音大，疯只形容人的精神或行为，不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92701, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近整天躲在屋里不见人，大家都担心他疯了了。", "corrected_sentence": "他最近整天躲在屋里不见人，大家都担心他疯了。", "error_description": "错误：句末的“了”多写了一个，写成“疯了了”。正确：“疯了”。原因：表示变化的“了”只用一个，重复使用不符合汉语语法，母语者会立即察觉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92701, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说话颠三倒四，大家都说他了疯。", "corrected_sentence": "他说话颠三倒四，大家都说他疯了。", "error_description": "错误：“了”放在了“疯”前面，写成“了疯”。正确：“疯了”。原因：“了”是表示变化的助词，要放在“疯”之后，构成“疯了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确。“正常”与“疯”相对，指精神正常、行为合乎常态。"}, {"text": "深", "is_correct": false, "explanation": "“深”指从上到下或从外到里的距离大，与“疯”不构成反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "“圆”指形状像圆圈，与“疯”不构成反义关系。"}, {"text": "软", "is_correct": false, "explanation": "“软”指不硬，与“疯”不构成反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确。“正常”与“疯”相对，指精神正常、行为合乎常态。", "深": "“深”指从上到下或从外到里的距离大，与“疯”不构成反义关系。", "圆": "“圆”指形状像圆圈，与“疯”不构成反义关系。", "软": "“软”指不硬，与“疯”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "正常", "is_correct": true, "explanation": "正确。“正常”与“疯”相对，指精神正常、行为合乎常态。"}, {"text": "亮", "is_correct": false, "explanation": "“亮”指有光、明亮，与“疯”不构成反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”指上下或前后距离大，与“疯”不构成反义关系。"}, {"text": "贵", "is_correct": false, "explanation": "“贵”指价格高，与“疯”不构成反义关系。"}], "correct_answer": "正常", "explanations": {"正常": "正确。“正常”与“疯”相对，指精神正常、行为合乎常态。", "亮": "“亮”指有光、明亮，与“疯”不构成反义关系。", "厚": "“厚”指上下或前后距离大，与“疯”不构成反义关系。", "贵": "“贵”指价格高，与“疯”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "精神失常；也指行为失去常态。", "primary_collocate": null, "pronunciation": "fēng", "ipa": "fɤŋ˥", "syllable_count": 1, "sentences": [{"text": "听说他受了很大的刺激，后来就疯了。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的母亲疯了很多年，一直住在医院里。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在雪地里玩疯了，天黑还不想回家。", "target_word": "疯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他考了第一名，高兴得快要疯了。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这几天他白天不吃饭，晚上在院子里大喊大叫，邻居都说他快疯了。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球迷们看到进球，一个个都疯了。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在国外受了很多苦，回来时人已经疯了。", "target_word": "疯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他不是真的疯了，只是太伤心。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子玩疯了，作业一个字也没写。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她丈夫去世后，她难过得几乎疯了。", "target_word": "疯", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "疯了", "label": "体标"}, {"form": "瘋", "label": "繁体"}], "register": "口语", "sense_fingerprint": "疯|形容词|精神失常；行为失控", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a27985d7-ed1e-45a0-89a0-5af58ad339f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确答案。疯读作 fēng（第一声），指精神失常或行为失去常态。"}, {"text": "方", "is_correct": false, "explanation": "韵母不同：方读 fāng（ang），疯读 fēng（eng）。方意思是方向。"}, {"text": "哼", "is_correct": false, "explanation": "声母不同：哼读 hēng（h），疯读 fēng（f）。哼意思是哼唱。"}, {"text": "逢", "is_correct": false, "explanation": "声调不同：逢读 féng（第二声），疯读 fēng（第一声）。逢意思是遇到。"}, {"text": "分", "is_correct": false, "explanation": "韵母不同：分读 fēn（en），疯读 fēng（eng）。分意思是分开。"}], "explanations": {"疯": "正确答案。疯读作 fēng（第一声），指精神失常或行为失去常态。", "方": "韵母不同：方读 fāng（ang），疯读 fēng（eng）。方意思是方向。", "哼": "声母不同：哼读 hēng（h），疯读 fēng（f）。哼意思是哼唱。", "逢": "声调不同：逢读 féng（第二声），疯读 fēng（第一声）。逢意思是遇到。", "分": "韵母不同：分读 fēn（en），疯读 fēng（eng）。分意思是分开。"}, "sentence_index": null, "correct_answer": "疯"}, "level_3": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确。受了很大刺激后“就疯了”，表示精神失常。"}, {"text": "富", "is_correct": false, "explanation": "语义：“富”说有钱，受刺激后变富没有因果关系，句意不通。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”说身材，受刺激不会使人长高。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄小，与“后来就……了”所说的变化不符。"}], "explanations": {"疯": "正确。受了很大刺激后“就疯了”，表示精神失常。", "富": "语义：“富”说有钱，受刺激后变富没有因果关系，句意不通。", "高": "体貌：“高”说身材，受刺激不会使人长高。", "年轻": "语义：“年轻”说年龄小，与“后来就……了”所说的变化不符。"}, "sentence_index": 0, "correct_answer": "疯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上的东西很疯，堆得乱七八糟。", "explanation": "这里应该用〈杂乱〉。杂乱形容东西摆放没有次序，疯只形容人的精神或行为，不能用来形容东西。"}, {"text": "窗外疯风大作，树枝被吹得乱响。", "explanation": "这里应该用〈狂〉。狂可以形容风、雨等猛烈，疯表示人精神失常或行为失控，不能用来修饰风。"}, {"text": "这碗汤有一股疯味，我没喝完。", "explanation": "这里应该用〈怪〉。怪形容奇怪、不正常的气味，疯只形容人的精神或行为，不能用来形容气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确答案。疯读作 fēng（第一声），指精神失常或行为失去常态。"}, {"text": "讽", "is_correct": false, "explanation": "声调不同：讽读 fěng（第三声），疯读 fēng（第一声）。讽意思是讽刺。"}, {"text": "奉", "is_correct": false, "explanation": "声调不同：奉读 fèng（第四声），疯读 fēng（第一声）。奉意思是奉献。"}, {"text": "蒙", "is_correct": false, "explanation": "声母不同：蒙读 mēng（m），疯读 fēng（f）。蒙意思是蒙住。"}, {"text": "崩", "is_correct": false, "explanation": "声母不同：崩读 bēng（b），疯读 fēng（f）。崩意思是崩溃。"}], "explanations": {"疯": "正确答案。疯读作 fēng（第一声），指精神失常或行为失去常态。", "讽": "声调不同：讽读 fěng（第三声），疯读 fēng（第一声）。讽意思是讽刺。", "奉": "声调不同：奉读 fèng（第四声），疯读 fēng（第一声）。奉意思是奉献。", "蒙": "声母不同：蒙读 mēng（m），疯读 fēng（f）。蒙意思是蒙住。", "崩": "声母不同：崩读 bēng（b），疯读 fēng（f）。崩意思是崩溃。"}, "sentence_index": null, "correct_answer": "疯"}, "level_3": {"options": [{"text": "疯", "is_correct": true, "explanation": "正确。“回来时人已经疯了”与受了很多苦之后的精神状态相符。"}, {"text": "年轻", "is_correct": false, "explanation": "语义：“年轻”说年龄小，与受苦后回来的状态矛盾，句意不通。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”多形容物品或队伍，不用来说人的状态。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”说身材丰满，与受了很多苦的状态不符。"}], "explanations": {"疯": "正确。“回来时人已经疯了”与受了很多苦之后的精神状态相符。", "年轻": "语义：“年轻”说年龄小，与受苦后回来的状态矛盾，句意不通。", "整齐": "搭配：“整齐”多形容物品或队伍，不用来说人的状态。", "胖": "体貌：“胖”说身材丰满，与受了很多苦的状态不符。"}, "sentence_index": 6, "correct_answer": "疯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中手疯了，不能写字。", "explanation": "这里应该用〈伤〉。疯只用于人的精神失常，不说身体受伤；手受伤要说“伤”。"}, {"text": "我的头很疯，想早点休息。", "explanation": "这里应该用〈疼〉。疼形容身体的痛感，疯不能用来形容头痛。"}, {"text": "这间屋子的灯光很疯，看书很舒服。", "explanation": "这里应该用〈亮〉。亮形容光线强，疯只形容人的精神或行为，不能用来形容灯光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近压力太大，快要疯着。", "corrected_sentence": "他最近压力太大，快要疯了。", "error_description": "错误：“快要……”后面用了“着”，写成“疯着”。正确：“疯了”。原因：“快要”表示即将发生的变化，要用“了”，不能用表示持续状态的“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92702, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子走丢以后，她急得快疯了了。", "corrected_sentence": "孩子走丢以后，她急得快疯了。", "error_description": "错误：句末的“了”多写了一个，写成“疯了了”。正确：“疯了”。原因：表示变化的“了”只用一个，重复使用不符合汉语语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
