INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "午餐是中午吃的饭。", "primary_collocate": null, "pronunciation": "wǔ cān", "ipa": "u˨˩ tsʰan˥", "syllable_count": 2, "sentences": [{"text": "我的午餐是一碗面条。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的午餐很好吃。", "target_word": "午餐", "complexity_tier": "T3", "furigana": "jīntiān de wǔcān hěn hǎochī", "sentence_source": "generated"}, {"text": "他每天十二点吃午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在公司门口吃了午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午餐以后，大家都想休息一下。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我准备了午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的午餐有米饭和青菜。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "午餐你想吃什么？", "target_word": "午餐", "complexity_tier": "T3", "furigana": "wǔcān nǐ xiǎng chī shénme?", "sentence_source": "generated"}, {"text": "她忙得没时间吃午餐。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我带着午餐去上班。", "target_word": "午餐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顿", "label": "量词"}, {"form": "工作午餐", "label": "复合"}, {"form": "午餐时间", "label": "复合"}], "register": "中性", "sense_fingerprint": "中午吃的饭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "午餐", "is_correct": true, "explanation": "正确：“午餐”指中午吃的饭，与“一碗面条”相符，可以作主语。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是用来喝的，面条不是饮料，不能说“我的饮料是一碗面条”。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是食物，与“一碗面条”不相符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“一碗面条”是可以盛放的食物，厨房是房间，二者不能作“是”的判断。"}], "explanations": {"午餐": "正确：“午餐”指中午吃的饭，与“一碗面条”相符，可以作主语。", "饮料": "语义：饮料是用来喝的，面条不是饮料，不能说“我的饮料是一碗面条”。", "书包": "语义：书包是装东西的袋子，不是食物，与“一碗面条”不相符。", "厨房": "搭配：“一碗面条”是可以盛放的食物，厨房是房间，二者不能作“是”的判断。"}, "sentence_index": 0, "correct_answer": "午餐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天早上吃午餐，然后去上班。", "explanation": "这里应该用〈早餐〉。午餐指中午吃的饭，早上吃的饭要说早餐。"}, {"text": "妈妈晚上做了一顿午餐。", "explanation": "这里应该用〈晚餐〉。午餐指中午吃的饭，晚上吃的饭要说晚餐。"}, {"text": "他每天上午十点吃午餐，然后去开会。", "explanation": "这里应该用〈早点〉。午餐指中午吃的饭，上午十点吃的东西要说早点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午餐", "is_correct": true, "explanation": "正确：“午餐”指中午吃的饭，学校的午饭有米饭和青菜，与句意相符。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是借书看书的地方，不会提供米饭和青菜，与句意不符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里写字用的板子，不能“有米饭和青菜”。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“有米饭和青菜”要求主语能供应食物，操场与这种搭配不相符。"}], "explanations": {"午餐": "正确：“午餐”指中午吃的饭，学校的午饭有米饭和青菜，与句意相符。", "图书馆": "语义：图书馆是借书看书的地方，不会提供米饭和青菜，与句意不符。", "黑板": "语义：黑板是教室里写字用的板子，不能“有米饭和青菜”。", "操场": "搭配：“有米饭和青菜”要求主语能供应食物，操场与这种搭配不相符。"}, "sentence_index": 6, "correct_answer": "午餐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈给我装了一根午餐，我在路上吃。", "explanation": "这里应该用〈顿〉。午餐作为一餐饭用「顿」计量；「根」用于细长的东西，不能用于一餐饭。"}, {"text": "我买了一块午餐，在公园吃。", "explanation": "这里应该用〈顿〉。“块”用于块状的东西，一餐饭要用“顿”。"}, {"text": "他每天带一杯午餐去学校。", "explanation": "这里应该用〈顿〉。“杯”用于盛饮料的容器，一餐饭要用“顿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校的午餐们很好吃，同学们都很喜欢。", "corrected_sentence": "学校的午餐很好吃，同学们都很喜欢。", "error_description": "错误形式：“学校的午餐们”。正确形式：“学校的午餐”。“们”用于指人的复数，“午餐”是物，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我今天带了一只午餐去公司。", "corrected_sentence": "我今天带了一份午餐去公司。", "error_description": "错误形式：“一只午餐”。正确形式：“一份午餐”。“只”用于动物或单个的物件，一份饭食要用“份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
