INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可执行是说一件事能真的做出来，照着做就行。", "primary_collocate": null, "pronunciation": "kě zhí xíng", "ipa": "kʰɤ˨˩ ʈʂɨ˧˥ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这个办法很简单，大家都觉得可执行。", "target_word": "可执行", "complexity_tier": "T3", "furigana": "zhè gè bàn fǎ hěn jiǎn dān, dà jiā dōu jué de kě zhí xíng.", "sentence_source": "generated"}, {"text": "你的计划太大了，不可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我们一个可执行的学习计划。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个目标不太可执行，我们改一改吧。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的建议很具体，也可执行，大家都同意。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一个可执行的方案。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的要求可执行吗？", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好计划一定要可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个想法很好，但是不可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出的办法是可执行的，我们马上试了。", "target_word": "可执行", "complexity_tier": "T3", "furigana": "tā tí chū de bàn fǎ shì kě zhí xíng de, wǒ men mǎ shàng shì le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "可執行", "label": "繁体"}], "register": "中性", "sense_fingerprint": "办法、计划、要求等具体清楚，能真正照着做出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可执行", "is_correct": true, "explanation": "“可执行”指办法能真正照着做，与“很简单”的语境相符，填入后句意通顺。"}, {"text": "复杂", "is_correct": false, "explanation": "语义：“复杂”与前句“很简单”相反，前后矛盾，句子不通。"}, {"text": "不可能", "is_correct": false, "explanation": "语义：“不可能”与前句“很简单”相矛盾，句意不通。"}, {"text": "遥远", "is_correct": false, "explanation": "搭配：“遥远”多用于距离或时间，不用来形容办法。"}], "explanations": {"可执行": "“可执行”指办法能真正照着做，与“很简单”的语境相符，填入后句意通顺。", "复杂": "语义：“复杂”与前句“很简单”相反，前后矛盾，句子不通。", "不可能": "语义：“不可能”与前句“很简单”相矛盾，句意不通。", "遥远": "搭配：“遥远”多用于距离或时间，不用来形容办法。"}, "sentence_index": 0, "correct_answer": "可执行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人做事很可执行，大家都信任他。", "explanation": "这里应该用〈可靠〉。“可执行”只说办法、计划能否照着做，不用来形容人的品质。"}, {"text": "这种药很可执行，吃了以后很快见效。", "explanation": "这里应该用〈有效〉。“可执行”用于办法、计划，不用来说药物的作用。"}, {"text": "这部电影很可执行，我看了两遍。", "explanation": "这里应该用〈精彩〉。“可执行”说办法、计划能否照着做，不用来评价电影好不好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可执行", "is_correct": true, "explanation": "“可执行”说要求能否照着做，与“吗”问句相符，是句子的谓语。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：“可爱”形容人或动物讨人喜欢，与“要求”不搭，句子不通。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多形容水、眼神等，不用来形容要求。"}, {"text": "温暖", "is_correct": false, "explanation": "搭配：“温暖”多形容温度或感情，不用来形容要求。"}], "explanations": {"可执行": "“可执行”说要求能否照着做，与“吗”问句相符，是句子的谓语。", "可爱": "语义：“可爱”形容人或动物讨人喜欢，与“要求”不搭，句子不通。", "清澈": "搭配：“清澈”多形容水、眼神等，不用来形容要求。", "温暖": "搭配：“温暖”多形容温度或感情，不用来形容要求。"}, "sentence_index": 6, "correct_answer": "可执行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把刀很可执行，厨房里天天用。", "explanation": "这里应该用〈实用〉。“可执行”只用于办法、计划、要求，不用来形容刀具等物品。"}, {"text": "这个消息很可执行，大家都相信了。", "explanation": "这里应该用〈可信〉。“可执行”说办法能否照做，不用来形容消息是否可信。"}, {"text": "这只小狗很可执行，大家都喜欢它。", "explanation": "这里应该用〈可爱〉。“可执行”不用来形容动物的样子或性情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方案设计地可执行，大家都同意了。", "corrected_sentence": "这个方案设计得可执行，大家都同意了。", "error_description": "补语标记应用“得”，不能用“地”。“地”用在动词前作状语，“设计”之后接补语“可执行”要用“得”。错误形式：设计地可执行；正确形式：设计得可执行。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个办法是可执行的的，我们明天就开始。", "corrected_sentence": "这个办法是可执行的，我们明天就开始。", "error_description": "“的”重复使用，“可执行的”只需一个“的”。错误形式：可执行的的；正确形式：可执行的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
