INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92708, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能够被计算机运行或执行的（多指程序、脚本、文件）。", "primary_collocate": null, "pronunciation": "kě zhí xíng", "ipa": "kʰɤ˨˩ ʈʂɨ˧˥ ɕiŋ˧˥", "syllable_count": 3, "sentences": [{"text": "这个文件是可执行的，可以直接打开。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个命令在电脑上不可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写了一个可执行的程序。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序现在还不可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段代码编译以后就可执行。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个脚本可执行吗？", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把代码改成可执行的。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个程序写得很规范，是可执行的。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "程序不可执行，因为里面有错误。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条命令可执行，你试一下。", "target_word": "可执行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可執行", "label": "繁体"}], "register": "书面", "sense_fingerprint": "程序、脚本、文件等能被计算机直接运行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可执行", "is_correct": true, "explanation": "“可执行”指文件能被电脑运行，与“可以直接打开”相符，句意通顺。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指物体能透光，与文件能否运行无关，句子不通。"}, {"text": "柔软", "is_correct": false, "explanation": "搭配：“柔软”多形容质地，不用来形容文件。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”多形容体形、建筑，不用来形容文件。"}], "explanations": {"可执行": "“可执行”指文件能被电脑运行，与“可以直接打开”相符，句意通顺。", "透明": "语义：“透明”指物体能透光，与文件能否运行无关，句子不通。", "柔软": "搭配：“柔软”多形容质地，不用来形容文件。", "高大": "搭配：“高大”多形容体形、建筑，不用来形容文件。"}, "sentence_index": 0, "correct_answer": "可执行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块显卡现在可执行，装上就能玩游戏。", "explanation": "这里应该用〈可用〉。“可执行”只用于程序、命令、文件等能被运行的对象，显卡是硬件，不能被“执行”。"}, {"text": "这份说明很可执行，新手也能看懂。", "explanation": "这里应该用〈易懂〉。说明书是文字，不能被“执行”，“可执行”不用来说文字是否易懂。"}, {"text": "这张照片很可执行，可以直接打印。", "explanation": "这里应该用〈清晰〉。照片不是程序或命令，“可执行”不用来形容图像的清晰程度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可执行", "is_correct": true, "explanation": "“可执行”指代码能被运行，与“改成”搭配，句子通顺。"}, {"text": "纯白", "is_correct": false, "explanation": "语义：“纯白”指颜色，与代码无关，句子不通。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道，不用来形容代码。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指水汽多，与代码无关，句子不通。"}], "explanations": {"可执行": "“可执行”指代码能被运行，与“改成”搭配，句子通顺。", "纯白": "语义：“纯白”指颜色，与代码无关，句子不通。", "辛辣": "搭配：“辛辣”形容味道，不用来形容代码。", "潮湿": "语义：“潮湿”指水汽多，与代码无关，句子不通。"}, "sentence_index": 6, "correct_answer": "可执行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章很可执行，我一个晚上就看完了。", "explanation": "这里应该用〈可读〉。“可执行”只用于能被运行的程序、命令等，不用来形容文章是否好读。"}, {"text": "这只小狗很可执行，大家都喜欢它。", "explanation": "这里应该用〈可爱〉。“可执行”不用来形容动物的样子或性情。"}, {"text": "我的朋友很可执行，有事都找他。", "explanation": "这里应该用〈可靠〉。“可执行”只用于程序、命令等对象，不用来形容人的品质。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个安装包是可执行的的，双击就能装。", "corrected_sentence": "这个安装包是可执行的，双击就能装。", "error_description": "“的”重复使用，“可执行的”只需一个“的”。错误形式：可执行的的；正确形式：可执行的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段程序编地可执行，双击就能运行。", "corrected_sentence": "这段程序编得可执行，双击就能运行。", "error_description": "补语标记应用“得”，不能用“地”。“地”用在动词前作状语，“编”之后接补语“可执行”要用“得”。错误形式：编地可执行；正确形式：编得可执行。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
