INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92719, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "约吗是问别人想不想一起去玩。", "primary_collocate": null, "pronunciation": "yuē ma", "ipa": "yɛ˥ ma", "syllable_count": 2, "sentences": [{"text": "今晚我想去看电影，你约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末天气好，去爬山，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去吃火锅，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天下午打球，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店新开的，一起去尝尝，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天不加班，去公园走走，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请客，晚上唱歌，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后去图书馆，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说海边很漂亮，这个周末去，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好久没见了，喝杯咖啡，约吗？", "target_word": "约吗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "提出一个活动，问对方想不想一起去玩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '230f03da-1729-41ca-a1ac-3cb91ec386f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92719, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "约吗", "is_correct": true, "explanation": "「约吗」是口语，问对方想不想一起去看电影，符合句意。"}, {"text": "写吗", "is_correct": false, "explanation": "语义：「写」指写字或写作，与今晚去看电影的提议无关。"}, {"text": "唱吗", "is_correct": false, "explanation": "搭配：「唱」的对象是歌，不能单独用来提议去看电影。"}, {"text": "考吗", "is_correct": false, "explanation": "语义：「考」指考试，与今晚看电影的安排无关。"}], "explanations": {"约吗": "「约吗」是口语，问对方想不想一起去看电影，符合句意。", "写吗": "语义：「写」指写字或写作，与今晚去看电影的提议无关。", "唱吗": "搭配：「唱」的对象是歌，不能单独用来提议去看电影。", "考吗": "语义：「考」指考试，与今晚看电影的安排无关。"}, "sentence_index": 0, "correct_answer": "约吗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我们去爬山了，约吗？", "explanation": "这里不能用「约吗」：它用于提议还没发生的活动，「昨天」已经完成，应改为「去爬山了吗」之类的问法。"}, {"text": "他的脚受伤了，走路很慢，约吗？", "explanation": "这里不能用「约吗」：句子在说明伤情，并没有提议一起做什么，因此不这样用。"}, {"text": "这个学期的成绩出来了，你约吗？", "explanation": "这里应该用〈知道吗〉。约吗用于询问对方是否愿意一起活动，这里只是告知成绩出来了，并没有邀约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92719, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "约吗", "is_correct": true, "explanation": "「约吗」是口语，提议一起唱歌，符合句意。"}, {"text": "睡吗", "is_correct": false, "explanation": "语义：「睡」指睡觉，与句中晚上唱歌的安排相冲突。"}, {"text": "学吗", "is_correct": false, "explanation": "语义：「学」指学习，与请客后唱歌的提议不相符。"}, {"text": "扫吗", "is_correct": false, "explanation": "搭配：「扫」需要地面、垃圾等对象，不能用来提议唱歌。"}], "explanations": {"约吗": "「约吗」是口语，提议一起唱歌，符合句意。", "睡吗": "语义：「睡」指睡觉，与句中晚上唱歌的安排相冲突。", "学吗": "语义：「学」指学习，与请客后唱歌的提议不相符。", "扫吗": "搭配：「扫」需要地面、垃圾等对象，不能用来提议唱歌。"}, "sentence_index": 6, "correct_answer": "约吗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "好久没见了，他长得很高，约吗？", "explanation": "这里不能用「约吗」：它只用来提议一起做事，这里描述的是外貌，没有提议的意思。"}, {"text": "好久没见了，你瘦了很多，约吗？", "explanation": "这里不能用「约吗」：句子在谈论外貌，没有提议一起做什么。"}, {"text": "好久没见了，窗外的雨下得很大，约吗？", "explanation": "这里不能用「约吗」：句子在描述天气，没有提议一起做什么，因此不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92719, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "周末我们去爬山，你约吗吗？", "corrected_sentence": "周末我们去爬山，你约吗？", "error_description": "错误形式：「你约吗吗？」；正确形式：「你约吗？」。句末疑问语气词「吗」只用一个，多写一个「吗」是多余的错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92719, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末去逛公园，你约吗了？", "corrected_sentence": "周末去逛公园，你约吗？", "error_description": "错误形式：「你约吗了？」；正确形式：「你约吗？」。「吗」是疑问语气词，不能再和表示完成的「了」连用，句中多出的「了」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
