INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92722, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "股东对公司所享有的权利。", "primary_collocate": null, "pronunciation": "gǔ quán", "ipa": "ku˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "股权让股东可以参与公司的决定。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "持有股权的人，可以分到公司的利润。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司要保护小股东的股权。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他通过股权获得了公司的控制权。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "股权不同，股东享有的权利也不同。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法律规定，股东的股权受到保护。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想出售股权，其他股东不同意。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司把一部分股权分给了新股东。", "target_word": "股权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一直持有着公司的股权。", "target_word": "股权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有股权，就不能参加公司的投票。", "target_word": "股权", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "股权转让", "label": "复合"}, {"form": "股权投资", "label": "复合"}, {"form": "股權", "label": "繁体"}], "register": "书面", "sense_fingerprint": "股东对公司享有的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92722, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "股权", "is_correct": true, "explanation": "股权是股东对公司的权利，可以让股东参与决定，句意相符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是劳动报酬，不能让股东参与公司的决定。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是权利，不可能让股东参与公司的决定。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“参与公司的决定”需要权利类的词作主语，“座位”不能这样搭配。"}], "explanations": {"股权": "股权是股东对公司的权利，可以让股东参与决定，句意相符。", "工资": "语义：工资是劳动报酬，不能让股东参与公司的决定。", "天气": "语义：天气不是权利，不可能让股东参与公司的决定。", "座位": "搭配：“参与公司的决定”需要权利类的词作主语，“座位”不能这样搭配。"}, "sentence_index": 0, "correct_answer": "股权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的股权主要是一栋楼。", "explanation": "这里应该用〈资产〉。一栋楼属于资产；股权是股东对公司的权利，不能说“股权是一栋楼”。"}, {"text": "这位股权每天都来公司上班。", "explanation": "这里应该用〈股东〉。股东是人，能来公司上班；股权是权利，不能上班。"}, {"text": "他很爱吃股权。", "explanation": "这里应该用〈水果〉。水果可以吃；股权是股东对公司所享有的权利，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92722, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "股权", "is_correct": true, "explanation": "股权可以出售，所以“想出售股权”成立；其他股东不同意也合乎常理。"}, {"text": "房租", "is_correct": false, "explanation": "搭配：“出售”不能和“房租”搭配，房租是付给房东的钱，不能卖。"}, {"text": "童年", "is_correct": false, "explanation": "搭配：“出售”不能和“童年”搭配，童年是经历，不能拿去卖。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气是性格特点，不是可以出售的东西。"}], "explanations": {"股权": "股权可以出售，所以“想出售股权”成立；其他股东不同意也合乎常理。", "房租": "搭配：“出售”不能和“房租”搭配，房租是付给房东的钱，不能卖。", "童年": "搭配：“出售”不能和“童年”搭配，童年是经历，不能拿去卖。", "脾气": "语义：脾气是性格特点，不是可以出售的东西。"}, "sentence_index": 6, "correct_answer": "股权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "银行每个月给我结算股权。", "explanation": "这里应该用〈利息〉。利息可以按月结算；股权是公司的权利，不能按月结算。"}, {"text": "他拥有这本书的股权。", "explanation": "这里应该用〈版权〉。版权是作品的权利，书的版权不能说成股权；股权指公司份额。"}, {"text": "他拿到了这次比赛的股权。", "explanation": "这里应该用〈冠军〉。冠军是比赛的名次，比赛没有股权；股权是股东对公司所享有的权利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92722, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在持有过公司的股权。", "corrected_sentence": "他正在持有公司的股权。", "error_description": "体标错误：“正在”表示动作进行中，与表示经历的“过”不能同用，应去掉“过”，说“正在持有公司的股权”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92722, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "有一只股权的人都能分到利润。", "corrected_sentence": "有股权的人都能分到利润。", "error_description": "量词错误：“股权”前不能用“只”，“只”多用于动物等个体；应直接说“有股权的人”，不能说“有一只股权的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲剧", "is_correct": true, "explanation": "悲剧：以悲惨结局为主的戏剧或影视作品，与喜剧相对，是反义词。"}, {"text": "花园", "is_correct": false, "explanation": "花园：种植花草的地方，与「喜剧」没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "河流：陆地上流动的水体，与「喜剧」没有反义关系。"}, {"text": "课桌", "is_correct": false, "explanation": "课桌：供学生学习时使用的桌子，与「喜剧」没有反义关系。"}], "correct_answer": "悲剧", "explanations": {"悲剧": "悲剧：以悲惨结局为主的戏剧或影视作品，与喜剧相对，是反义词。", "花园": "花园：种植花草的地方，与「喜剧」没有反义关系。", "河流": "河流：陆地上流动的水体，与「喜剧」没有反义关系。", "课桌": "课桌：供学生学习时使用的桌子，与「喜剧」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲剧", "is_correct": true, "explanation": "悲剧：以悲惨结局为主的戏剧或影视作品，与喜剧相对，是反义词。"}, {"text": "书架", "is_correct": false, "explanation": "书架：摆放书籍的家具，与「喜剧」没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "天空：地面上方的广阔空间，与「喜剧」没有反义关系。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞：遮挡雨水的用品，与「喜剧」没有反义关系。"}], "correct_answer": "悲剧", "explanations": {"悲剧": "悲剧：以悲惨结局为主的戏剧或影视作品，与喜剧相对，是反义词。", "书架": "书架：摆放书籍的家具，与「喜剧」没有反义关系。", "天空": "天空：地面上方的广阔空间，与「喜剧」没有反义关系。", "雨伞": "雨伞：遮挡雨水的用品，与「喜剧」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "喜剧是让人看了会笑的戏或电影。", "primary_collocate": null, "pronunciation": "xǐ jù", "ipa": "ɕi˨˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢看喜剧，因为它很好笑。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨晚我们在家看了一部喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这部喜剧，我笑了很久。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末我想去电影院看喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们爱看喜剧，常常笑个不停。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心情不好的时候，我就看喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部喜剧里有很多好笑的人。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈不爱看悲剧，只爱看喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演过一部很有名的喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天晚上电视里有一部喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "喜剧片", "label": "复合"}, {"form": "喜劇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "让人看了会笑的戏或电影", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜剧", "is_correct": true, "explanation": "喜剧：让人看了会笑的戏或电影，符合「因为它很好笑」的理由。"}, {"text": "药方", "is_correct": false, "explanation": "语义：「药方」是开药的单子，与「很好笑」无关，句意不通。"}, {"text": "地图", "is_correct": false, "explanation": "语义：「地图」用来指路，不能用「好笑」来形容。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：「好笑」形容的是人或作品，不能用来形容账单。"}], "explanations": {"喜剧": "喜剧：让人看了会笑的戏或电影，符合「因为它很好笑」的理由。", "药方": "语义：「药方」是开药的单子，与「很好笑」无关，句意不通。", "地图": "语义：「地图」用来指路，不能用「好笑」来形容。", "账单": "搭配：「好笑」形容的是人或作品，不能用来形容账单。"}, "sentence_index": 0, "correct_answer": "喜剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在博物馆里参观了一部喜剧，展品全是古代的陶器。", "explanation": "这里应该用〈展览〉。喜剧是让人发笑的戏或电影，不是陈列实物的展览；展览用来陈列展品。"}, {"text": "这个周末我想去电影院看喜剧，因为想哭。", "explanation": "这里应该用〈悲剧〉。喜剧让人发笑，与「想哭」的目的矛盾。"}, {"text": "这个周末我想去电影院看喜剧，了解一下我们小区的停车规定。", "explanation": "这里应该用〈教学视频〉。喜剧以幽默引人发笑，不用来讲解规定；教学视频用于讲解知识。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜剧", "is_correct": true, "explanation": "喜剧：让人看了会笑的戏或电影，符合「里面有很多好笑的人」。"}, {"text": "词典", "is_correct": false, "explanation": "语义：「词典」收录词语，里面不会有「好笑的人」这样的人物。"}, {"text": "数据", "is_correct": false, "explanation": "搭配：「数据」是信息，不能用「好笑的人」来描述它的内容。"}, {"text": "药品", "is_correct": false, "explanation": "语义：「药品」是治病用的物品，与「好笑的人」无关。"}], "explanations": {"喜剧": "喜剧：让人看了会笑的戏或电影，符合「里面有很多好笑的人」。", "词典": "语义：「词典」收录词语，里面不会有「好笑的人」这样的人物。", "数据": "搭配：「数据」是信息，不能用「好笑的人」来描述它的内容。", "药品": "语义：「药品」是治病用的物品，与「好笑的人」无关。"}, "sentence_index": 6, "correct_answer": "喜剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天晚上电视里有一部喜剧，正在播报最新的天气。", "explanation": "这里应该用〈新闻〉。喜剧是虚构的戏或电影，不会播报天气。"}, {"text": "今天晚上电视里有一部喜剧，专门介绍汽车的性能。", "explanation": "这里应该用〈宣传片〉。喜剧以幽默引人发笑，不用来介绍产品。"}, {"text": "今天晚上电视里有一部喜剧，吓得我不敢关灯。", "explanation": "这里应该用〈恐怖片〉。喜剧引人发笑，不会让人害怕，与「吓得不敢关灯」矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我上次租了一本喜剧回家看。", "corrected_sentence": "我上次租了一部喜剧回家看。", "error_description": "错误形式：「一本喜剧」，量词「本」用于书籍。正确形式：「一部喜剧」，影视作品用量词「部」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92723, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹和我一起看了一部的喜剧。", "corrected_sentence": "妹妹和我一起看了一部喜剧。", "error_description": "错误形式：「一部的喜剧」，数量短语「一部」后面不能加「的」直接修饰名词。正确形式：「一部喜剧」，数量词直接修饰名词，不加「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
