INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92724, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以讽刺或幽默的手法引人发笑、结局多为圆满的戏剧或影视作品。", "primary_collocate": null, "pronunciation": "xǐ jù", "ipa": "ɕi˨˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这部喜剧让全场观众笑个不停。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢看讽刺社会的喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这出喜剧的结局很圆满。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卓别林拍过很多有名的喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喜剧常用幽默的方法讲故事。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一出喜剧，明年会上演。", "target_word": "喜剧", "complexity_tier": "T3", "furigana": "xǐ jù", "sentence_source": "generated"}, {"text": "剧院下个月要演一部新喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和悲剧不同，喜剧的结局多半是好的。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的同学排演了一出喜剧。", "target_word": "喜剧", "complexity_tier": "T3", "furigana": "xǐ jù", "sentence_source": "generated"}, {"text": "这部喜剧里的笑话很聪明。", "target_word": "喜剧", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "喜剧片", "label": "复合"}, {"form": "喜劇", "label": "繁体"}], "register": "中性", "sense_fingerprint": "以幽默讽刺引人发笑、结局圆满的戏剧或影视作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喜剧", "is_correct": true, "explanation": "喜剧：以幽默引人发笑的戏或影视作品，符合「让全场观众笑个不停」。"}, {"text": "病历", "is_correct": false, "explanation": "语义：「病历」是医疗记录，不能让观众笑个不停。"}, {"text": "教材", "is_correct": false, "explanation": "语义：「教材」是教学用书，不是能让观众发笑的作品。"}, {"text": "说明书", "is_correct": false, "explanation": "搭配：「说明书」是说明用法的文件，不能作为「这部」所指的、让观众笑个不停的作品。"}], "explanations": {"喜剧": "喜剧：以幽默引人发笑的戏或影视作品，符合「让全场观众笑个不停」。", "病历": "语义：「病历」是医疗记录，不能让观众笑个不停。", "教材": "语义：「教材」是教学用书，不是能让观众发笑的作品。", "说明书": "搭配：「说明书」是说明用法的文件，不能作为「这部」所指的、让观众笑个不停的作品。"}, "sentence_index": 0, "correct_answer": "喜剧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告是一出喜剧，作者用严谨的数据证明了结论。", "explanation": "这里应该用〈学术论文〉。喜剧指戏剧或影视作品，不能用来指严谨论证的文章；学术论文用于论证结论。"}, {"text": "这部喜剧被我当作字典来查单词，每次都能找到答案。", "explanation": "这里应该用〈工具书〉。喜剧是让人发笑的戏或电影，不能当作查词的工具；工具书用于查阅资料。"}, {"text": "他是一位出色的喜剧，每次表演都让人笑个不停。", "explanation": "这里应该用〈喜剧演员〉。「喜剧」指作品或艺术形式，不能直接用来称呼表演者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜剧", "is_correct": true, "explanation": "喜剧：可以上演的戏剧作品，符合「剧院下个月要演」的语境。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：「食谱」是做菜的说明，不能在剧院上演。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：「演」不能用于字典，字典不是可以上演的作品。"}, {"text": "数据", "is_correct": false, "explanation": "语义：「数据」是数字信息，不能在剧院上演。"}], "explanations": {"喜剧": "喜剧：可以上演的戏剧作品，符合「剧院下个月要演」的语境。", "食谱": "语义：「食谱」是做菜的说明，不能在剧院上演。", "字典": "搭配：「演」不能用于字典，字典不是可以上演的作品。", "数据": "语义：「数据」是数字信息，不能在剧院上演。"}, "sentence_index": 6, "correct_answer": "喜剧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们中午吃的这份喜剧是用面粉做的，味道很好。", "explanation": "这里应该用〈蛋糕〉。喜剧是戏剧或影视作品，不是可以吃的食物；蛋糕是用面粉做成的甜点。"}, {"text": "这部喜剧是一台洗衣机，每天都在帮我洗衣服。", "explanation": "这里应该用〈家电〉。喜剧指戏剧或影视作品，不是家用电器；洗衣机才是用来洗衣服的家电。"}, {"text": "这部喜剧正在电视上直播股市的涨跌行情，观众都在看。", "explanation": "这里应该用〈财经节目〉。喜剧是让人发笑的戏或电影，不用来直播行情；财经节目用于报道市场信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
