INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92739, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "姿态是人或动物站、坐、走、跑、睡等动作时，身体呈现的样子。", "primary_collocate": null, "pronunciation": "zī tài", "ipa": "tsɹ̩˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "她跳舞的姿态很优美。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他坐着的姿态很放松。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只鸟站着的姿态很特别。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们正确的跑步姿态。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员起跑的姿态很标准。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡觉的姿态很有意思。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "模特走路的姿态很好看。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她以优美的姿态走上了舞台。", "target_word": "姿态", "complexity_tier": "T3", "furigana": "tā yǐ yōu měi de zī tài zǒu shàng le wǔ tái", "sentence_source": "generated"}, {"text": "你的游泳姿态不对，会很累的。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫伸懒腰的姿态很可爱。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姿態", "label": "繁体"}, {"form": "姿态万千", "label": "复合"}], "register": "中性", "sense_fingerprint": "人或动物站、坐、走、动时身体呈现的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92739, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确答案。姿态（zī tài）指人站着、坐着或走路时身体的样子。"}, {"text": "事态", "is_correct": false, "explanation": "shì（第四声）与 zī（第一声）声母不同（sh 与 z），意思是事情发展的状况。"}, {"text": "失态", "is_correct": false, "explanation": "shī（第一声）与 zī 声母不同（sh 与 z），意思是言行失去常态、失礼。"}, {"text": "时态", "is_correct": false, "explanation": "shí（第二声）与 zī 声母不同（sh 与 z），声调也不同，意思是动词表示的时间形式。"}], "explanations": {"姿态": "正确答案。姿态（zī tài）指人站着、坐着或走路时身体的样子。", "事态": "shì（第四声）与 zī（第一声）声母不同（sh 与 z），意思是事情发展的状况。", "失态": "shī（第一声）与 zī 声母不同（sh 与 z），意思是言行失去常态、失礼。", "时态": "shí（第二声）与 zī 声母不同（sh 与 z），声调也不同，意思是动词表示的时间形式。"}, "sentence_index": null, "correct_answer": "姿态"}, "level_3": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确：“姿态”指跳舞时身体的样子，可以说“优美”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指买卖的钱数，跳舞没有价格，也不能说“优美”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，与跳舞的样子无关，不能说“优美”。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人活了多久，与舞蹈的样子无关。"}], "explanations": {"姿态": "正确：“姿态”指跳舞时身体的样子，可以说“优美”。", "价格": "语义：“价格”指买卖的钱数，跳舞没有价格，也不能说“优美”。", "体温": "语义：“体温”指身体的温度，与跳舞的样子无关，不能说“优美”。", "年龄": "语义：“年龄”指人活了多久，与舞蹈的样子无关。"}, "sentence_index": 0, "correct_answer": "姿态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的姿态一直很好，已经用了十年。", "explanation": "这里应该用〈状态〉。姿态指人或动物身体的样子，机器运行的情况要用状态。"}, {"text": "今天的姿态很好，适合去郊游。", "explanation": "这里应该用〈天气〉。姿态指人或动物身体的样子，今天的晴雨冷暖要说天气。"}, {"text": "这碗面的姿态很香，我一口气吃光了。", "explanation": "这里应该用〈味道〉。姿态指身体的样子，食物的香味要说味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92739, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确答案。姿态（zī tài）指人站着、坐着或走路时身体的样子。"}, {"text": "气态", "is_correct": false, "explanation": "qì（第四声）与 zī 声母不同（q 与 z），意思是物质呈气体的样子或状态。"}, {"text": "基态", "is_correct": false, "explanation": "jī（第一声）与 zī 声母不同（j 与 z），意思是物理学中能量最低的状态。"}, {"text": "喜态", "is_correct": false, "explanation": "xǐ（第三声）与 zī 声母不同（x 与 z），声调也不同，意思是高兴的神情。"}, {"text": "始态", "is_correct": false, "explanation": "shǐ（第三声）与 zī 声母不同（sh 与 z），声调也不同，意思是开始时的状态。"}], "explanations": {"姿态": "正确答案。姿态（zī tài）指人站着、坐着或走路时身体的样子。", "气态": "qì（第四声）与 zī 声母不同（q 与 z），意思是物质呈气体的样子或状态。", "基态": "jī（第一声）与 zī 声母不同（j 与 z），意思是物理学中能量最低的状态。", "喜态": "xǐ（第三声）与 zī 声母不同（x 与 z），声调也不同，意思是高兴的神情。", "始态": "shǐ（第三声）与 zī 声母不同（sh 与 z），声调也不同，意思是开始时的状态。"}, "sentence_index": null, "correct_answer": "姿态"}, "level_3": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确：“姿态”指走路时身体的样子，可以说“好看”。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”指上学交的钱，与走路的样子无关。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指身体的温度，不能用来形容走路的样子好看。"}, {"text": "病情", "is_correct": false, "explanation": "搭配：“病情”指病的状况，不能用“好看”来形容。"}], "explanations": {"姿态": "正确：“姿态”指走路时身体的样子，可以说“好看”。", "学费": "语义：“学费”指上学交的钱，与走路的样子无关。", "体温": "语义：“体温”指身体的温度，不能用来形容走路的样子好看。", "病情": "搭配：“病情”指病的状况，不能用“好看”来形容。"}, "sentence_index": 6, "correct_answer": "姿态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电视的姿态很清楚。", "explanation": "这里应该用〈画面〉。姿态指人或动物身体的样子，电视图像的清晰程度要用画面。"}, {"text": "这次考试的姿态很好。", "explanation": "这里应该用〈成绩〉。姿态指身体的样子，考试的结果要用成绩。"}, {"text": "这个项目的姿态很快。", "explanation": "这里应该用〈进度〉。姿态指身体的样子，项目推进的快慢要用进度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SE