INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92739, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站着的一只姿态很自然。", "corrected_sentence": "他站着的姿态很自然。", "error_description": "“姿态”前面不能用量词“只”，“只”多用于动物或单个物品。应去掉“一只”，改为：他站着的姿态很自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92739, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位舞者转身的优美地姿态让人感动。", "corrected_sentence": "这位舞者转身的优美姿态让人感动。", "error_description": "“地”用于修饰动词等，不能用来修饰名词“姿态”。应去掉“地”，改为：这位舞者转身的优美姿态让人感动。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
