INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92740, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人或团体对事情所表现出来的态度或立场。", "primary_collocate": null, "pronunciation": "zī tài", "ipa": "tsɹ̩˥ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他对这件事的姿态很友好。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司摆出了合作的姿态。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方都表现出了开放的姿态。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用低调的姿态面对批评。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以认真的姿态对待工作。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望你用积极的姿态学习。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家一直保持着中立的姿态。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对问题，他的姿态很坚决。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对于这个问题，我们的姿态很清楚。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他放低姿态，向朋友道歉了。", "target_word": "姿态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "姿態", "label": "繁体"}], "register": "书面", "sense_fingerprint": "人或团体对事情表现出来的态度、立场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92740, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确答案。姿态（zī tài）指对事情表现出来的态度或立场。"}, {"text": "事态", "is_correct": false, "explanation": "shì（第四声）与 zī（第一声）声母不同（sh 与 z），意思是事情发展的状况。"}, {"text": "失态", "is_correct": false, "explanation": "shī（第一声）与 zī 声母不同（sh 与 z），意思是言行失去常态、失礼。"}, {"text": "时态", "is_correct": false, "explanation": "shí（第二声）与 zī 声母不同（sh 与 z），声调也不同，意思是动词表示的时间形式。"}], "explanations": {"姿态": "正确答案。姿态（zī tài）指对事情表现出来的态度或立场。", "事态": "shì（第四声）与 zī（第一声）声母不同（sh 与 z），意思是事情发展的状况。", "失态": "shī（第一声）与 zī 声母不同（sh 与 z），意思是言行失去常态、失礼。", "时态": "shí（第二声）与 zī 声母不同（sh 与 z），声调也不同，意思是动词表示的时间形式。"}, "sentence_index": null, "correct_answer": "姿态"}, "level_3": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确：“姿态”指对事情表现出的态度，可以说“友好”。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，与对事情的态度无关。"}, {"text": "分量", "is_correct": false, "explanation": "搭配：“分量”指轻重，不能用“友好”来形容。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指物体的轻重，对事情不能说友好。"}], "explanations": {"姿态": "正确：“姿态”指对事情表现出的态度，可以说“友好”。", "身高": "语义：“身高”指人的高矮，与对事情的态度无关。", "分量": "搭配：“分量”指轻重，不能用“友好”来形容。", "重量": "语义：“重量”指物体的轻重，对事情不能说友好。"}, "sentence_index": 0, "correct_answer": "姿态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的姿态很便宜，只要二十块钱。", "explanation": "这里应该用〈价格〉。姿态指身体的样子或对事情的态度，商品的价钱要说价格。"}, {"text": "这个湖的姿态很深，最深处有十米。", "explanation": "这里应该用〈深度〉。姿态不能表示水的深浅，湖水的深浅要说深度。"}, {"text": "今天的姿态很好，适合去爬山。", "explanation": "这里应该用〈天气〉。姿态不能表示天气的状况，今天的晴雨冷暖要说天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92740, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确答案。姿态（zī tài）指对事情表现出来的态度或立场。"}, {"text": "气态", "is_correct": false, "explanation": "qì（第四声）与 zī 声母不同（q 与 z），意思是物质呈气体的样子或状态。"}, {"text": "基态", "is_correct": false, "explanation": "jī（第一声）与 zī 声母不同（j 与 z），意思是物理学中能量最低的状态。"}, {"text": "喜态", "is_correct": false, "explanation": "xǐ（第三声）与 zī 声母不同（x 与 z），声调也不同，意思是高兴的神情。"}, {"text": "始态", "is_correct": false, "explanation": "shǐ（第三声）与 zī 声母不同（sh 与 z），声调也不同，意思是开始时的状态。"}], "explanations": {"姿态": "正确答案。姿态（zī tài）指对事情表现出来的态度或立场。", "气态": "qì（第四声）与 zī 声母不同（q 与 z），意思是物质呈气体的样子或状态。", "基态": "jī（第一声）与 zī 声母不同（j 与 z），意思是物理学中能量最低的状态。", "喜态": "xǐ（第三声）与 zī 声母不同（x 与 z），声调也不同，意思是高兴的神情。", "始态": "shǐ（第三声）与 zī 声母不同（sh 与 z），声调也不同，意思是开始时的状态。"}, "sentence_index": null, "correct_answer": "姿态"}, "level_3": {"options": [{"text": "姿态", "is_correct": true, "explanation": "正确：“姿态”指对事情表现出的立场，可以说“中立”。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指人的性情，国家不能有脾气，与“中立”不合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指存在了多少年，不能说“中立的年龄”。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“中立”不能修饰“体重”，“保持”的对象应是立场或态度。"}], "explanations": {"姿态": "正确：“姿态”指对事情表现出的立场，可以说“中立”。", "脾气": "语义：“脾气”指人的性情，国家不能有脾气，与“中立”不合。", "年龄": "语义：“年龄”指存在了多少年，不能说“中立的年龄”。", "体重": "搭配：“中立”不能修饰“体重”，“保持”的对象应是立场或态度。"}, "sentence_index": 6, "correct_answer": "姿态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他加快了姿态，赶上了火车。", "explanation": "这里应该用〈速度〉。姿态不能表示行进的快慢，要用速度。"}, {"text": "这种食物的姿态很高。", "explanation": "这里应该用〈热量〉。姿态不能表示食物的能量，要用热量。"}, {"text": "室内的姿态很高。", "explanation": "这里应该用〈温度〉。姿态不能表示冷热的程度，要用温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92740, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对于这次合作，他们表现出了一只积极的姿态。", "corrected_sentence": "对于这次合作，他们表现出了积极的姿态。", "error_description": "“姿态”前面不能用量词“只”，应去掉“一只”，改为：对于这次合作，他们表现出了积极的姿态。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92740, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面对批评，他始终保持着冷静地姿态。", "corrected_sentence": "面对批评，他始终保持着冷静的姿态。", "error_description": "“冷静”修饰名词“姿态”时要用“的”，不能用“地”。应改为：面对批评，他始终保持着冷静的姿态。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
