INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "安慰是别人难过的时候，说好听的话让他好受一点。", "primary_collocate": null, "pronunciation": "ān wèi", "ipa": "an˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "她哭了，我说了几句好听的话安慰她。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人难过的时候，你要多安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他输了比赛，同学们都过来安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不会说话，不知道怎么安慰难过的人。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友安慰了我半天，我心里才好受一点。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈总是用温和的话安慰我。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失败了，你不要笑他，应该安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻声安慰着哭的女儿。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了几句话安慰那个难过的孩子。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想安慰你，可是不知道说什么好。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安慰了", "label": "体标"}, {"form": "安慰着", "label": "体标"}, {"form": "安慰过", "label": "体标"}, {"form": "安慰安慰", "label": "重叠"}], "register": "中性", "sense_fingerprint": "别人难过时说好话让他好受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安慰", "is_correct": true, "explanation": "“安慰”表示用好话让对方好受，与“说了几句好听的话”的语境一致，正确。"}, {"text": "责骂", "is_correct": false, "explanation": "语义：“责骂”带有斥责的意思，与“好听的话”相矛盾。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”带有讥讽，与“好听的话”的语气不相符。"}, {"text": "训斥", "is_correct": false, "explanation": "搭配：“训斥”指严厉说教，一般不说用“好听的话”训斥人。"}], "explanations": {"安慰": "“安慰”表示用好话让对方好受，与“说了几句好听的话”的语境一致，正确。", "责骂": "语义：“责骂”带有斥责的意思，与“好听的话”相矛盾。", "嘲笑": "语义：“嘲笑”带有讥讽，与“好听的话”的语气不相符。", "训斥": "搭配：“训斥”指严厉说教，一般不说用“好听的话”训斥人。"}, "sentence_index": 0, "correct_answer": "安慰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了奖，朋友们都过来安慰他。", "explanation": "这里应该用〈祝贺〉。“安慰”针对难过的人，得奖的人应当被祝贺，不该被安慰。"}, {"text": "我把那只旧杯子安慰了一遍。", "explanation": "对象误用：“安慰”的对象应当是有感情的人，不能用于杯子。"}, {"text": "他用拳头安慰了朋友。", "explanation": "方式误用：“安慰”是用言语或温和的行动让人平静，用拳头打人不是安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安慰", "is_correct": true, "explanation": "“安慰”表示让对方心里好受，前句说“不要笑他”，后句“应该安慰他”与之呼应，符合语境。"}, {"text": "咒骂", "is_correct": false, "explanation": "语义：“咒骂”是恶语相向，与“不要笑他”后的劝导语气不协调。"}, {"text": "威胁", "is_correct": false, "explanation": "语义：“威胁”是用恐吓对待对方，与“应该”后的态度说不通。"}, {"text": "讥讽", "is_correct": false, "explanation": "语义：“讥讽”是拿话挖苦对方，与“不要笑他”的劝诫正相反，说“应该讥讽他”说不通。"}], "explanations": {"安慰": "“安慰”表示让对方心里好受，前句说“不要笑他”，后句“应该安慰他”与之呼应，符合语境。", "咒骂": "语义：“咒骂”是恶语相向，与“不要笑他”后的劝导语气不协调。", "威胁": "语义：“威胁”是用恐吓对待对方，与“应该”后的态度说不通。", "讥讽": "语义：“讥讽”是拿话挖苦对方，与“不要笑他”的劝诫正相反，说“应该讥讽他”说不通。"}, "sentence_index": 6, "correct_answer": "安慰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班长安慰了那个主动帮忙的同学。", "explanation": "这里应该用〈感谢〉。“安慰”是为难过的人宽慰，主动帮忙的同学应当感谢。"}, {"text": "他安慰地骂了我一顿。", "explanation": "语义矛盾：“安慰地”表示温和地宽慰，与“骂了我一顿”的责备正相反。"}, {"text": "我安慰了那块石头，它一直不说话。", "explanation": "对象误用：“安慰”的对象应当是有感情的人，不能用于石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被老板骂了，心里很难受，我很安慰他一下。", "corrected_sentence": "他被老板骂了，心里很难受，我去安慰他一下。", "error_description": "错误形式：“我很安慰他一下”；“很安慰”只能作形容词（如“听了很安慰”），后面不能再带宾语“他”。正确形式：“我去安慰他一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92745, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你先别着急，我来安慰一个下她。", "corrected_sentence": "你先别着急，我来安慰一下她。", "error_description": "错误形式：“安慰一个下”；正确形式：“安慰一下”。“一下”是固定的动量结构，中间不能加“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
