INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92746, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用言语或行动使人心情平静舒适。", "primary_collocate": null, "pronunciation": "ān wèi", "ipa": "an˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "朋友考试没考好，我去安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈抱着哭的小弟弟，轻轻安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿来一杯热茶，想安慰难过的奶奶。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师安慰了那个丢了书包的同学。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道怎么安慰她，只好陪她坐了一会儿。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别担心，我来安慰他，你先回家吧。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子摔倒后哭了，爸爸蹲下来安慰他。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用笑脸安慰着生病的朋友。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一束花去安慰住院的同事。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗走过来，好像在安慰伤心的主人。", "target_word": "安慰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "安慰了", "label": "体标"}, {"form": "安慰着", "label": "体标"}, {"form": "安慰过", "label": "体标"}, {"form": "安慰安慰", "label": "重叠"}], "register": "中性", "sense_fingerprint": "用言语或行动让人心情平静", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd12015e2-7c16-4cde-a171-47414d24e165') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92746, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "安慰", "is_correct": true, "explanation": "“安慰”指让对方心里好受，朋友考试没考好时，“我去安慰他”符合语境。"}, {"text": "祝贺", "is_correct": false, "explanation": "语义：“祝贺”是为喜事道喜，考试没考好时说“去祝贺他”不合情理。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”是称赞对方的优点，与“没考好”的情境不相符。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”多用于品德、景色等，不用来评价考试成绩。"}], "explanations": {"安慰": "“安慰”指让对方心里好受，朋友考试没考好时，“我去安慰他”符合语境。", "祝贺": "语义：“祝贺”是为喜事道喜，考试没考好时说“去祝贺他”不合情理。", "夸奖": "语义：“夸奖”是称赞对方的优点，与“没考好”的情境不相符。", "赞美": "搭配：“赞美”多用于品德、景色等，不用来评价考试成绩。"}, "sentence_index": 0, "correct_answer": "安慰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他得了全班第一，朋友们都过来安慰他。", "explanation": "这里应该用〈祝贺〉。“安慰”针对的是难过的人，得了第一名的人应当被祝贺，不该被安慰。"}, {"text": "老师安慰了那个笑得很开心的同学。", "explanation": "语境矛盾：“安慰”针对的是难过的人，句中同学正开心地笑，与安慰的语境相反。"}, {"text": "他用拳头安慰了朋友。", "explanation": "方式误用：“安慰”是用言语或温和的行动让人平静，用拳头打人不是安慰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92746, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安慰", "is_correct": true, "explanation": "“安慰”表示让孩子心里好受，孩子摔倒哭了，爸爸蹲下来安慰他，符合语境。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”是针对对方的帮助，孩子摔倒哭了时，爸爸不应向他表示感谢。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”针对的是好的表现，与摔倒哭的情境不搭。"}, {"text": "祝福", "is_correct": false, "explanation": "语义：“祝福”是对未来的美好期盼，用在孩子哭的时候说不通。"}], "explanations": {"安慰": "“安慰”表示让孩子心里好受，孩子摔倒哭了，爸爸蹲下来安慰他，符合语境。", "感谢": "语义：“感谢”是针对对方的帮助，孩子摔倒哭了时，爸爸不应向他表示感谢。", "表扬": "搭配：“表扬”针对的是好的表现，与摔倒哭的情境不搭。", "祝福": "语义：“祝福”是对未来的美好期盼，用在孩子哭的时候说不通。"}, "sentence_index": 6, "correct_answer": "安慰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他安慰地骂了我一顿。", "explanation": "语义矛盾：“安慰地”表示温和地宽慰，与“骂了我一顿”的责备正相反。"}, {"text": "学校安慰了那位拾金不昧的同学。", "explanation": "这里应该用〈表扬〉。“安慰”是为难过的人宽慰，拾金不昧的同学应当表扬。"}, {"text": "他安慰了那只旧椅子，把它擦得干干净净。", "explanation": "对象误用：“安慰”的对象应当是有感情的人，不能用于椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4be6a56-6de3-4f2a-8abf-94e8205a5896') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
