INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92749, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山脉是一座连着一座的很多高山。", "primary_collocate": null, "pronunciation": "shān mài", "ipa": "ʂan˥ mai˥˩", "syllable_count": 2, "sentences": [{"text": "远处有一条很长的山脉。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条山脉上有很多高山。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们开车翻过了这道山脉。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脉上的雪终年不化。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机从山脉上面飞过。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片山脉里住着很多动物。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，白雪盖住了整条山脉。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脉的另一边是一个小城市。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都去这条山脉爬山。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的山脉是用棕色画的。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "山脈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "许多高山连在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92749, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山脉", "is_correct": true, "explanation": "正确：“山脉”指连绵的群山，与“远处”和“很长的”相符。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指长在人身上，不会位于远处。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是地理上的长条，句子描述的是远处的地形。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：量词“条”不用于“时间”，“远处有”也不能指时长。"}], "explanations": {"山脉": "正确：“山脉”指连绵的群山，与“远处”和“很长的”相符。", "手指": "语义：手指长在人身上，不会位于远处。", "作业": "语义：作业不是地理上的长条，句子描述的是远处的地形。", "时间": "搭配：量词“条”不用于“时间”，“远处有”也不能指时长。"}, "sentence_index": 0, "correct_answer": "山脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们一个小时就攻顶了这条山脉。", "explanation": "语义错误：“攻顶”指登上某座山峰的顶点，山脉是连绵的群山，没有单一的顶点，这里误把它当作〈山峰〉。"}, {"text": "我把这条山脉搬到了书架上。", "explanation": "语义错误：〈山脉〉指真实的地理实体，不能搬到书架上；能放在书架上的应是它的〈模型〉。"}, {"text": "这条山脉就是我家门前的那一座山。", "explanation": "语义错误：〈山脉〉指连绵的群山，不能指门前这样单独的一座山头，这种情况应说〈一座山〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92749, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山脉", "is_correct": true, "explanation": "正确：白雪覆盖的是绵延的群山，“整条”与“盖住”都合适。"}, {"text": "语言", "is_correct": false, "explanation": "语义：白雪只能覆盖有形的地表，“语言”是抽象的，无法被盖住。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“盖住”一般接有形的物体，“整条”也不修饰“名字”。"}, {"text": "晚会", "is_correct": false, "explanation": "语义：晚会是一种活动，白雪不能把它盖住。"}], "explanations": {"山脉": "正确：白雪覆盖的是绵延的群山，“整条”与“盖住”都合适。", "语言": "语义：白雪只能覆盖有形的地表，“语言”是抽象的，无法被盖住。", "名字": "搭配：“盖住”一般接有形的物体，“整条”也不修饰“名字”。", "晚会": "语义：晚会是一种活动，白雪不能把它盖住。"}, "sentence_index": 6, "correct_answer": "山脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们住进了这条山脉的二楼。", "explanation": "语义错误：〈山脉〉是自然地理，不是有楼层的建筑；能住进去的地方应说〈山庄〉。"}, {"text": "他把这条山脉挂在墙上当画。", "explanation": "语义错误：〈山脉〉指真实的群山，不能当作一幅画挂在墙上；挂在墙上的画应是〈山水画〉。"}, {"text": "这条山脉在夏天会涨水，淹没了村子。", "explanation": "语义错误：“山脉”指群山，不是河流，不会涨水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92749, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们沿着这条山脉们走了三天。", "corrected_sentence": "我们沿着这条山脉走了三天。", "error_description": "词尾错误：“山脉”指地理上的连绵群山，不是人，不能加复数词尾“们”，应说“这条山脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92749, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们翻过了这只山脉。", "corrected_sentence": "我们翻过了这条山脉。", "error_description": "量词错误：“只”多用于动物，“山脉”应用量词“条”或“道”，此处应说“这条山脉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
