INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92750, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92750, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "沿一定方向延伸、成条状分布的群山。", "primary_collocate": null, "pronunciation": "shān mài", "ipa": "ʂan˥ mai˥˩", "syllable_count": 2, "sentences": [{"text": "这条山脉从东向西延伸。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脉沿着海边向北延伸。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道山脉像一条长龙。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脉把这个国家分成两部分。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条山脉是南北方向的。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流绕着山脉流向大海。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山脉两边的天气很不一样。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上指出了那条山脉。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路沿着山脉一直修到北方。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条山脉有两千多公里长。", "target_word": "山脉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "道", "label": "量词"}, {"form": "山脈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "沿一定方向延伸的条状群山", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92750, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "山脉", "is_correct": true, "explanation": "正确：“山脉”指沿一定方向延伸的群山，与“从东向西延伸”相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能沿方向延伸。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，没有“从东向西延伸”的空间走向。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：量词“条”不常用于“时间”，且“从东向西”描述空间走向，不能指时间。"}], "explanations": {"山脉": "正确：“山脉”指沿一定方向延伸的群山，与“从东向西延伸”相合。", "手机": "语义：手机是通讯工具，不能沿方向延伸。", "面包": "语义：面包是食物，没有“从东向西延伸”的空间走向。", "时间": "搭配：量词“条”不常用于“时间”，且“从东向西”描述空间走向，不能指时间。"}, "sentence_index": 0, "correct_answer": "山脉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条山脉有五十层，电梯直达顶层。", "explanation": "语义错误：〈山脉〉是连绵的群山，不是有层数、有电梯的〈大厦〉，这里误把它当成了建筑。"}, {"text": "登山队今天开始攻顶这条山脉。", "explanation": "语义错误：攻顶的对象应是〈山峰〉，山脉是连绵的群山，没有单一的顶点，不能说攻顶。"}, {"text": "我们把这条山脉搬进了教室。", "explanation": "语义错误：〈山脉〉指真实的地理实体，不能搬进教室；能搬进教室的应是它的〈模型〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92750, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "山脉", "is_correct": true, "explanation": "正确：“山脉”有两边，两边的天气可以不同，与句意相合。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是抽象的时间过程，没有“两边”，也不会有天气。"}, {"text": "作文", "is_correct": false, "explanation": "语义：作文是文字作品，没有地理上的“两边”。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“两边的天气”指有空间的地方，“名字”不能有两边。"}], "explanations": {"山脉": "正确：“山脉”有两边，两边的天气可以不同，与句意相合。", "历史": "语义：历史是抽象的时间过程，没有“两边”，也不会有天气。", "作文": "语义：作文是文字作品，没有地理上的“两边”。", "名字": "搭配：“两边的天气”指有空间的地方，“名字”不能有两边。"}, "sentence_index": 6, "correct_answer": "山脉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们用一根绳子把这条山脉拴在树上。", "explanation": "语义错误：〈山脉〉是大范围的地理实体，不能用绳子拴在树上；能被拴住的应是〈牲口〉。"}, {"text": "这条山脉的门很大，我们从门进去了。", "explanation": "语义错误：山脉是自然地理，不是有门的建筑。"}, {"text": "他买了一条山脉当作生日礼物。", "explanation": "语义错误：〈山脉〉是大范围的地理实体，不能买来送人；可以买来送人的应是〈纪念品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92750, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这颗山脉从北向南伸展。", "corrected_sentence": "这条山脉从北向南伸展。", "error_description": "量词错误：“颗”用于粒状的小物体，“山脉”是条状延伸的群山，应用量词“条”或“道”，此处应说“这条山脉”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92750, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们沿着这只山脉走了三天。", "corrected_sentence": "我们沿着这道山脉走了三天。", "error_description": "量词错误：“只”多用于动物，“山脉”应用量词“道”或“条”，此处应说“这道山脉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
