INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度比一般略高。", "primary_collocate": null, "pronunciation": "jiào wéi", "ipa": "tɕjɑʊ˥˩ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这个房间不大，但是较为舒服。", "target_word": "较为", "complexity_tier": "T3", "furigana": "zhè gè fáng jiān bú dà dàn shì jiào wéi shū fu", "sentence_source": "generated"}, {"text": "他的家境较为富裕，但从不乱花钱。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路线不是最近的，但走起来较为轻松。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方的冬天较为干燥，要多喝水。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的价格较为合理，所以客人不少。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和哥哥相比，弟弟的性格较为安静。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的题目较为简单，大家都答完了。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个小区的交通较为方便，上班不用开车。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条路的灯光较为暗，晚上走路要小心。", "target_word": "较为", "complexity_tier": "T3", "furigana": "zhè tiáo lù de dēng guāng jiào wéi àn wǎn shang zǒu lù yào xiǎo xīn", "sentence_source": "generated"}, {"text": "今年夏天雨水较为充足，河水也涨高了。", "target_word": "较为", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "较为|副词|程度比一般略高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a27985d7-ed1e-45a0-89a0-5af58ad339f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "较为", "is_correct": true, "explanation": "正确。“较为”表示程度比一般略高，修饰“舒服”最合适。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能修饰“舒服”这类状态形容词。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间已完成，与程度无关，句意不通。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的状态，与“不大，但是……”的现状描述不符。"}], "explanations": {"较为": "正确。“较为”表示程度比一般略高，修饰“舒服”最合适。", "正在": "搭配：“正在”表示动作进行，不能修饰“舒服”这类状态形容词。", "已经": "语义：“已经”表示时间已完成，与程度无关，句意不通。", "曾经": "语义：“曾经”指过去的状态，与“不大，但是……”的现状描述不符。"}, "sentence_index": 0, "correct_answer": "较为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天比昨天较为热，大家都出汗了。", "explanation": "这里应该用〈更〉，说“比昨天更热”。“比”字句已经表示比较，要用“更”，不能再用“较为”。"}, {"text": "这道题最较为难，大家都不会做。", "explanation": "这里应该去掉〈较为〉，说“最难”。“最”已表示最高程度，不能与“较为”同用。"}, {"text": "这家店的菜有点较为贵，我们不常来。", "explanation": "这里应该去掉〈较为〉，说“有点贵”。“有点”已表示程度不高，“较为”也表示程度，二者不能同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "较为", "is_correct": true, "explanation": "正确。“较为”修饰“简单”，表示程度略高，句意通顺。"}, {"text": "并非", "is_correct": false, "explanation": "语义：“并非简单”与后句“大家都答完了”的语境不协调。"}, {"text": "不", "is_correct": false, "explanation": "语义：“不简单”与后句“大家都答完了”的语境不协调。"}, {"text": "仅仅", "is_correct": false, "explanation": "语义：“仅仅”表示只限于，与“题目简单”这一描述不搭。"}], "explanations": {"较为": "正确。“较为”修饰“简单”，表示程度略高，句意通顺。", "并非": "语义：“并非简单”与后句“大家都答完了”的语境不协调。", "不": "语义：“不简单”与后句“大家都答完了”的语境不协调。", "仅仅": "语义：“仅仅”表示只限于，与“题目简单”这一描述不搭。"}, "sentence_index": 6, "correct_answer": "较为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事非常较为重要，大家都要注意。", "explanation": "这里应该去掉〈非常〉。“较为”本身表示程度适中，不能再用“非常”修饰。"}, {"text": "天气越较为冷，大家都穿上了厚衣服。", "explanation": "这里应该去掉〈较为〉，说“天气越来越冷”。“越……”结构中不能加“较为”。"}, {"text": "这个汤太较为咸，我一口都没喝。", "explanation": "这里应该去掉〈较为〉，说“太咸”。“太”已表示程度过高，不能与“较为”同用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街人少，晚上走起来很较为安静。", "corrected_sentence": "这条街人少，晚上走起来较为安静。", "error_description": "错误：“较为”前面多加了程度副词“很”，写成“很较为安静”。正确：“较为安静”。原因：“较为”本身已表示程度，前面不能再加“很”等程度副词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92753, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个地方的房租不较为便宜，很多学生都住在这里。", "corrected_sentence": "这个地方的房租较为便宜，很多学生都住在这里。", "error_description": "错误：“不”放在了“较为”前面，写成“不较为便宜”。正确：“较为便宜”。原因：“较为”不能被“不”修饰，表示否定时应说“不便宜”或“不太便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
