INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92757, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开年是新的一年刚开始的时候。", "primary_collocate": null, "pronunciation": "kāi nián", "ipa": "kʰaɪ̯˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "开年的时候，街上到处都是红灯笼。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年了，大家都说新年好。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年后，我们一起去学游泳。", "target_word": "开年", "complexity_tier": "T3", "furigana": "kāi nián hòu, wǒ men yì qǐ qù xué yóu yǒng.", "sentence_source": "generated"}, {"text": "开年这几天，商店都不开门。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说开年要多陪陪家人。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年时，孩子们穿上了新衣服。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一到开年，妈妈就做很多好吃的。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年头一周，我每天早起跑步。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她开年就定了一个小目标。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年后的第一个周末，我们去看奶奶。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "開年", "label": "繁体"}], "register": "中性", "sense_fingerprint": "新的一年刚开始的时候", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92757, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开年", "is_correct": true, "explanation": "正确：“开年的时候”指新年刚开始的时候，与“街上到处都是红灯笼”的节日氛围相符。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁不是时间，“地铁的时候”无法表示时间，句意不通。"}, {"text": "河水", "is_correct": false, "explanation": "语义：河水不表示时间，“河水的时候”说不通。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“……的时候”需要时间词，“课本”不能表示时间，搭配不当。"}], "explanations": {"开年": "正确：“开年的时候”指新年刚开始的时候，与“街上到处都是红灯笼”的节日氛围相符。", "地铁": "语义：地铁不是时间，“地铁的时候”无法表示时间，句意不通。", "河水": "语义：河水不表示时间，“河水的时候”说不通。", "课本": "搭配：“……的时候”需要时间词，“课本”不能表示时间，搭配不当。"}, "sentence_index": 0, "correct_answer": "开年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部手机的开年很快。", "explanation": "这里应该用〈开机〉。开年指新年的开头，手机打开应说“开机”。"}, {"text": "我家买了一台开年。", "explanation": "这里量词用错。“台”用于机器，开年是时间，不是机器，不能用“台”计量。"}, {"text": "这篇小说的开年很吸引人。", "explanation": "这里应该用〈开头〉。开年指新年的开头，不能用于小说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92757, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开年", "is_correct": true, "explanation": "正确：“一到开年”指新年一开始，与“妈妈就做很多好吃的”的语境相符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不表示时间，“一到雨伞”无法成立。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不表示时间，“一到玻璃，妈妈就做很多好吃的”句意不通。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“一到”后要接时间或地点，“数学”不能作时间，搭配不当。"}], "explanations": {"开年": "正确：“一到开年”指新年一开始，与“妈妈就做很多好吃的”的语境相符。", "雨伞": "语义：雨伞不表示时间，“一到雨伞”无法成立。", "玻璃": "语义：玻璃不表示时间，“一到玻璃，妈妈就做很多好吃的”句意不通。", "数学": "搭配：“一到”后要接时间或地点，“数学”不能作时间，搭配不当。"}, "sentence_index": 6, "correct_answer": "开年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "音乐会开年了，大家都很激动。", "explanation": "这里应该用〈开幕〉。音乐会说开幕，开年指新年的开头，不能用于音乐会。"}, {"text": "我们去山里看了一座开年。", "explanation": "这里量词用错。“座”用于山、桥等大型建筑，开年是时间，不能用“座”计量。"}, {"text": "这条路的开年很快。", "explanation": "这里应该用〈通车〉。开年指新年的开头，道路开放应说“通车”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92757, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开年了时，街上很热闹。", "corrected_sentence": "开年时，街上很热闹。", "error_description": "“了”多余：“开年时”后不能加“了”，应说“开年时”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92757, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开年的后，我们去了公园。", "corrected_sentence": "开年后，我们去了公园。", "error_description": "“的”多余：“开年”后接“后”时中间不能加“的”，应说“开年后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
