INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92758, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年的开头；新年伊始。", "primary_collocate": null, "pronunciation": "kāi nián", "ipa": "kʰaɪ̯˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "开年以后，公司的事情特别多。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年第一天，我们全家去爬山。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年时天气很冷，常常下雪。", "target_word": "开年", "complexity_tier": "T3", "furigana": "kāi nián shí tiān qì hěn lěng, cháng cháng xià xuě.", "sentence_source": "generated"}, {"text": "开年的计划，他已经写好了。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到开年，火车站都有很多人。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年不久，他就换了新工作。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年时大家互相说祝福的话。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年前，老板请大家吃了饭。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望开年能有个好开始。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开年的第一场雪下得很大。", "target_word": "开年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "開年", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一年的开头，新年伊始的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92758, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开年", "is_correct": true, "explanation": "正确：“开年”指一年的开头，“开年以后”指新年开始之后，与“公司的事情特别多”相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不表示时间，“手机以后”无法表示时间的先后，句意不通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不表示时间，“蛋糕以后”无法作为时间点，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“以后”前要接时间词，“颜色”不能表示时间，搭配不当。"}], "explanations": {"开年": "正确：“开年”指一年的开头，“开年以后”指新年开始之后，与“公司的事情特别多”相符。", "手机": "语义：手机不表示时间，“手机以后”无法表示时间的先后，句意不通。", "蛋糕": "语义：蛋糕不表示时间，“蛋糕以后”无法作为时间点，句意不通。", "颜色": "搭配：“以后”前要接时间词，“颜色”不能表示时间，搭配不当。"}, "sentence_index": 0, "correct_answer": "开年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的开年很精彩。", "explanation": "这里应该用〈开头〉。开年指一年的开头，不能用于文章。"}, {"text": "这场比赛的开年很顺利。", "explanation": "这里应该用〈开局〉。开年指新年开始的一段时间，不指比赛的开始。"}, {"text": "我买了两只开年。", "explanation": "这里量词用错。“只”用于动物或成对的东西，开年是时间，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92758, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开年", "is_correct": true, "explanation": "正确：“开年时”指新年开始的时候，符合大家互相说祝福的场景。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不表示时间，“窗户时大家互相说祝福的话”无法成立。"}, {"text": "蚂蚁", "is_correct": false, "explanation": "语义：蚂蚁是动物，不表示时间，“蚂蚁时”句意不通。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：“……时”需要时间词，“字典”不能作时间，搭配不当。"}], "explanations": {"开年": "正确：“开年时”指新年开始的时候，符合大家互相说祝福的场景。", "窗户": "语义：窗户不表示时间，“窗户时大家互相说祝福的话”无法成立。", "蚂蚁": "语义：蚂蚁是动物，不表示时间，“蚂蚁时”句意不通。", "字典": "搭配：“……时”需要时间词，“字典”不能作时间，搭配不当。"}, "sentence_index": 6, "correct_answer": "开年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电影的开年很精彩。", "explanation": "这里应该用〈开场〉。开年指新年开始的时期，不能指电影的开始。"}, {"text": "展览开年了，很多人都去看了。", "explanation": "这里应该用〈开幕〉。展览说开幕，开年指新年的开头，不能用于展览。"}, {"text": "我买了一辆开年。", "explanation": "这里量词用错。“辆”用于车辆，开年是时间，不是可以用“辆”计量的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92758, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "开年的以后，我们要做很多计划。", "corrected_sentence": "开年以后，我们要做很多计划。", "error_description": "“的”多余：“开年”后接“以后”时中间不能加“的”，应说“开年以后”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92758, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起讨论开年的了安排。", "corrected_sentence": "我们一起讨论开年的安排。", "error_description": "“了”位置错误：“了”不能放在定语“开年的”和中心语“安排”之间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
