INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92759, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92759, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "怎么回事是问发生了什么事，为什么会这样。", "primary_collocate": null, "pronunciation": "zěn me huí shì", "ipa": "tʂən˨˩ mɘ xweɪ˧˥ ʂʅ˥˩", "syllable_count": 4, "sentences": [{"text": "你今天怎么回事？一直在哭。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机怎么回事？突然不能用了。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是怎么回事？水为什么是黑的？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天没来，到底怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的作业不见了，这是怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一直不亮，这是怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天这么热，空调怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的脸这么红，是怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车停在路上不动了，怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问他：“你的书包怎么回事？”", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么回事儿", "label": "儿化形式"}], "register": "口语", "sense_fingerprint": "问发生了什么事、为什么会这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92759, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎么回事", "is_correct": true, "explanation": "“怎么回事”问发生了什么、为什么会这样，与“一直在哭”的情况相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问的是人，而句子问的是状况和原因，“你今天谁”不成立。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，句子里没有可以计数的对象。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“什么”之后要接谓语，“你今天什么”缺少能与之搭配的成分，句子不成立。"}], "explanations": {"怎么回事": "“怎么回事”问发生了什么、为什么会这样，与“一直在哭”的情况相符。", "谁": "语义：“谁”问的是人，而句子问的是状况和原因，“你今天谁”不成立。", "多少": "语义：“多少”问数量，句子里没有可以计数的对象。", "什么": "配价：“什么”之后要接谓语，“你今天什么”缺少能与之搭配的成分，句子不成立。"}, "sentence_index": 0, "correct_answer": "怎么回事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想学做饭，这个菜谱我看不懂，请你教我怎么回事。", "explanation": "这里误把〈怎么回事〉当作“怎么做”来用，应该用〈怎么做〉。“怎么回事”问发生了什么或为什么这样，不问具体的做法。"}, {"text": "这部电影你觉得怎么回事？", "explanation": "这里应该用〈怎么样〉。“怎么回事”问发生了什么或为什么这样，不用于征求对电影的评价。"}, {"text": "我不会用这台机器，请你教我怎么回事。", "explanation": "这里应该用〈怎么用〉。“怎么回事”问原因或经过，不问操作的方法，也不能作“教”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92759, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么回事", "is_correct": true, "explanation": "“怎么回事”问空调发生了什么，与“天这么热”的语境相符。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“什么”要求后接谓语或名词性成分，“空调什么”不成立。"}, {"text": "哪个", "is_correct": false, "explanation": "配价：“哪个”需要在一组对象中选择，句中没有给出这样的范围。"}, {"text": "哪种", "is_correct": false, "explanation": "搭配：“哪种”要求后接类别名词，“空调哪种”无法表达这个问句。"}], "explanations": {"怎么回事": "“怎么回事”问空调发生了什么，与“天这么热”的语境相符。", "什么": "配价：“什么”要求后接谓语或名词性成分，“空调什么”不成立。", "哪个": "配价：“哪个”需要在一组对象中选择，句中没有给出这样的范围。", "哪种": "搭配：“哪种”要求后接类别名词，“空调哪种”无法表达这个问句。"}, "sentence_index": 6, "correct_answer": "怎么回事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋子漏水了，我们该怎么回事？", "explanation": "这里应该用〈怎么办〉。“怎么回事”问发生了什么或为什么这样，不用于问接下来如何处理。"}, {"text": "这个方案你觉得怎么回事？", "explanation": "这里应该用〈怎么样〉。“怎么回事”问原因或经过，不用于征求对方案的评价。"}, {"text": "我想学做蛋糕，请你教我怎么回事。", "explanation": "这里应该用〈怎么做〉。“怎么回事”问发生了什么或为什么，不用于问做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92759, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的电脑突然把黑屏了，这是怎么回事？", "corrected_sentence": "我的电脑突然黑屏了，这是怎么回事？", "error_description": "把字句错误：“突然把黑屏了”中多出“把”。“黑屏”是不及物的状态变化，不能用“把”引出，应说“突然黑屏了”。去掉“把”即正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92759, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的耳机突然没声音了，这是怎么回事吗？", "corrected_sentence": "我的耳机突然没声音了，这是怎么回事？", "error_description": "语气词错误：“怎么回事”本身已是疑问结构，句末不能再加疑问语气词“吗”，应说“这是怎么回事？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
