INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "询问事情的原因或经过的疑问短语。", "primary_collocate": null, "pronunciation": "zěn me huí shì", "ipa": "tʂən˨˩ mɘ xweɪ˧˥ ʂʅ˥˩", "syllable_count": 4, "sentences": [{"text": "你先说说，昨天到底是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你告诉我，这件事是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把整件事的经过讲了，我才明白是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也不知道这是怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问我：“这是怎么回事？”", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他哭了，妈妈想知道怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的脸上有伤，到底怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在看我，我不明白怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们吵什么？先让我弄清楚怎么回事。", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋里这么乱，是怎么回事？", "target_word": "怎么回事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么回事儿", "label": "儿化形式"}], "register": "口语", "sense_fingerprint": "询问事情的原因或经过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92c164eb-a700-4e23-b7c0-fb840f4fdc05') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怎么回事", "is_correct": true, "explanation": "“怎么回事”询问事情的原因或经过，与“你先说说”的语境相符。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，句子问的是事情的原因或经过。"}, {"text": "哪里", "is_correct": false, "explanation": "语义：“哪里”问地点，句子要求的是对经过的说明。"}, {"text": "哪个", "is_correct": false, "explanation": "配价：“哪个”需要在一组可选对象中选择，句中没有这样的范围。"}], "explanations": {"怎么回事": "“怎么回事”询问事情的原因或经过，与“你先说说”的语境相符。", "多少": "语义：“多少”问数量，句子问的是事情的原因或经过。", "哪里": "语义：“哪里”问地点，句子要求的是对经过的说明。", "哪个": "配价：“哪个”需要在一组可选对象中选择，句中没有这样的范围。"}, "sentence_index": 0, "correct_answer": "怎么回事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想学游泳，你能教我怎么回事吗？", "explanation": "这里误把〈怎么回事〉当作“怎么做”来用，应该用〈怎么做〉。“怎么回事”问发生了什么或为什么这样，不问具体的做法。"}, {"text": "这部小说你觉得怎么回事？", "explanation": "这里应该用〈怎么样〉。“怎么回事”问原因或经过，不用于征求对小说的评价。"}, {"text": "这台洗衣机我不会用，请你教我怎么回事。", "explanation": "这里应该用〈怎么用〉。“怎么回事”问原因或经过，不问操作的方法，也不能作“教”的对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怎么回事", "is_correct": true, "explanation": "“怎么回事”询问脸上有伤的原因，与句意相符。"}, {"text": "多少", "is_correct": false, "explanation": "语义：“多少”问数量，句子问的是受伤的原因，不是伤的数目。"}, {"text": "什么", "is_correct": false, "explanation": "配价：“什么”之后需要谓语，“到底什么”缺少能与之搭配的成分。"}, {"text": "哪种", "is_correct": false, "explanation": "搭配：“哪种”要求后接类别名词，“到底哪种”无法表达这个问句。"}], "explanations": {"怎么回事": "“怎么回事”询问脸上有伤的原因，与句意相符。", "多少": "语义：“多少”问数量，句子问的是受伤的原因，不是伤的数目。", "什么": "配价：“什么”之后需要谓语，“到底什么”缺少能与之搭配的成分。", "哪种": "搭配：“哪种”要求后接类别名词，“到底哪种”无法表达这个问句。"}, "sentence_index": 6, "correct_answer": "怎么回事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题我不会做，你能教我怎么回事。", "explanation": "这里应该用〈怎么做〉。怎么回事询问原因或经过，不问具体的做法。"}, {"text": "这次比赛输了，我们下一步怎么回事？", "explanation": "这里应该用〈怎么办〉。“怎么回事”问发生了什么或为什么这样，不问接下来如何处理。"}, {"text": "我想换个发型，请你教我怎么回事。", "explanation": "这里应该用〈怎么做〉。“怎么回事”问原因或经过，不问具体的做法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不明白这件事到底是怎么回事吗？", "corrected_sentence": "我不明白这件事到底是怎么回事。", "error_description": "语气词错误：“怎么回事”本身已是疑问结构，句中不能再加疑问语气词“吗”。应说“到底是怎么回事”，不说“到底是怎么回事吗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92760, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里的灯突然很灭了，这是怎么回事？", "corrected_sentence": "屋里的灯突然灭了，这是怎么回事？", "error_description": "程度副词错误：“很”不能修饰“灭”这类动作性的变化动词，“突然很灭了”不成立。去掉“很”即正确。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f262bbe3-ba7d-446d-adc6-e525308585e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拔出", "is_correct": true, "explanation": "拔出：把陷在里面的东西拉出来，与“陷入泥坑”的意思相反。"}, {"text": "观看", "is_correct": false, "explanation": "观看：指用眼睛看，与“陷入”没有反义关系，句中不通顺。"}, {"text": "准备", "is_correct": false, "explanation": "准备：指事先安排，与“陷入”不构成反义，句中也不合适。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指把坏的东西修好，与“陷入泥坑”没有反义关系。"}], "correct_answer": "拔出", "explanations": {"拔出": "拔出：把陷在里面的东西拉出来，与“陷入泥坑”的意思相反。", "观看": "观看：指用眼睛看，与“陷入”没有反义关系，句中不通顺。", "准备": "准备：指事先安排，与“陷入”不构成反义，句中也不合适。", "修理": "修理：指把坏的东西修好，与“陷入泥坑”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "脱出", "is_correct": true, "explanation": "脱出：从流沙里出来，与“陷入流沙”的意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买：指花钱买东西，与“陷入”没有反义关系，句中不通顺。"}, {"text": "测量", "is_correct": false, "explanation": "测量：指量出长度或大小，与“陷入流沙”不构成反义。"}, {"text": "粉刷", "is_correct": false, "explanation": "粉刷：指给墙面涂颜料，与“陷入流沙”没有反义关系。"}], "correct_answer": "脱出", "explanations": {"脱出": "脱出：从流沙里出来，与“陷入流沙”的意思相反。", "购买": "购买：指花钱买东西，与“陷入”没有反义关系，句中不通顺。", "测量": "测量：指量出长度或大小，与“陷入流沙”不构成反义。", "粉刷": "粉刷：指给墙面涂颜料，与“陷入流沙”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "陷入是掉进去，出不来。", "primary_collocate": null, "pronunciation": "xiàn rù", "ipa": "ɕjɛn⁵¹ ɻu⁵¹", "syllable_count": 2, "sentences": [{"text": "汽车陷入了泥里。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脚陷入雪地里。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车轮陷入沙子里，开不出来。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一不小心，鞋子陷入了泥坑。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大象的腿陷入了河边的烂泥。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙发太软，人一坐就陷入其中。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的脚陷入沼泽，拔不出来。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "卡车陷入深深的泥坑。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小车陷入雪中，走不动了。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢陷入了流沙里。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陷入了", "label": "体标"}], "register": "书面", "sense_fingerprint": "身体或物体掉进泥、雪、沙等里面出不来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陷入", "is_correct": true, "explanation": "正确答案：陷入（xiànrù）。"}, {"text": "线路", "is_correct": false, "explanation": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。"}, {"text": "显露", "is_correct": false, "explanation": "显露 xiǎnlù 第一个音节声调不同（xiǎn 为第三声，xiàn 为第四声），第二个音节 lù 与 rù 声母不同（l 与 r），意思是表现出来。"}, {"text": "先入", "is_correct": false, "explanation": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入。"}, {"text": "现任", "is_correct": false, "explanation": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}], "explanations": {"陷入": "正确答案：陷入（xiànrù）。", "线路": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。", "显露": "显露 xiǎnlù 第一个音节声调不同（xiǎn 为第三声，xiàn 为第四声），第二个音节 lù 与 rù 声母不同（l 与 r），意思是表现出来。", "先入": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入。", "现任": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}, "sentence_index": null, "correct_answer": "陷入"}, "level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：物体掉进泥里出不来，与句意相合。"}, {"text": "跳进", "is_correct": false, "explanation": "语义：“跳进”的主语要能跳，汽车不能跳进泥里。"}, {"text": "擦拭", "is_correct": false, "explanation": "搭配：“擦拭”多搭配物体表面，不说擦拭泥里。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”多搭配房间、场地，不说打扫泥里。"}], "explanations": {"陷入": "陷入：物体掉进泥里出不来，与句意相合。", "跳进": "语义：“跳进”的主语要能跳，汽车不能跳进泥里。", "擦拭": "搭配：“擦拭”多搭配物体表面，不说擦拭泥里。", "打扫": "搭配：“打扫”多搭配房间、场地，不说打扫泥里。"}, "sentence_index": 0, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "太阳慢慢陷入了西山。", "explanation": "这里应该用〈沉入〉。陷入指东西掉进泥、雪里出不来，太阳落山并不是被困住，要用沉入。"}, {"text": "他把牛奶陷入了碗里。", "explanation": "这里应该用〈倒入〉。陷入指东西掉进泥、雪里出不来，把牛奶倒进碗里是移动，不是陷住，要用倒入。"}, {"text": "他把钥匙陷入了抽屉里。", "explanation": "这里应该用〈扔进〉。陷入指东西陷进泥、雪里出不来，把钥匙扔进抽屉不是陷住，要用扔进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：脚陷进沼泽里，符合句意。"}, {"text": "扔进", "is_correct": false, "explanation": "语义：“扔进”指把物体抛进去，脚不能被扔进沼泽。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的宾语多是衣物、身体，不说洗沼泽。"}, {"text": "踢", "is_correct": false, "explanation": "搭配：“踢”的宾语多是球或物件，踢沼泽不合常理。"}], "explanations": {"陷入": "陷入：脚陷进沼泽里，符合句意。", "扔进": "语义：“扔进”指把物体抛进去，脚不能被扔进沼泽。", "洗": "搭配：“洗”的宾语多是衣物、身体，不说洗沼泽。", "踢": "搭配：“踢”的宾语多是球或物件，踢沼泽不合常理。"}, "sentence_index": 6, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水陷入了大海。", "explanation": "这里应该用〈流入〉。陷入指东西掉进泥、雪里出不来，河水流入大海是流动，不是被困住，要用流入。"}, {"text": "他们陷入了新房子。", "explanation": "这里应该用〈搬进〉。陷入指东西掉进泥、雪里出不来，搬进新房子是入住，不是被困住，要用搬进。"}, {"text": "他把水陷入了杯子里。", "explanation": "这里应该用〈注入〉。陷入指东西掉进泥、雪里出不来，往杯子里注水不是被困住，要用注入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车子陷入在沙坑，动不了。", "corrected_sentence": "车子陷入了沙坑，动不了。", "error_description": "“在”误用：“陷入”后可直接带处所，不需要“在”，应说“陷入了沙坑”（或说“陷在沙坑里”）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92763, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小船被陷入了湖底的淤泥。", "corrected_sentence": "小船陷入了湖底的淤泥。", "error_description": "“被”误用：“陷入”不能用“被”构成被动式，应说“小船陷入了湖底的淤泥”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "摆脱", "is_correct": true, "explanation": "摆脱：指脱离困境或束缚，与“陷入不利境地”的意思相反。"}, {"text": "完成", "is_correct": false, "explanation": "完成：指做完某件事，与“陷入”不构成反义关系，句中也不通顺。"}, {"text": "观察", "is_correct": false, "explanation": "观察：指仔细看，与“陷入”没有反义关系，不能替代句中的意思。"}, {"text": "准备", "is_correct": false, "explanation": "准备：指事先安排，与“陷入”的意思不相对，句中也不合适。"}], "correct_answer": "摆脱", "explanations": {"摆脱": "摆脱：指脱离困境或束缚，与“陷入不利境地”的意思相反。", "完成": "完成：指做完某件事，与“陷入”不构成反义关系，句中也不通顺。", "观察": "观察：指仔细看，与“陷入”没有反义关系，不能替代句中的意思。", "准备": "准备：指事先安排，与“陷入”的意思不相对，句中也不合适。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "走出", "is_correct": true, "explanation": "走出：从回忆中出来，与“陷入回忆”的意思相反。"}, {"text": "尝试", "is_correct": false, "explanation": "尝试：指动手试一试，与“陷入”没有反义关系，句中不通顺。"}, {"text": "修理", "is_correct": false, "explanation": "修理：指把坏的东西修好，与“陷入回忆”没有反义关系。"}, {"text": "考虑", "is_correct": false, "explanation": "考虑：指思量，与“陷入”不构成反义，不能替代句中的意思。"}], "correct_answer": "走出", "explanations": {"走出": "走出：从回忆中出来，与“陷入回忆”的意思相反。", "尝试": "尝试：指动手试一试，与“陷入”没有反义关系，句中不通顺。", "修理": "修理：指把坏的东西修好，与“陷入回忆”没有反义关系。", "考虑": "考虑：指思量，与“陷入”不构成反义，不能替代句中的意思。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "落入不利的境地或状态；深深地进入。", "primary_collocate": null, "pronunciation": "xiàn rù", "ipa": "ɕjɛn⁵¹ ɻu⁵¹", "syllable_count": 2, "sentences": [{"text": "公司陷入了困难。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着照片，陷入了沉思。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家陷入了战争。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到消息，她陷入了痛苦。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人陷入了激烈的争吵。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电后，小城陷入一片黑暗。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生意陷入了危机。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太累了，很快就陷入了沉睡。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能让自己陷入麻烦。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到老房子，爸爸陷入了回忆。", "target_word": "陷入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陷入了", "label": "体标"}], "register": "书面", "sense_fingerprint": "落入困难、沉思等不利或深沉的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "陷入", "is_correct": true, "explanation": "正确答案：陷入（xiànrù）。"}, {"text": "线路", "is_correct": false, "explanation": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。"}, {"text": "显露", "is_correct": false, "explanation": "显露 xiǎnlù 第一个音节声调不同（xiǎn 为第三声，xiàn 为第四声），第二个音节 lù 与 rù 声母不同（l 与 r），意思是表现出来。"}, {"text": "先入", "is_correct": false, "explanation": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入，多见于“先入为主”。"}, {"text": "现任", "is_correct": false, "explanation": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}], "explanations": {"陷入": "正确答案：陷入（xiànrù）。", "线路": "线路 xiànlù 与 陷入 xiànrù 只有第二个音节不同：lù 与 rù 声母不同（l 与 r），意思是线路。", "显露": "显露 xiǎnlù 第一个音节声调不同（xiǎn 为第三声，xiàn 为第四声），第二个音节 lù 与 rù 声母不同（l 与 r），意思是表现出来。", "先入": "先入 xiānrù 与 陷入 xiànrù 只有第一个音节声调不同（xiān 为第一声，xiàn 为第四声），意思是先进入，多见于“先入为主”。", "现任": "现任 xiànrèn 与 陷入 xiànrù 第二个音节只有韵母不同（rèn 与 rù），意思是现在担任某个职务。"}, "sentence_index": null, "correct_answer": "陷入"}, "level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：落入困难的境地，与句意相合。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”的对象是场所、展览等，困难不能被参观。"}, {"text": "赢得", "is_correct": false, "explanation": "搭配：“赢得”多搭配胜利、尊重，不说赢得困难。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”多搭配生活、待遇，不说享受困难。"}], "explanations": {"陷入": "陷入：落入困难的境地，与句意相合。", "参观": "语义：“参观”的对象是场所、展览等，困难不能被参观。", "赢得": "搭配：“赢得”多搭配胜利、尊重，不说赢得困难。", "享受": "搭配：“享受”多搭配生活、待遇，不说享受困难。"}, "sentence_index": 0, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她陷入了一顿丰盛的晚饭。", "explanation": "这里应该用〈吃〉。陷入指落入不利的境地或深陷某种状态，不用来指吃饭，要用吃。"}, {"text": "会议陷入了高潮，大家都很兴奋。", "explanation": "这里应该用〈进入〉。陷入指落入不利的境地，会议热烈地发展属于正常过程，要用进入。"}, {"text": "他陷入了一场晚会。", "explanation": "这里应该用〈参加〉。陷入指落入不利的境地或深陷某种状态，不表示到场参加，要用参加。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陷入", "is_correct": true, "explanation": "陷入：陷入危机，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”多搭配艺术品、风景，不说欣赏危机。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：“品尝”指尝食物的味道，与危机无关。"}, {"text": "建造", "is_correct": false, "explanation": "搭配：“建造”多搭配房屋、桥梁，不说建造危机。"}], "explanations": {"陷入": "陷入：陷入危机，符合句意。", "欣赏": "搭配：“欣赏”多搭配艺术品、风景，不说欣赏危机。", "品尝": "语义：“品尝”指尝食物的味道，与危机无关。", "建造": "搭配：“建造”多搭配房屋、桥梁，不说建造危机。"}, "sentence_index": 6, "correct_answer": "陷入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直陷入锻炼身体。", "explanation": "这里应该用〈坚持〉。陷入表示落入不利的境地或深陷某种状态，不用于持续做某件事，坚持锻炼要用坚持。"}, {"text": "我们在海边陷入着阳光。", "explanation": "这里应该用〈享受〉。陷入表示深深地进入不利或沉重的状态，享受阳光是愉快的事，要用享受。"}, {"text": "他陷入了一封信，很高兴。", "explanation": "这里应该用〈收到〉。陷入表示落入某种境地或深陷某种状态，不能表示接受信件，要用收到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很陷入了深深的忧虑。", "corrected_sentence": "她陷入了深深的忧虑。", "error_description": "“很”误用：“很”不能修饰动词“陷入”，应去掉“很”，说“她陷入了深深的忧虑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92764, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的心情被陷入了低谷。", "corrected_sentence": "她的心情陷入了低谷。", "error_description": "“被”误用：“陷入”不能用“被”构成被动式，应说“心情陷入了低谷”，去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
