INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92769, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "页面是书或手机屏幕上的一页。", "primary_collocate": null, "pronunciation": "yè miàn", "ipa": "jɛ˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这本书的页面已经很旧了。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用手指在手机页面上往下划。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的页面上画着一只小猫。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机页面上有很多小图标。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请仔细检查每个页面，看看有没有印错的字。", "target_word": "页面", "complexity_tier": "T3", "furigana": "qǐng zǐ xì jiǎn chá měi gè yè miàn, kàn kan yǒu méi yǒu yìn cuò de zì.", "sentence_source": "generated"}, {"text": "这个页面太亮了，眼睛不舒服。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在书的页面上写了名字。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机页面突然黑了，不能用了。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老书的页面是黄色的。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着手机页面，笑了起来。", "target_word": "页面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个页面", "label": "量词"}, {"form": "頁面", "label": "繁体"}], "register": "中性", "sense_fingerprint": "书或手机屏幕上的一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87559d69-6226-45a9-b346-d294e15626a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92769, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "页面", "is_correct": true, "explanation": "正确：页面指书的一页，“这本书的页面”指书里的一页，“已经很旧了”符合纸质书的状态。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，不是书本身的一部分，“这本书的书包”说不通。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“天空”不能用“旧”来形容，“这本书的天空已经很旧了”搭配不当。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机与这本书没有从属关系，“这本书的手机”无法成立，句意不通。"}], "explanations": {"页面": "正确：页面指书的一页，“这本书的页面”指书里的一页，“已经很旧了”符合纸质书的状态。", "书包": "语义：书包是装书的袋子，不是书本身的一部分，“这本书的书包”说不通。", "天空": "搭配：“天空”不能用“旧”来形容，“这本书的天空已经很旧了”搭配不当。", "手机": "语义：手机与这本书没有从属关系，“这本书的手机”无法成立，句意不通。"}, "sentence_index": 0, "correct_answer": "页面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书有三本页面。", "explanation": "这里量词用错。“本”用来数整本书，不能用来数书里的一页，应说“三个页面”或“三页”。"}, {"text": "这张新桌子的页面很平整。", "explanation": "这里应该用〈桌面〉。页面指书或屏幕上的一页，桌子的表面应说“桌面”。"}, {"text": "我的书里夹着一只页面。", "explanation": "这里量词用错。“只”用于动物或成对的东西，页面应用“个”或“页”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92769, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "页面", "is_correct": true, "explanation": "正确：“书的页面上”指书的一页，符合“在……上写名字”的语境。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是建筑的一部分，不是书的一部分，“书的墙”不成立，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“写”需要有可写的载体，空气不能用来写字，“在空气上写了名字”搭配不当。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户与书没有从属关系，“书的窗户”无法理解，“弟弟在书的窗户上写了名字”说不通。"}], "explanations": {"页面": "正确：“书的页面上”指书的一页，符合“在……上写名字”的语境。", "墙": "语义：墙是建筑的一部分，不是书的一部分，“书的墙”不成立，句意不通。", "空气": "搭配：“写”需要有可写的载体，空气不能用来写字，“在空气上写了名字”搭配不当。", "窗户": "语义：窗户与书没有从属关系，“书的窗户”无法理解，“弟弟在书的窗户上写了名字”说不通。"}, "sentence_index": 6, "correct_answer": "页面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在墙上挂了一朵页面。", "explanation": "这里量词用错。“朵”用于花、云等，页面不是花，不能用“朵”计量。"}, {"text": "这把椅子的页面很干净。", "explanation": "这里应该用〈椅面〉。页面指书或屏幕上的一页，椅子的表面应说“椅面”。"}, {"text": "他骑着一辆页面去上班。", "explanation": "这里量词用错。“辆”用于车辆，页面不是车，不能用“辆”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92769, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本书的一本页面撕破了。", "corrected_sentence": "这本书的一个页面撕破了。", "error_description": "量词错误：页面应用“个”或“页”计量，“一本”是用来数整本书的，不能数其中的一页。应改为“一个页面”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92769, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本旧书少了三页面。", "corrected_sentence": "这本旧书少了三个页面。", "error_description": "量词缺失：页面前的数词后要加量词，应说“三个页面”（或“三页”），不能直接说“三页面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '182d7fa0-45f8-4a57-becb-ff7e1cd5f739') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
