INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92771, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "挖掘是用工具在地上挖，把东西弄出来。", "primary_collocate": null, "pronunciation": "wā jué", "ipa": "ua˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "工人们在路边挖掘一条新水沟。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古队在山上挖掘了一座古墓。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用大机器挖掘地下的煤。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在院子里挖掘出一口旧井。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在马路下挖掘旧管道。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在山脚下挖掘水渠，准备种田。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古学家小心地挖掘着地下的古城。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们挖掘了三天，终于找到了那些老瓷器。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "矿工们每天在地下挖掘煤炭。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里正在挖掘一个很大的坑，请不要靠近。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖掘了", "label": "完成体"}, {"form": "挖掘着", "label": "持续体"}, {"form": "挖掘过", "label": "经历体"}, {"form": "挖掘机", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用工具在地下挖，把埋着的东西取出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92771, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "砍伐", "is_correct": false, "explanation": "搭配：“砍伐”的对象是树木、森林，不能用来说挖一条水沟。"}, {"text": "挖掘", "is_correct": true, "explanation": "“挖掘”指用工具在地上挖，把东西弄出来，与“在路边挖一条新水沟”相符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是可买卖的物品，不能说购买一条水沟。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是庄稼、花草，不能说种植一条水沟。"}], "explanations": {"砍伐": "搭配：“砍伐”的对象是树木、森林，不能用来说挖一条水沟。", "挖掘": "“挖掘”指用工具在地上挖，把东西弄出来，与“在路边挖一条新水沟”相符。", "购买": "搭配：“购买”的对象是可买卖的物品，不能说购买一条水沟。", "种植": "搭配：“种植”的对象是庄稼、花草，不能说种植一条水沟。"}, "sentence_index": 0, "correct_answer": "挖掘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用锯子挖掘了一块木板。", "explanation": "这里应该用〈锯〉。挖掘指用工具挖开地面或泥土，切割木板要用锯。"}, {"text": "他挖掘了一封长信。", "explanation": "这里应该用〈写〉。挖掘指挖出埋在地下或泥土里的东西，写信要用写。"}, {"text": "农民在地里挖掘小麦。", "explanation": "这里应该用〈收割〉。挖掘用于挖出埋在土里的东西，小麦要用收割，割下来即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92771, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收割", "is_correct": false, "explanation": "搭配：“收割”的对象是庄稼，不能用来说挖地下的古城。"}, {"text": "挖掘", "is_correct": true, "explanation": "“挖掘”指用工具挖出地下埋着的东西，与“考古学家小心地挖掘着地下的古城”相符。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发等，不能说修剪地下的古城。"}, {"text": "焚烧", "is_correct": false, "explanation": "语义：“焚烧”是用火烧毁，与“小心地”和考古学家保护古城的语境冲突。"}], "explanations": {"收割": "搭配：“收割”的对象是庄稼，不能用来说挖地下的古城。", "挖掘": "“挖掘”指用工具挖出地下埋着的东西，与“考古学家小心地挖掘着地下的古城”相符。", "修剪": "搭配：“修剪”用于枝叶、头发等，不能说修剪地下的古城。", "焚烧": "语义：“焚烧”是用火烧毁，与“小心地”和考古学家保护古城的语境冲突。"}, "sentence_index": 6, "correct_answer": "挖掘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在树上挖掘苹果。", "explanation": "这里应该用〈采摘〉。挖掘指在地下挖东西，树上的果子要用采摘。"}, {"text": "工人在车间里挖掘零件。", "explanation": "这里应该用〈加工〉。挖掘指挖出埋藏的东西，车间里做零件要用加工。"}, {"text": "警察挖掘了嫌疑人的房间。", "explanation": "这里应该用〈搜查〉。挖掘指挖出埋藏的东西，搜查房间要用搜查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92771, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们在这里挖掘很深。", "corrected_sentence": "工人们在这里挖掘得很深。", "error_description": "缺少“得”：挖掘后面表示程度的“很深”要用“挖掘得很深”，不能说“挖掘很深”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92771, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民在地里挖掘了出一个旧罐子。", "corrected_sentence": "农民在地里挖掘出了一个旧罐子。", "error_description": "语序错误：“了”应放在补语“出”之后，应为“挖掘出了”，不能说“挖掘了出”。补语“出”属于“挖掘”的结果补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
