INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "比喻深入找出还没有被发现的人才、潜力、真相等。", "primary_collocate": null, "pronunciation": "wā jué", "ipa": "ua˥ tɕɥe˧˥", "syllable_count": 2, "sentences": [{"text": "老师帮我挖掘了自己的潜力。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想挖掘更多有能力的年轻人。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在努力挖掘这件事背后的真相。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要挖掘这座老城的历史故事。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从数据里挖掘出了一个新问题。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把这个小镇的美食文化挖掘出来。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教练很会挖掘球员的优点。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家到农村去挖掘写作的好材料。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司正在挖掘市场里的新机会。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师能挖掘每个学生的长处。", "target_word": "挖掘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "挖掘了", "label": "完成体"}, {"form": "挖掘着", "label": "持续体"}, {"form": "挖掘过", "label": "经历体"}, {"form": "数据挖掘", "label": "复合词"}], "register": "中性", "sense_fingerprint": "比喻深入找出还没有被发现的人才、潜力、真相等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "浪费", "is_correct": false, "explanation": "语义：“浪费”是白白用掉或丢掉，与“老师帮我”的积极语境相反。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发，不能说修剪潜力。"}, {"text": "挖掘", "is_correct": true, "explanation": "“挖掘”在这里指深入发现还没被发现的潜力，与“老师帮我挖掘了自己的潜力”相符。"}, {"text": "埋没", "is_correct": false, "explanation": "语义：“埋没”是让人才或能力不被发现，与“老师帮我”的语境矛盾。"}], "explanations": {"浪费": "语义：“浪费”是白白用掉或丢掉，与“老师帮我”的积极语境相反。", "修剪": "搭配：“修剪”用于枝叶、头发，不能说修剪潜力。", "挖掘": "“挖掘”在这里指深入发现还没被发现的潜力，与“老师帮我挖掘了自己的潜力”相符。", "埋没": "语义：“埋没”是让人才或能力不被发现，与“老师帮我”的语境矛盾。"}, "sentence_index": 0, "correct_answer": "挖掘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶挖掘了一块蛋糕。", "explanation": "这里应该用〈切〉。挖掘指挖开地面或深入发现，切蛋糕要用切。"}, {"text": "学生们挖掘了一张白纸。", "explanation": "这里应该用〈折〉。挖掘指深入发现隐藏的事物，纸张没有可挖掘的内容，折纸要用折。"}, {"text": "警察挖掘了嫌疑人的房间。", "explanation": "这里应该用〈搜查〉。挖掘指深入发现隐藏的事物，搜查房间要用搜查。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "挑剔", "is_correct": false, "explanation": "搭配：“挑剔”针对缺点和毛病，不能说挑剔球员的优点。"}, {"text": "剥夺", "is_correct": false, "explanation": "语义：“剥夺”是夺去别人的权利，不能用来形容教练对球员优点的态度。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”针对错误和缺点，与“优点”搭配不当。"}, {"text": "挖掘", "is_correct": true, "explanation": "“挖掘”指深入找出球员的优点，与“这位教练很会挖掘球员的优点”相符。"}], "explanations": {"挑剔": "搭配：“挑剔”针对缺点和毛病，不能说挑剔球员的优点。", "剥夺": "语义：“剥夺”是夺去别人的权利，不能用来形容教练对球员优点的态度。", "批评": "搭配：“批评”针对错误和缺点，与“优点”搭配不当。", "挖掘": "“挖掘”指深入找出球员的优点，与“这位教练很会挖掘球员的优点”相符。"}, "sentence_index": 6, "correct_answer": "挖掘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师挖掘了一锅汤。", "explanation": "这里应该用〈煮〉。挖掘指挖开地面或深入发现，煮汤要用煮。"}, {"text": "小明挖掘了那块黑板。", "explanation": "这里应该用〈擦〉。挖掘指挖开地面或深入发现，擦黑板要用擦。"}, {"text": "妈妈在厨房挖掘衣服。", "explanation": "这里应该用〈洗涤〉。挖掘指深入发现隐藏的事物，衣服要用洗涤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位学者挖掘了得很深。", "corrected_sentence": "这位学者挖掘得很深。", "error_description": "“了”与程度补语“得”不能同时出现：应说“挖掘得很深”，不能说“挖掘了得很深”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "研究员挖掘了出一个隐藏的规律。", "corrected_sentence": "研究员挖掘出了一个隐藏的规律。", "error_description": "语序错误：“了”应放在补语“出”之后，应为“挖掘出了”，不能说“挖掘了出”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "不然是说如果不是这样，就会怎么样。", "primary_collocate": null, "pronunciation": "bù rán", "ipa": "pu˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "快走吧，不然我们要迟到了。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要多穿点衣服，不然会感冒的。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早点睡觉，不然明天起不来。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你小声说话，不然会吵醒孩子。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我得马上走，不然就赶不上火车了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把门关好，不然猫会跑出去。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要认真听课，不然考试会很难。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在出发吧，不然路上会堵车。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一定是忘了，不然早就来电话了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "带上伞吧，不然下雨会淋湿的。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不然的话", "label": "复合"}], "register": "中性", "sense_fingerprint": "连词，表示假设前面的情况不成立，引出另一种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abcd77a8-dfd0-4884-ad5f-32644d4c808a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果不快走，就会出现迟到的结果，引出另一种结果。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结果，“快走吧”推不出“我们要迟到了”。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”是书面语，与口语催促的语境不协调；语义上也推不出迟到。"}, {"text": "然后", "is_correct": false, "explanation": "语义：“然后”表示先后顺序，“快走吧”与“迟到”不是先后关系。"}], "explanations": {"不然": "不然：表示如果不快走，就会出现迟到的结果，引出另一种结果。", "所以": "语义：“所以”表示因果结果，“快走吧”推不出“我们要迟到了”。", "故而": "语域：“故而”是书面语，与口语催促的语境不协调；语义上也推不出迟到。", "然后": "语义：“然后”表示先后顺序，“快走吧”与“迟到”不是先后关系。"}, "sentence_index": 0, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先吃饭，不然去看电影。", "explanation": "这里应该用〈然后〉。不然表示假设不成立时的后果，不能表示先后顺序。"}, {"text": "下雨了，不然我们取消了比赛。", "explanation": "这里应该用〈因此〉。不然表示假设不成立时的后果，不能表示由前一件事导致的结果。"}, {"text": "天冷了，不然我多穿了一件衣服。", "explanation": "这里应该用〈所以〉。不然引出的是不这样做就会出现的后果，表示因果要用所以。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果不认真听课，考试就会很难，引出后果。"}, {"text": "因此", "is_correct": false, "explanation": "语域：“因此”偏书面，与口语语境不符；语义上“认真听课”不会导致“考试很难”。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示承接的结果，“认真听课”与“考试很难”之间没有这种承接关系。"}, {"text": "不料", "is_correct": false, "explanation": "语义：“不料”表示出乎意料，句中并没有意外的情况。"}], "explanations": {"不然": "不然：表示如果不认真听课，考试就会很难，引出后果。", "因此": "语域：“因此”偏书面，与口语语境不符；语义上“认真听课”不会导致“考试很难”。", "于是": "语义：“于是”表示承接的结果，“认真听课”与“考试很难”之间没有这种承接关系。", "不料": "语义：“不料”表示出乎意料，句中并没有意外的情况。"}, "sentence_index": 6, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条路很远，不然风景很好。", "explanation": "这里应该用〈不过〉。不然表示假设不成立时的后果，不能表示转折。"}, {"text": "如果你有空，不然我们就出发。", "explanation": "这里应该用〈那么〉。不然要求前面是不成立的情况，前句是“如果有空”这样的假设时不能用不然。"}, {"text": "他会游泳，不然游得很快。", "explanation": "这里应该用〈而且〉。不然表示不这样就会出现的后果，不能用来补充并列的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得快点走，不然的会赶不上车。", "corrected_sentence": "我们得快点走，不然会赶不上车。", "error_description": "“不然”后面不能直接接“的”，“的”只能组成“不然的话”。这里应去掉“的”，写成“……，不然会赶不上车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92773, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你得多练习，就不然口语会很难提高。", "corrected_sentence": "你得多练习，不然口语会很难提高。", "error_description": "“不然”是连词，前面不能加副词“就”，应直接写成“……，不然口语会很难提高”。这里多加了“就”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示如果不是前面所说的情况，就会出现另一种结果。", "primary_collocate": null, "pronunciation": "bù rán", "ipa": "pu˥˩ ʐan˧˥", "syllable_count": 2, "sentences": [{"text": "多亏你提醒我，不然我就忘了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸好带着伞，不然衣服都湿了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你快点儿吃，不然饭就凉了。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一定有事，不然不会不来。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们得早点去，不然没有座位了。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先写完作业，不然不能出去玩。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好学习，不然你以后会后悔的。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上开慢点，不然很危险。", "target_word": "不然", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "幸亏朋友帮忙，不然我一个人做不完。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把水杯放好，不然会掉在地上。", "target_word": "不然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不然的话", "label": "复合"}], "register": "中性", "sense_fingerprint": "连词，前面是已有的情况，用不然说明否则会出现的另一种结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abcd77a8-dfd0-4884-ad5f-32644d4c808a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果没有你的提醒，就会出现“忘了”的结果。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，“多亏你提醒我”与“我就忘了”不是因果关系。"}, {"text": "因此", "is_correct": false, "explanation": "语域：“因此”偏书面，在口语叙述中不协调；语义上也不能引出忘记。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示递进补充，此处没有补充的理由，“我就忘了”与前句矛盾。"}], "explanations": {"不然": "不然：表示如果没有你的提醒，就会出现“忘了”的结果。", "所以": "语义：“所以”引出结果，“多亏你提醒我”与“我就忘了”不是因果关系。", "因此": "语域：“因此”偏书面，在口语叙述中不协调；语义上也不能引出忘记。", "况且": "语义：“况且”表示递进补充，此处没有补充的理由，“我就忘了”与前句矛盾。"}, "sentence_index": 0, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我没去，不然我生病了。", "explanation": "这里应该用〈因为〉。不然表示假设不成立时的后果，不能说明原因。"}, {"text": "我感冒了，不然今天没去上班。", "explanation": "这里应该用〈所以〉。不然表示如果不这样就会出现的后果，前句是原因、后句是结果时要用所以。"}, {"text": "他很聪明，不然很努力。", "explanation": "这里应该用〈而且〉。不然表示不这样就会出现的后果，不能用来补充并列的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不然", "is_correct": true, "explanation": "不然：表示如果不好好学习，你以后就会后悔，引出另一种结果。"}, {"text": "故而", "is_correct": false, "explanation": "语域：“故而”是书面语，与口语劝告的语境不符；语义上“好好学习”不导致“后悔”。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”引出承接的动作结果，“好好学习”与“后悔”不是承接关系。"}, {"text": "那么", "is_correct": false, "explanation": "语义：“那么”表示推论或结论，“好好学习”推不出“你以后会后悔”。"}], "explanations": {"不然": "不然：表示如果不好好学习，你以后就会后悔，引出另一种结果。", "故而": "语域：“故而”是书面语，与口语劝告的语境不符；语义上“好好学习”不导致“后悔”。", "于是": "语义：“于是”引出承接的动作结果，“好好学习”与“后悔”不是承接关系。", "那么": "语义：“那么”表示推论或结论，“好好学习”推不出“你以后会后悔”。"}, "sentence_index": 6, "correct_answer": "不然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "吃完饭，不然去散步。", "explanation": "这里应该用〈然后〉。不然表示假设不成立时的后果，不能表示动作的先后。"}, {"text": "明天天气好，不然我们就去爬山。", "explanation": "这里应该用〈那么〉。不然要求前面是不成立的情况，前句“天气好”是肯定的假设，不能用不然。"}, {"text": "这个菜很辣，不然很好吃。", "explanation": "这里应该用〈不过〉。不然表示假设不成立时的后果，不能表示转折。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们得早点出门，不然的会没有座位。", "corrected_sentence": "我们得早点出门，不然会没有座位。", "error_description": "“不然”后面不能直接接“的”，应去掉“的”，写成“……，不然会没有座位”。“的”只能组成“不然的话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "好好复习，就不然考试会不及格。", "corrected_sentence": "好好复习，不然考试会不及格。", "error_description": "“不然”是连词，前面不能加副词“就”，应直接写成“……，不然考试会不及格”。这里多加了“就”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
