INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92779, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拥护是很喜欢一个人，还想帮着他。", "primary_collocate": null, "pronunciation": "yōng hù", "ipa": "joŋ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "大家都拥护他，有困难都来帮他。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "dàjiā dōu yōnghù tā, yǒu kùnnan dōu lái bāng tā", "sentence_source": "generated"}, {"text": "同学们都拥护他，愿意帮他的忙。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "tóngxuémen dōu yōnghù tā, yuànyì bāng tā de máng", "sentence_source": "generated"}, {"text": "邻居们都拥护这位老人，有事就去帮他。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "línjūmen dōu yōnghù zhè wèi lǎorén, yǒu shì jiù qù bāng tā", "sentence_source": "generated"}, {"text": "大家都拥护她，因为她对人很好。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都拥护这位好医生，常常帮他的忙。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "cūnlǐ rén dōu yōnghù zhè wèi hǎo yīshēng, chángcháng bāng tā de máng", "sentence_source": "generated"}, {"text": "妈妈很拥护爸爸，还常帮他做准备。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都拥护小李，他有事大家就去帮。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "dàjiā dōu yōnghù Xiǎo Lǐ, tā yǒu shì dàjiā jiù qù bāng", "sentence_source": "generated"}, {"text": "孩子们拥护这位好校长。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都拥护班长，有事都愿意帮他。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "wǒmen dōu yōnghù bānzhǎng, yǒu shì dōu yuànyì bāng tā", "sentence_source": "generated"}, {"text": "很多人拥护这位老板，常来帮他忙。", "target_word": "拥护", "complexity_tier": "T3", "furigana": "hěn duō rén yōnghù zhè wèi lǎobǎn, cháng lái bāng tā máng", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥护了", "label": "体标"}, {"form": "拥护过", "label": "体标"}, {"form": "拥护者", "label": "复合"}, {"form": "擁護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很喜欢一个人并想帮着他", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92779, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥护", "is_correct": true, "explanation": "正确：“拥护”指很喜欢并想帮着他，与“有困难都来帮他”相符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“反对”表示不赞成，与后句“有困难都来帮他”相矛盾。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”表示侵犯，与后句“有困难都来帮他”的意思相矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：“躲避他”后接的是避开的人，与“有困难都来帮他”的主动帮忙搭配冲突。"}], "explanations": {"拥护": "正确：“拥护”指很喜欢并想帮着他，与“有困难都来帮他”相符。", "反对": "语义：“反对”表示不赞成，与后句“有困难都来帮他”相矛盾。", "欺负": "语义：“欺负”表示侵犯，与后句“有困难都来帮他”的意思相矛盾。", "躲避": "搭配：“躲避他”后接的是避开的人，与“有困难都来帮他”的主动帮忙搭配冲突。"}, "sentence_index": 0, "correct_answer": "拥护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家都拥护这项新规定，并在会上公开表态。", "explanation": "此句用的是另一义项〈公开赞成并全力支持〉，指对政策表态，与这里“很喜欢并想帮着他”的意思不同。"}, {"text": "居民们都拥护这项政策，还在会议上发言支持。", "explanation": "此句用的是另一义项〈公开赞成并全力支持〉，指对政策表态，与这里“很喜欢并想帮着他”的意思不同。"}, {"text": "全班都拥护这个主张，并在投票时举手。", "explanation": "此句用的是另一义项〈公开赞成并全力支持〉，指对主张表态，与这里“很喜欢并想帮着他”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92779, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥护", "is_correct": true, "explanation": "正确：“拥护”指很喜欢并想帮着，与“大家就去帮”相符。"}, {"text": "排挤", "is_correct": false, "explanation": "语义：“排挤”是把人挤出去，与后句“有事大家就去帮”的意思相矛盾。"}, {"text": "躲开", "is_correct": false, "explanation": "搭配：“躲开”后接的是要避开的人，与“有事大家就去帮”的主动帮忙搭配冲突。"}, {"text": "冷落", "is_correct": false, "explanation": "语义：“冷落”表示不理睬，与后句“有事大家就去帮”的意思相矛盾。"}], "explanations": {"拥护": "正确：“拥护”指很喜欢并想帮着，与“大家就去帮”相符。", "排挤": "语义：“排挤”是把人挤出去，与后句“有事大家就去帮”的意思相矛盾。", "躲开": "搭配：“躲开”后接的是要避开的人，与“有事大家就去帮”的主动帮忙搭配冲突。", "冷落": "语义：“冷落”表示不理睬，与后句“有事大家就去帮”的意思相矛盾。"}, "sentence_index": 6, "correct_answer": "拥护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都拥护这道菜，常常点它。", "explanation": "这里应该用〈喜欢〉。拥护指很喜欢并想帮着，对食物只能说“喜欢”，不能说想帮忙。"}, {"text": "孩子们都拥护这本书，常常翻它。", "explanation": "这里应该用〈喜爱〉。拥护指很喜欢并想帮着，对书只能说“喜爱”，不能说想帮忙。"}, {"text": "大家都拥护这盏灯，每天开着。", "explanation": "这里应该用〈欣赏〉。拥护指很喜欢并想帮着，对灯只能说“欣赏”，不能说想帮忙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92779, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "街坊们都很拥护他过，有事常来找他帮忙。", "corrected_sentence": "街坊们都很拥护他，有事常来找他帮忙。", "error_description": "错误形式：“拥护他过”。正确形式：“拥护过他”或直接用“拥护他”。“过”表示经历，应紧跟动词，不能放在宾语后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92779, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们都不拥护过他，也不愿帮他。", "corrected_sentence": "同学们都没拥护过他，也不愿帮他。", "error_description": "错误形式：“不拥护过他”。正确形式：“没拥护过他”。表示“未曾有过”的经历要用否定词“没”，“不”不能与表示经历的“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "反对", "is_correct": true, "explanation": "反义：“反对”与“拥护”意思相反，指不赞成甚至加以抵制。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”是日常活动，与“拥护”的赞成之义不构成反义。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”是一种活动，与“拥护”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”是休息的行为，与“拥护”没有反义关系。"}], "correct_answer": "反对", "explanations": {"反对": "反义：“反对”与“拥护”意思相反，指不赞成甚至加以抵制。", "散步": "无关：“散步”是日常活动，与“拥护”的赞成之义不构成反义。", "唱歌": "无关：“唱歌”是一种活动，与“拥护”没有反义关系。", "睡觉": "无关：“睡觉”是休息的行为，与“拥护”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
