INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或主张表示赞成并全力支持。", "primary_collocate": null, "pronunciation": "yōng hù", "ipa": "joŋ˥ xu˥˩", "syllable_count": 2, "sentences": [{"text": "大家都拥护这个好办法。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人民拥护政府的新政策。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们一致拥护他当班长。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都拥护这个决定。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人很拥护新来的村长。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数人拥护这项规定。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拥护过这个计划，现在也一样。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们拥护公司提出的办法。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学都举手拥护他的意见。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不拥护这种做法，因为不公平。", "target_word": "拥护", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "拥护了", "label": "体标"}, {"form": "拥护过", "label": "体标"}, {"form": "拥护者", "label": "复合"}, {"form": "擁護", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或主张表示赞成并全力支持", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c6132e6-803b-447a-bcb0-7084d8062b66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拥护", "is_correct": true, "explanation": "正确：“拥护”表示赞成并全力支持，与“好办法”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，“吃办法”搭配不当。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲等，办法不能唱，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”含有讥讽之意，与“好办法”的褒义相矛盾。"}], "explanations": {"拥护": "正确：“拥护”表示赞成并全力支持，与“好办法”相符。", "吃": "搭配：“吃”的宾语应是食物，“吃办法”搭配不当。", "唱": "语义：“唱”的对象是歌曲等，办法不能唱，句意不通。", "嘲笑": "语义：“嘲笑”含有讥讽之意，与“好办法”的褒义相矛盾。"}, "sentence_index": 0, "correct_answer": "拥护"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都拥护这道菜。", "explanation": "这里应该用〈喜欢〉。拥护用于人或主张，表示公开赞成；对食物的好感要用“喜欢”。"}, {"text": "我们都拥护这首歌。", "explanation": "这里应该用〈赞美〉。拥护用于人或主张；对歌曲的称赞要用“赞美”。"}, {"text": "我们都拥护这盏灯。", "explanation": "这里应该用〈喜爱〉。拥护用于人或主张；对物品的喜爱要用“喜爱”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拥护", "is_correct": true, "explanation": "正确：“拥护过”表示曾经赞成并支持，与“这个计划”及“现在也一样”相符。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，“喝计划”搭配不当。"}, {"text": "喂", "is_correct": false, "explanation": "语义：“喂”的对象是人或动物，计划不能被喂，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”的对象是可以清洗的东西，计划不能洗，句意不通。"}], "explanations": {"拥护": "正确：“拥护过”表示曾经赞成并支持，与“这个计划”及“现在也一样”相符。", "喝": "搭配：“喝”的宾语应是饮品，“喝计划”搭配不当。", "喂": "语义：“喂”的对象是人或动物，计划不能被喂，句意不通。", "洗": "语义：“洗”的对象是可以清洗的东西，计划不能洗，句意不通。"}, "sentence_index": 6, "correct_answer": "拥护"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们都拥护这张桌子，天天用它写作业。", "explanation": "这里应该用〈喜欢〉。拥护用于人或主张，表示公开赞成；对桌子的好感只能说“喜欢”。"}, {"text": "同学们都拥护这支钢笔，每天都带着它。", "explanation": "这里应该用〈喜爱〉。拥护用于人或主张，表示公开赞成；对钢笔的喜爱要用“喜爱”。"}, {"text": "大家都拥护这把椅子，常常坐在上面。", "explanation": "这里应该用〈满意〉。拥护用于人或主张，表示公开赞成；对椅子的感受应用“满意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都拥护这只主张。", "corrected_sentence": "大家都拥护这个主张。", "error_description": "错误形式：“拥护这只主张”。正确形式：“拥护这个主张”。“主张”前应用量词“个”，“只”多用于动物、手等，不能修饰“主张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92780, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们从不拥护过这个决定。", "corrected_sentence": "他们从没拥护过这个决定。", "error_description": "错误形式：“从不拥护过这个决定”。正确形式：“从没拥护过这个决定”。表示“从未有过”的经历要用否定词“没”，“不”不能与表示经历的“过”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d8a4f7-94f0-4bc2-968a-99dbecae4ed9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
