INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92781, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "分裂是一个整体裂开，变成几块。", "primary_collocate": null, "pronunciation": "fēn liè", "ipa": "fən˥˥ lie˥˩", "syllable_count": 2, "sentences": [{"text": "细胞会分裂成两个新细胞。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座冰山在海上分裂成了几块。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块大石头突然分裂成三块。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，河上的冰开始分裂成小块。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震时，这座山分裂成了两半。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小虫的身体可以分裂成两个。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "细胞分裂以后，数量就变多了。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验里，一个水滴分裂成了好几个小水滴。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "岩石遇热后分裂成了许多小块。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看，这个细胞正在分裂成两个。", "target_word": "分裂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "分裂了", "label": "体标（了）"}, {"form": "分裂过", "label": "体标（过）"}, {"form": "细胞分裂", "label": "复合"}], "register": "中性", "sense_fingerprint": "具体的整体（细胞、冰山、岩石）裂开成几块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9536ccae-044a-44e6-b63c-3b9235ea771b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92781, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "分裂", "is_correct": true, "explanation": "正确答案：分裂（fēn liè），指整体裂开，变成几块。"}, {"text": "分类", "is_correct": false, "explanation": "fēn lèi（第四声）与 fēn liè 只有第二个音节的韵母不同（-ei 与 -ie），意思是按类别分开。"}, {"text": "分界", "is_correct": false, "explanation": "fēn jiè（第四声）与 fēn liè 只有第二个音节的声母不同（j 与 l），意思是划分界限。"}, {"text": "分离", "is_correct": false, "explanation": "fēn lí（第二声）与 fēn liè 的声调和韵母都不同，意思是使彼此分开、不再相连。"}], "explanations": {"分裂": "正确答案：分裂（fēn liè），指整体裂开，变成几块。", "分类": "fēn lèi（第四声）与 fēn liè 只有第二个音节的韵母不同（-ei 与 -ie），意思是按类别分开。", "分界": "fēn jiè（第四声）与 fēn liè 只有第二个音节的声母不同（j 与 l），意思是划分界限。", "分离": "fēn lí（第二声）与 fēn liè 的声调和韵母都不同，意思是使彼此分开、不再相连。"}, "sentence_index": null, "correct_answer": "分裂"}, "level_3": {"options": [{"text": "分裂", "is_correct": true, "explanation": "正确答案：分裂，指细胞一分为二。"}, {"text": "吃", "is_correct": false, "explanation": "语义：细胞不会“吃”，“吃成两个新细胞”说不通。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”的宾语须是衣物，不能用“两个新细胞”作宾语。"}, {"text": "融化", "is_correct": false, "explanation": "搭配：“融化成”的结果是液体，不能说“融化成两个新细胞”。"}], "explanations": {"分裂": "正确答案：分裂，指细胞一分为二。", "吃": "语义：细胞不会“吃”，“吃成两个新细胞”说不通。", "穿": "配价：“穿”的宾语须是衣物，不能用“两个新细胞”作宾语。", "融化": "搭配：“融化成”的结果是液体，不能说“融化成两个新细胞”。"}, "sentence_index": 0, "correct_answer": "分裂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块蛋糕被分裂成了小块。", "explanation": "这里应该用〈分割〉。分裂指整体自己裂开，人为切开蛋糕要用分割。"}, {"text": "冰在阳光下慢慢分裂成了水。", "explanation": "这里应该用〈融化〉。分裂是裂成几块，固体变成水要用融化，不能用分裂。"}, {"text": "他从楼上摔下来，腿分裂成了两截。", "explanation": "这里应该用〈摔断〉。分裂不用于人的肢体，腿折断要用摔断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92781, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分裂", "is_correct": true, "explanation": "正确答案：分裂，指细胞一分为二，数量因此增加。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：细胞不会唱歌，这句话说不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：细胞不会散步，这里不能用“散步”。"}, {"text": "点燃", "is_correct": false, "explanation": "搭配：“点燃”多用于火、烟花等，不能用于细胞。"}], "explanations": {"分裂": "正确答案：分裂，指细胞一分为二，数量因此增加。", "唱歌": "语义：细胞不会唱歌，这句话说不通。", "散步": "语义：细胞不会散步，这里不能用“散步”。", "点燃": "搭配：“点燃”多用于火、烟花等，不能用于细胞。"}, "sentence_index": 6, "correct_answer": "分裂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "氢和氧分裂生成了水。", "explanation": "这里应该用〈结合〉。分裂是分开，氢和氧结合生成水要用结合，两者意思相反。"}, {"text": "墙面因为潮湿，颜色分裂了。", "explanation": "这里应该用〈变色〉。分裂指整体分成几块，颜色改变要用变色，不能说颜色分裂。"}, {"text": "这个小男孩很调皮，一转眼就分裂成了两个。", "explanation": "这里应该用〈分身〉。分裂只用于细胞、冰块等可以分开的物体，人不会分裂成两个；若想说一个人变出两个自己，应该用分身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92781, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那块石头被雷劈中后分裂了成两块。", "corrected_sentence": "那块石头被雷劈中后分裂成了两块。", "error_description": "错误：“分裂了成两块”；正确：“分裂成了两块”。“了”应放在结果补语“成”之后，不能插在“分裂”和“成”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92781, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个细胞慢慢把分裂成了两个。", "corrected_sentence": "这个细胞慢慢分裂成了两个。", "error_description": "错误：“把”字后面缺少被处置的宾语，而且“细胞”本身就是分裂的主体，不能再用“把”引出它；正确：“慢慢分裂成了两个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '482133c4-d396-4084-808e-835f6ae724b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
