INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某一地区范围内的经济活动及其发展状况。", "primary_collocate": null, "pronunciation": "dì qū jīng jì", "ipa": "ti˥˩ tɕʰy˥ tɕiŋ˥ tɕi˥˩", "syllable_count": 4, "sentences": [{"text": "这个地区经济发展得很快。", "target_word": "地区经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "西部地区经济比沿海慢一些。", "target_word": "地区经济", "complexity_tier": "T3", "furigana": "xī bù dì qū jīng jì bǐ yán hǎi màn yì xiē", "sentence_source": "generated"}, {"text": "政府想帮助西部地区经济发展。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新修的铁路让沿线地区经济变好了。", "target_word": "地区经济", "complexity_tier": "T3", "furigana": "xīn xiū de tiě lù ràng yán xiàn dì qū jīng jì biàn hǎo le", "sentence_source": "generated"}, {"text": "这个城市的地区经济主要靠旅游。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了东北地区经济的变化。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地区经济好了，年轻人就不用去外地工作。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年地区经济增长了百分之八。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河对周围地区经济很重要。", "target_word": "地区经济", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大学里学习地区经济。", "target_word": "地区经济", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词，指一个地区的经济活动和发展状况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abcd77a8-dfd0-4884-ad5f-32644d4c808a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地区经济", "is_correct": true, "explanation": "地区经济：某一地区范围内的经济活动及其发展状况，可以作“发展”的主语，句意通顺。"}, {"text": "个人收入", "is_correct": false, "explanation": "搭配：“发展”多用于经济、产业等，个人收入一般说“增长”，不说“发展得很快”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气可以“变化”，但不会“发展”，与句意不符。"}, {"text": "地理", "is_correct": false, "explanation": "语义：“地理”指地形、地貌等，不能说“发展得很快”。"}], "explanations": {"地区经济": "地区经济：某一地区范围内的经济活动及其发展状况，可以作“发展”的主语，句意通顺。", "个人收入": "搭配：“发展”多用于经济、产业等，个人收入一般说“增长”，不说“发展得很快”。", "天气": "语义：天气可以“变化”，但不会“发展”，与句意不符。", "地理": "语义：“地理”指地形、地貌等，不能说“发展得很快”。"}, "sentence_index": 0, "correct_answer": "地区经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新修的铁路让全国的地区经济变好了。", "explanation": "这里应该用〈国民经济〉。地区经济指某一地区范围内的经济，说全国的整体经济要用国民经济。"}, {"text": "这几年我家的地区经济提高了很多。", "explanation": "这里应该用〈收入〉。地区经济指一个地区的经济状况，不能指一个家庭的收入。"}, {"text": "这个地区经济很美。", "explanation": "这里应该用〈风景〉。地区经济指经济状况，不能用“很美”来形容，形容好看要说风景或环境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地区经济", "is_correct": true, "explanation": "地区经济：一个地区的经济状况，“好了”说明经济变好，年轻人就不用外出工作。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“体温”不能用“好了”来说状况，与后句的就业语境也无关。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：“眼睛”不是经济状况，“眼睛好了”与“不用去外地工作”之间没有关系。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”与年轻人外出工作的语境不相关，推不出就业的结果。"}], "explanations": {"地区经济": "地区经济：一个地区的经济状况，“好了”说明经济变好，年轻人就不用外出工作。", "体温": "搭配：“体温”不能用“好了”来说状况，与后句的就业语境也无关。", "眼睛": "语义：“眼睛”不是经济状况，“眼睛好了”与“不用去外地工作”之间没有关系。", "作业": "语义：“作业”与年轻人外出工作的语境不相关，推不出就业的结果。"}, "sentence_index": 6, "correct_answer": "地区经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他父母在家里负责管理地区经济。", "explanation": "这里应该用〈家庭经济〉。地区经济指一个地区的经济，管理一个家庭的开支要用家庭经济。"}, {"text": "他的地区经济提高了很多。", "explanation": "这里应该用〈成绩〉。地区经济指地区的经济状况，不能指个人的学习成绩。"}, {"text": "政府的地区经济用来建新学校。", "explanation": "这里应该用〈资金〉。地区经济指经济状况，不是可以用来花的钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的地区经济的变好了。", "corrected_sentence": "这个城市的地区经济变好了。", "error_description": "“地区经济”后面不能直接加“的”接谓语，“的”只用于名词修饰语之后。这里多加了“的”，应写成“这个城市的地区经济变好了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92786, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沿线的地区经济好起去了。", "corrected_sentence": "沿线的地区经济好起来了。", "error_description": "“好起来”表示变好的趋势，“起去”不能这样用，应写成“好起来”。这里把“来”错写成“去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4db7538-89a3-475a-94b2-d3096e4afc9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开通", "is_correct": true, "explanation": "正确：“开通”指让道路重新可以通行，与“封锁”相对，是反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "无关：“修建”指建造，与“封锁”不构成反义。"}, {"text": "观看", "is_correct": false, "explanation": "无关：“观看”指看，与“封锁”不构成反义。"}, {"text": "整理", "is_correct": false, "explanation": "无关：“整理”指把东西归类摆好，与“封锁”不构成反义。"}], "correct_answer": "开通", "explanations": {"开通": "正确：“开通”指让道路重新可以通行，与“封锁”相对，是反义关系。", "修建": "无关：“修建”指建造，与“封锁”不构成反义。", "观看": "无关：“观看”指看，与“封锁”不构成反义。", "整理": "无关：“整理”指把东西归类摆好，与“封锁”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开通", "is_correct": true, "explanation": "正确：“开通”指让道路重新可以通行，与“封锁”相对，是反义关系。"}, {"text": "推进", "is_correct": false, "explanation": "无关：“推进”指向前推动，与“封锁”不构成反义。"}, {"text": "保存", "is_correct": false, "explanation": "无关：“保存”指留存不失，与“封锁”不构成反义。"}, {"text": "谈判", "is_correct": false, "explanation": "无关：“谈判”指双方协商，与“封锁”不构成反义。"}], "correct_answer": "开通", "explanations": {"开通": "正确：“开通”指让道路重新可以通行，与“封锁”相对，是反义关系。", "推进": "无关：“推进”指向前推动，与“封锁”不构成反义。", "保存": "无关：“保存”指留存不失，与“封锁”不构成反义。", "谈判": "无关：“谈判”指双方协商，与“封锁”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "封锁是把路堵住，谁也过不去。", "primary_collocate": null, "pronunciation": "fēng suǒ", "ipa": "fɤŋ˥ suɔ˨˩", "syllable_count": 2, "sentences": [{"text": "大雪封锁了山路，车开不过去。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察封锁了路口，谁也不能进去。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事故发生后，警方马上封锁了那段公路。", "target_word": "封锁", "complexity_tier": "T3", "furigana": "shì gù fā shēng hòu, jǐng fāng mǎ shàng fēng suǒ le nà duàn gōng lù.", "sentence_source": "generated"}, {"text": "倒下的大树封锁了小路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水封锁了回村的路，我们只能等着。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把桥封锁了，行人都得绕路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人封锁着这条街，正在修路。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了安全，公园把东门封锁了。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天他们封锁了这条路两个小时。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雾封锁了高速公路，很多车停在路边。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封锁了", "label": "体标"}, {"form": "封锁着", "label": "体标"}, {"form": "封锁过", "label": "体标"}, {"form": "封锁线", "label": "复合"}], "register": "中性", "sense_fingerprint": "把道路、路口、现场堵住，使人和车无法通过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '230f03da-1729-41ca-a1ac-3cb91ec386f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修整", "is_correct": false, "explanation": "语义：“修整”指修好、整理，与“车开不过去”的结果矛盾，句子不通。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”指把路堵住，所以车开不过去，与句意一致。"}, {"text": "祝愿", "is_correct": false, "explanation": "搭配：“祝愿”的对象是人或事情，不能说祝愿山路。"}, {"text": "修筑", "is_correct": false, "explanation": "语义：“修筑”的施事是人，大雪不能修筑山路。"}], "explanations": {"修整": "语义：“修整”指修好、整理，与“车开不过去”的结果矛盾，句子不通。", "封锁": "正确：“封锁”指把路堵住，所以车开不过去，与句意一致。", "祝愿": "搭配：“祝愿”的对象是人或事情，不能说祝愿山路。", "修筑": "语义：“修筑”的施事是人，大雪不能修筑山路。"}, "sentence_index": 0, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司封锁了那位员工，让他回家。", "explanation": "这里应该用〈辞退〉。“封锁”的对象是通道或区域，不能用于人。"}, {"text": "警察封锁了这场打架，把两个人带走了。", "explanation": "这里应该用〈制止〉。“封锁”的对象是通道或区域，不能用于打架这类事件。"}, {"text": "妈妈封锁了窗户，怕冷风进来。", "explanation": "这里应该用〈关上〉。“封锁”指用强力封住通道，不用于日常关窗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏，与“正在修路”不协调，句子说不通。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”指把街道堵住，与“正在修路”的情境相符。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题、意见，不能说讨论这条街。"}, {"text": "追问", "is_correct": false, "explanation": "搭配：“追问”的对象是人或问题，不能用于街道。"}], "explanations": {"欣赏": "语义：“欣赏”指赞赏，与“正在修路”不协调，句子说不通。", "封锁": "正确：“封锁”指把街道堵住，与“正在修路”的情境相符。", "讨论": "搭配：“讨论”的对象是问题、意见，不能说讨论这条街。", "追问": "搭配：“追问”的对象是人或问题，不能用于街道。"}, "sentence_index": 6, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗帘封锁了阳光，屋里暗了下来。", "explanation": "这里应该用〈遮挡〉。“封锁”的对象是道路、港口等通道，不能用于阳光。"}, {"text": "我们封锁了博物馆，待了一整天。", "explanation": "这里应该用〈参观〉。“封锁”指封住通道或区域，不用于参观场所。"}, {"text": "老师封锁了那个座位，不让别人坐。", "explanation": "这里应该用〈占用〉。“封锁”指封住道路等通道，不用于座位；把座位占下、不让别人坐，要用“占用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人封锁了了这条山路，车开不过去。", "corrected_sentence": "工人封锁了这条山路，车开不过去。", "error_description": "“了”重复：动词后只能带一个“了”，“封锁了了”不合语法，应为“封锁了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92791, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人封锁了着这段路，正在修桥。", "corrected_sentence": "工人封锁着这段路，正在修桥。", "error_description": "“封锁”后不能同时带“了”和“着”，“了着”连用不合语法。正确说法是“工人封锁着这段路”，表示持续的状态，错误在于“了着”连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开放", "is_correct": true, "explanation": "正确：“开放”与“封锁”相对，指允许出入和往来，是反义关系。"}, {"text": "扩大", "is_correct": false, "explanation": "无关：“扩大”指使范围变大，与“封锁”不构成反义。"}, {"text": "解释", "is_correct": false, "explanation": "无关：“解释”指说明道理，与“封锁”不构成反义。"}, {"text": "储存", "is_correct": false, "explanation": "无关：“储存”指把东西收藏起来，与“封锁”不构成反义。"}], "correct_answer": "开放", "explanations": {"开放": "正确：“开放”与“封锁”相对，指允许出入和往来，是反义关系。", "扩大": "无关：“扩大”指使范围变大，与“封锁”不构成反义。", "解释": "无关：“解释”指说明道理，与“封锁”不构成反义。", "储存": "无关：“储存”指把东西收藏起来，与“封锁”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "开放", "is_correct": true, "explanation": "正确：“开放”与“封锁”相对，指允许出入和往来，是反义关系。"}, {"text": "增加", "is_correct": false, "explanation": "无关：“增加”指数量变多，与“封锁”不构成反义。"}, {"text": "赠送", "is_correct": false, "explanation": "无关：“赠送”指无偿送给别人，与“封锁”不构成反义。"}, {"text": "清理", "is_correct": false, "explanation": "无关：“清理”指清除杂物，与“封锁”不构成反义。"}], "correct_answer": "开放", "explanations": {"开放": "正确：“开放”与“封锁”相对，指允许出入和往来，是反义关系。", "增加": "无关：“增加”指数量变多，与“封锁”不构成反义。", "赠送": "无关：“赠送”指无偿送给别人，与“封锁”不构成反义。", "清理": "无关：“清理”指清除杂物，与“封锁”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用强力或其他手段封闭，使对外联系中断。", "primary_collocate": null, "pronunciation": "fēng suǒ", "ipa": "fɤŋ˥ suɔ˨˩", "syllable_count": 2, "sentences": [{"text": "军队封锁了通往城里的所有港口。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人封锁了边境，外面的人进不来。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想封锁消息，不让记者知道。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家封锁海面已经三个月了。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察封锁了整个小岛，没有船能出去。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争期间，敌人封锁着这座城市。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对方封锁了我们的网络，我们联系不上总部。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把村子封锁起来，不让外人进出。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府没有封锁边界，两国人员还能往来。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人封锁海面后，岛上缺少粮食和药。", "target_word": "封锁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "封锁了", "label": "体标"}, {"form": "封锁着", "label": "体标"}, {"form": "封锁过", "label": "体标"}, {"form": "封锁线", "label": "复合"}], "register": "书面", "sense_fingerprint": "用强力封闭港口、边境、消息等，使内外联系中断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '230f03da-1729-41ca-a1ac-3cb91ec386f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "祝福", "is_correct": false, "explanation": "搭配：“祝福”的对象是人，不能说祝福港口。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”指用强力封住港口，使对外联系中断，与句中的“军队”相符。"}, {"text": "粉刷", "is_correct": false, "explanation": "语义：“粉刷”指刷墙面，用于港口句意不通。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”后接活动或集体，不能接港口。"}], "explanations": {"祝福": "搭配：“祝福”的对象是人，不能说祝福港口。", "封锁": "正确：“封锁”指用强力封住港口，使对外联系中断，与句中的“军队”相符。", "粉刷": "语义：“粉刷”指刷墙面，用于港口句意不通。", "参加": "配价：“参加”后接活动或集体，不能接港口。"}, "sentence_index": 0, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地震封锁了电线，附近停了电。", "explanation": "这里应该用〈切断〉。“封锁”用于港口、边境、道路等通道，不用于电线这类设施。"}, {"text": "海关封锁了那批货物，要等检查完才能取走。", "explanation": "这里应该用〈扣押〉。“封锁”指封住道路、港口等通道，不用于扣下货物。"}, {"text": "医生封锁了那个病人，不让他接触别人。", "explanation": "这里应该用〈隔离〉。“封锁”的对象是通道或区域，不用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "维修", "is_correct": false, "explanation": "语义：“维修”是把设备修好，与“联系不上总部”的结果相反，句意不通。"}, {"text": "封锁", "is_correct": true, "explanation": "正确：“封锁”使网络中断，正好导致“联系不上总部”。"}, {"text": "检测", "is_correct": false, "explanation": "语义：“检测”是检查功能，不会导致“联系不上总部”。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”用于人或成就，不能接“网络”。"}], "explanations": {"维修": "语义：“维修”是把设备修好，与“联系不上总部”的结果相反，句意不通。", "封锁": "正确：“封锁”使网络中断，正好导致“联系不上总部”。", "检测": "语义：“检测”是检查功能，不会导致“联系不上总部”。", "祝贺": "搭配：“祝贺”用于人或成就，不能接“网络”。"}, "sentence_index": 6, "correct_answer": "封锁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵封锁了那只小狗，怕它跑出去。", "explanation": "这里应该用〈关住〉。“封锁”的对象是道路、港口等通道，不能用于动物。"}, {"text": "大树封锁了阳光，屋里暗了下来。", "explanation": "这里应该用〈遮挡〉。“封锁”的对象是道路、港口等通道，不能用于阳光。"}, {"text": "他封锁了钱包，没人能找到它。", "explanation": "这里应该用〈隐藏〉。“封锁”指封住通道，不用于藏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "敌人封锁着了这座港口，外面的船进不来。", "corrected_sentence": "敌人封锁了这座港口，外面的船进不来。", "error_description": "表示已经完成的动作时，“封锁”应带“了”，不能与“着”连用。正确说法是“敌人封锁了这座港口”，错误在于“着了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92792, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们封锁了了这座港口，外界的船进不来。", "corrected_sentence": "他们封锁了这座港口，外界的船进不来。", "error_description": "“了”重复：动词后只能带一个“了”，“封锁了了”不合语法，应为“封锁了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d475325-623c-484a-a3e1-a436c80d07f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
