INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "幻想是脑子里想一些不会真的发生的事。", "primary_collocate": null, "pronunciation": "huàn xiǎng", "ipa": "xwan˥˩ ɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他总幻想自己一夜之间变成明星。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别再幻想了，天上不会掉馅饼。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小时候，我常幻想自己能在天上飞。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她幻想着有一天遇到白马王子。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟幻想过当超人去救全世界。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要整天幻想发大财，要努力工作。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他幻想自己是国王，住在很大的城堡里。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别幻想他会突然给你一大笔钱。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们幻想着坐火箭去月亮上玩。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他累了就幻想自己躺在海边，什么都不用做。", "target_word": "幻想", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幻想着", "label": "体标"}, {"form": "幻想过", "label": "体标"}, {"form": "幻想了", "label": "体标"}], "register": "通用", "sense_fingerprint": "动词：在脑子里想不会真的发生的事，后面常接自己或想象的情景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确答案。幻想（huàn xiǎng）指脑子里想一些不会真的发生的事。"}, {"text": "换向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）韵母相同、声调不同，意思是改变方向。"}, {"text": "幻乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是幻想中的美好地方。"}, {"text": "怀想", "is_correct": false, "explanation": "huái（第二声）与 huàn（第四声）韵母和声调都不同，意思是怀念、回想。"}], "explanations": {"幻想": "正确答案。幻想（huàn xiǎng）指脑子里想一些不会真的发生的事。", "换向": "xiàng（第四声）与 xiǎng（第三声）韵母相同、声调不同，意思是改变方向。", "幻乡": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是幻想中的美好地方。", "怀想": "huái（第二声）与 huàn（第四声）韵母和声调都不同，意思是怀念、回想。"}, "sentence_index": null, "correct_answer": "幻想"}, "level_3": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确：“幻想”指想象不会发生的事，可以接“自己一夜之间变成明星”。"}, {"text": "练习", "is_correct": false, "explanation": "配价：“练习”要带动作的对象，不能接“自己一夜之间变成明星”这样的小句。"}, {"text": "研究", "is_correct": false, "explanation": "配价：“研究”的宾语是问题或事物，不能接这样的句子。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，与“变成明星”没有关系，句子不通。"}], "explanations": {"幻想": "正确：“幻想”指想象不会发生的事，可以接“自己一夜之间变成明星”。", "练习": "配价：“练习”要带动作的对象，不能接“自己一夜之间变成明星”这样的小句。", "研究": "配价：“研究”的宾语是问题或事物，不能接这样的句子。", "吃": "语义：“吃”指进食，与“变成明星”没有关系，句子不通。"}, "sentence_index": 0, "correct_answer": "幻想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她幻想着明天去参加考试。", "explanation": "这里应该用〈计划〉。幻想指想不会真的发生的事，明天的考试是可以安排的，要用计划。"}, {"text": "她幻想着把这笔钱存进银行。", "explanation": "这里应该用〈打算〉。幻想指想不会真的发生的事，把钱存进银行是可以实行的打算，要用打算。"}, {"text": "她幻想着明天会下雨，所以带了伞。", "explanation": "这里应该用〈预测〉。幻想是想象不会实现的事，根据天气判断将要发生的事要用预测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确：“幻想”指想象不现实的事，可以接“自己是国王，住在很大的城堡里”。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：“打扫”指清理场所，不能用来说“自己是国王”。"}, {"text": "检查", "is_correct": false, "explanation": "配价：“检查”的宾语是人或事物，不能接“自己是国王”这样的小句。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”指用水洗掉污物，与句子的意思不合。"}], "explanations": {"幻想": "正确：“幻想”指想象不现实的事，可以接“自己是国王，住在很大的城堡里”。", "打扫": "语义：“打扫”指清理场所，不能用来说“自己是国王”。", "检查": "配价：“检查”的宾语是人或事物，不能接“自己是国王”这样的小句。", "清洗": "语义：“清洗”指用水洗掉污物，与句子的意思不合。"}, "sentence_index": 6, "correct_answer": "幻想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们幻想了三种方案，最后选了最合适的一个。", "explanation": "这里应该用〈设想〉。幻想指想象不可能实现的事，提出可以执行的方案要用设想。"}, {"text": "他幻想起童年在海边玩耍的日子。", "explanation": "这里应该用〈回忆〉。幻想指想象将来或不可能的事，已经发生过的童年生活要用回忆。"}, {"text": "根据这些证据，我幻想他就是小偷。", "explanation": "这里应该用〈推测〉。幻想不能用来根据证据做判断，这种判断要用推测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常常着幻想自己成为作家。", "corrected_sentence": "他常常幻想自己成为作家。", "error_description": "“着”应放在动词后面表示持续的状态，不能放在“幻想”前面。应改为：他常常幻想自己成为作家。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92805, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他幻想的很开心，忘了时间。", "corrected_sentence": "他幻想得很开心，忘了时间。", "error_description": "补语要用“得”接在动词后面表示程度，“的”不能这样用。应改为：他幻想得很开心，忘了时间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
