INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92806, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92806, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "对不可能实现的事物所作的美好设想。", "primary_collocate": null, "pronunciation": "huàn xiǎng", "ipa": "xwan˥˩ ɕjaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他对未来有很多美好的幻想。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只是一个幻想，不会变成真的。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年轻人常常有各种不现实的幻想。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的幻想最后全都破灭了。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "对这个人，我早就没有幻想了。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他靠幻想活着，不愿面对现实。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她小时候的幻想，现在一个也没实现。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别用幻想代替努力，生活不是童话。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把自己的幻想写成了一本小说。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的幻想很美，可是现实很苦。", "target_word": "幻想", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "幻想小说", "label": "复合"}], "register": "通用", "sense_fingerprint": "名词：对不可能实现的事物所作的美好设想，常说有幻想、幻想破灭", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbe7cc2-5e9e-40b7-aa24-1c71bcda64ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92806, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确答案。幻想（huàn xiǎng）指对不可能实现的事物所作的美好设想。"}, {"text": "换向", "is_correct": false, "explanation": "xiàng（第四声）与 xiǎng（第三声）韵母相同、声调不同，意思是改变方向。"}, {"text": "幻乡", "is_correct": false, "explanation": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是幻想中的美好地方。"}, {"text": "怀想", "is_correct": false, "explanation": "huái（第二声）与 huàn（第四声）韵母和声调都不同，意思是怀念、回想。"}], "explanations": {"幻想": "正确答案。幻想（huàn xiǎng）指对不可能实现的事物所作的美好设想。", "换向": "xiàng（第四声）与 xiǎng（第三声）韵母相同、声调不同，意思是改变方向。", "幻乡": "xiāng（第一声）与 xiǎng（第三声）声调不同，意思是幻想中的美好地方。", "怀想": "huái（第二声）与 huàn（第四声）韵母和声调都不同，意思是怀念、回想。"}, "sentence_index": null, "correct_answer": "幻想"}, "level_3": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确：“幻想”指对未来的美好设想，可以说“美好的幻想”。"}, {"text": "回忆", "is_correct": false, "explanation": "语义：“回忆”指对过去的记忆，与“对未来”的说法矛盾。"}, {"text": "疑虑", "is_correct": false, "explanation": "搭配：“疑虑”是担心的情绪，不能用“美好”来修饰。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能说“对未来有很多美好的价格”，句子不通。"}], "explanations": {"幻想": "正确：“幻想”指对未来的美好设想，可以说“美好的幻想”。", "回忆": "语义：“回忆”指对过去的记忆，与“对未来”的说法矛盾。", "疑虑": "搭配：“疑虑”是担心的情绪，不能用“美好”来修饰。", "价格": "语义：“价格”指钱数，不能说“对未来有很多美好的价格”，句子不通。"}, "sentence_index": 0, "correct_answer": "幻想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的幻想最后全都落实了。", "explanation": "这里应该用〈设想〉。幻想指不可能实现的美好想象，能够落实的方案要用设想。"}, {"text": "这个幻想很可行，我们下周就开始做。", "explanation": "这里应该用〈计划〉。幻想是不可能实现的美好设想，可行、能马上执行的安排要用计划。"}, {"text": "他这次考试的幻想很好，拿到了第一名。", "explanation": "这里应该用〈成绩〉。幻想是不现实的美好设想，考试的结果要用成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幻想", "is_correct": true, "explanation": "正确：“幻想”指美好的设想，可以说“小时候的幻想”，且多数没有实现。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的高矮，不是可以实现的愿望。"}, {"text": "课本", "is_correct": false, "explanation": "语义：“课本”是书，不能说“实现”，句子不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“实现”的对象应是愿望或计划，不能说“体重没实现”。"}], "explanations": {"幻想": "正确：“幻想”指美好的设想，可以说“小时候的幻想”，且多数没有实现。", "身高": "语义：“身高”指人的高矮，不是可以实现的愿望。", "课本": "语义：“课本”是书，不能说“实现”，句子不通。", "体重": "搭配：“实现”的对象应是愿望或计划，不能说“体重没实现”。"}, "sentence_index": 6, "correct_answer": "幻想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个幻想很周密，已经开始执行了。", "explanation": "这里应该用〈方案〉。幻想不是可以执行的计划，有周密安排、可以执行的事要用方案。"}, {"text": "她心里有一个幻想，考虑了三年，最后决定去做。", "explanation": "这里应该用〈想法〉。幻想是不可能实现的美好设想，经过多年考虑并决定去做的念头要用想法。"}, {"text": "他的幻想很准确，大家都很佩服。", "explanation": "这里应该用〈猜测〉。幻想是不现实的美好设想，判断事情是否准确要用猜测。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他心里有一只美好的幻想。", "corrected_sentence": "他心里有一个美好的幻想。", "error_description": "“幻想”前面的量词应用“个”，不能用“只”。应改为：他心里有一个美好的幻想。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一个奇妙地幻想。", "corrected_sentence": "她有一个奇妙的幻想。", "error_description": "“奇妙”修饰名词“幻想”时要用“的”，不能用“地”。应改为：她有一个奇妙的幻想。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e283ca2f-7428-43e3-8cc3-e707b574f152') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
