INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92813, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "持是用手拿着，不放开。", "primary_collocate": null, "pronunciation": "chí", "ipa": "ʈʂʰɻ̩˧˥", "syllable_count": 1, "sentences": [{"text": "他右手持一把黑伞，站在门口等人。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人双手持杯，慢慢地喝了一口茶。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵持枪站在门口，一动也不动。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她左手持话筒，右手向观众挥了挥。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他持一束花，在车站等了半个小时。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "服务员双手持盘，小心地走进了房间。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察持盾牌走在最前面，后面是消防员。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师右手持刀，左手按住鱼，很快切好了。", "target_word": "持", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他双手持一根长竹竿，走过了小河。", "target_word": "持", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他双手持相机，对着远处的山拍了很多照片。", "target_word": "持", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "持着", "label": "体标"}], "register": "书面", "sense_fingerprint": "持|动词|用手拿着不放开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a27985d7-ed1e-45a0-89a0-5af58ad339f9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92813, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "持", "is_correct": true, "explanation": "持（chí）：用手拿着，是本题的正确答案。"}, {"text": "尺", "is_correct": false, "explanation": "尺（chǐ）与 chí 声调不同（第三声），意思是尺子。"}, {"text": "吃", "is_correct": false, "explanation": "吃（chī）与 chí 声调不同（第一声），意思是吃东西。"}, {"text": "翅", "is_correct": false, "explanation": "翅（chì）与 chí 声调不同（第四声），意思是翅膀。"}, {"text": "时", "is_correct": false, "explanation": "时（shí）与 chí 声母不同（sh 与 ch），意思是时间。"}], "explanations": {"持": "持（chí）：用手拿着，是本题的正确答案。", "尺": "尺（chǐ）与 chí 声调不同（第三声），意思是尺子。", "吃": "吃（chī）与 chí 声调不同（第一声），意思是吃东西。", "翅": "翅（chì）与 chí 声调不同（第四声），意思是翅膀。", "时": "时（shí）与 chí 声母不同（sh 与 ch），意思是时间。"}, "sentence_index": null, "correct_answer": "持"}, "level_3": {"options": [{"text": "持", "is_correct": true, "explanation": "持：用手拿着，与“右手”和“一把黑伞”的语境相符，是本题正确答案。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物送进嘴里，不能用来指右手拿伞。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能说唱一把黑伞。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”用于帽子、眼镜等物，不能说戴一把黑伞。"}], "explanations": {"持": "持：用手拿着，与“右手”和“一把黑伞”的语境相符，是本题正确答案。", "吃": "语义：“吃”指把食物送进嘴里，不能用来指右手拿伞。", "唱": "搭配：“唱”的对象是歌曲，不能说唱一把黑伞。", "戴": "搭配：“戴”用于帽子、眼镜等物，不能说戴一把黑伞。"}, "sentence_index": 0, "correct_answer": "持"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈持着孩子在院子里散步。", "explanation": "这里应该用〈抱〉。“持”指用手拿住器物，不用于怀里抱着的孩子，应说抱着孩子。"}, {"text": "他持着一股香味走进院子。", "explanation": "这里应该用〈带〉。“持”指用手拿住器物，不能用于气味，应说带着一股香味。"}, {"text": "他持了一个奖，大家都来祝贺。", "explanation": "这里应该用〈拿〉。“拿”可表示获得，如拿奖；“持”没有获得的意思，不能说持奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92813, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "持", "is_correct": true, "explanation": "持（chí）：用手拿着，是本题的正确答案。"}, {"text": "齿", "is_correct": false, "explanation": "齿（chǐ）与 chí 声调不同（第三声），意思是牙齿。"}, {"text": "赤", "is_correct": false, "explanation": "赤（chì）与 chí 声调不同（第四声），意思是红色。"}, {"text": "直", "is_correct": false, "explanation": "直（zhí）与 chí 声母不同（zh 与 ch），意思是笔直。"}, {"text": "十", "is_correct": false, "explanation": "十（shí）与 chí 声母不同（sh 与 ch），意思是数字十。"}], "explanations": {"持": "持（chí）：用手拿着，是本题的正确答案。", "齿": "齿（chǐ）与 chí 声调不同（第三声），意思是牙齿。", "赤": "赤（chì）与 chí 声调不同（第四声），意思是红色。", "直": "直（zhí）与 chí 声母不同（zh 与 ch），意思是笔直。", "十": "十（shí）与 chí 声母不同（sh 与 ch），意思是数字十。"}, "sentence_index": null, "correct_answer": "持"}, "level_3": {"options": [{"text": "持", "is_correct": true, "explanation": "持：用手拿着，与“右手”和“盾牌”的语境相符，是本题正确答案。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”用于衣服、鞋袜等，不能说穿盾牌。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”的对象是马、自行车等，不能说骑盾牌。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿啃咬，与手持盾牌的语境不符。"}], "explanations": {"持": "持：用手拿着，与“右手”和“盾牌”的语境相符，是本题正确答案。", "穿": "搭配：“穿”用于衣服、鞋袜等，不能说穿盾牌。", "骑": "搭配：“骑”的对象是马、自行车等，不能说骑盾牌。", "咬": "语义：“咬”指用牙齿啃咬，与手持盾牌的语境不符。"}, "sentence_index": 6, "correct_answer": "持"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他持了很大的力气，把门推开了。", "explanation": "这里应该用〈使〉。“持”不能与“力气”搭配表示用力，应说使了很大的力气。"}, {"text": "墙上持着一幅画。", "explanation": "这里应该用〈挂〉。“持”指用手拿住，不能说把画挂在墙上，应说墙上挂着一幅画。"}, {"text": "她每天持钢琴练习一个小时。", "explanation": "这里应该用〈弹〉。“持”只表示用手拿着，不能用来指弹奏乐器，应说弹钢琴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92813, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他右手持着了一把红伞，站在车站等车。", "corrected_sentence": "他右手持着一把红伞，站在车站等车。", "error_description": "错误：“着”后面多加了“了”，写成“持着了一把红伞”。正确：“持着一把红伞”。原因：“着”已表示持续的状态，后面不能再加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92813, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他双手持一个木盒着，站在台上。", "corrected_sentence": "他双手持一个木盒，站在台上。", "error_description": "错误：多加了“着”，写成“持一个木盒着”。正确：“持一个木盒”。原因：句中“持”表示用手拿住，不需要再加“着”，且“着”不能放在宾语后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '805a883a-cef1-44ea-84d0-ac7fbd81e9f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
