INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92815, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "新派是和以前不一样的、新的样子或做法。", "primary_collocate": null, "pronunciation": "xīn pài", "ipa": "ɕin˥ pʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他的穿衣风格很新派。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆做的是新派川菜。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶觉得年轻人的做法太新派了。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位厨师做的菜很新派，味道也不一样。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的房子装修得很新派。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爸爸不太喜欢新派音乐。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新开的茶馆有很多新派饮料。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的服务方式很新派，不用点菜本。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个新派的老师，常常带学生去公园上课。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚的方式很新派，没有请客。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新派川菜", "label": "复合词"}], "register": "中性", "sense_fingerprint": "样子或做法和以前不同，很新式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92815, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "响亮", "is_correct": false, "explanation": "搭配：“响亮”形容声音，不能用来形容穿衣风格。"}, {"text": "新派", "is_correct": true, "explanation": "“新派”指样子或做法和以前不一样，与“他的穿衣风格很新派”相符。"}, {"text": "低矮", "is_correct": false, "explanation": "体貌：“低矮”形容个子或建筑的高度，不能用来形容穿衣风格。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”形容味道，穿衣风格不能说是咸的。"}], "explanations": {"响亮": "搭配：“响亮”形容声音，不能用来形容穿衣风格。", "新派": "“新派”指样子或做法和以前不一样，与“他的穿衣风格很新派”相符。", "低矮": "体貌：“低矮”形容个子或建筑的高度，不能用来形容穿衣风格。", "咸": "语义：“咸”形容味道，穿衣风格不能说是咸的。"}, "sentence_index": 0, "correct_answer": "新派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的年龄很新派。", "explanation": "这里应该用〈年轻〉。新派形容样子或做法的新，年龄的大小要用年轻。"}, {"text": "这些蔬菜很新派，每天早上都送来。", "explanation": "这里应该用〈新鲜〉。新派指样子或做法和以前不同，蔬菜的鲜嫩要用新鲜。"}, {"text": "这位老人身体很新派。", "explanation": "这里应该用〈健康〉。新派用于样子和做法，身体的状况要用健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92815, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指旧的、过时的，与“新开的茶馆”的“新”冲突。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：“粗糙”指做工或质量不精细，与“新派”饮料的新式特点相悖。"}, {"text": "强硬", "is_correct": false, "explanation": "搭配：“强硬”形容态度或性格，不能用来形容饮料。"}, {"text": "新派", "is_correct": true, "explanation": "“新派”指样子或做法和以前不同，与“新开的茶馆有很多新派饮料”相符。"}], "explanations": {"陈旧": "语义：“陈旧”指旧的、过时的，与“新开的茶馆”的“新”冲突。", "粗糙": "语义：“粗糙”指做工或质量不精细，与“新派”饮料的新式特点相悖。", "强硬": "搭配：“强硬”形容态度或性格，不能用来形容饮料。", "新派": "“新派”指样子或做法和以前不同，与“新开的茶馆有很多新派饮料”相符。"}, "sentence_index": 6, "correct_answer": "新派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数字很新派。", "explanation": "这里应该用〈大〉。新派形容样子或做法的新，数字的大小要用大。"}, {"text": "她今天心情很新派。", "explanation": "这里应该用〈快乐〉。新派形容样子或做法，心情的好坏要用快乐。"}, {"text": "他的声音很新派。", "explanation": "这里应该用〈响亮〉。新派形容样子或做法，声音的洪亮要用响亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92815, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们的婚礼办很新派。", "corrected_sentence": "他们的婚礼办得很新派。", "error_description": "缺少“得”：“办”后面表示状态的补语要用“办得很新派”，不能说“办很新派”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92815, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜单新派。", "corrected_sentence": "这家店的菜单很新派。", "error_description": "缺少程度副词：性质形容词作陈述句谓语时一般要加“很”，应说“菜单很新派”，不能只说“菜单新派”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "安静", "is_correct": false, "explanation": "“安静”形容声音或环境平和，与新旧风格无关，不是反义词。"}, {"text": "旧派", "is_correct": true, "explanation": "“旧派”与“新派”相对，指旧风格、旧思想的一派，是这个义项的反义词。"}, {"text": "美丽", "is_correct": false, "explanation": "“美丽”形容外貌或景色好看，与“新派”的风格、思想无关。"}, {"text": "开朗", "is_correct": false, "explanation": "“开朗”形容性格乐观外向，与“新派”的新旧对立无关。"}], "correct_answer": "旧派", "explanations": {"安静": "“安静”形容声音或环境平和，与新旧风格无关，不是反义词。", "旧派": "“旧派”与“新派”相对，指旧风格、旧思想的一派，是这个义项的反义词。", "美丽": "“美丽”形容外貌或景色好看，与“新派”的风格、思想无关。", "开朗": "“开朗”形容性格乐观外向，与“新派”的新旧对立无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "高大", "is_correct": false, "explanation": "“高大”形容身材或体积，与“新派”的新旧风格无关，不是反义词。"}, {"text": "旧派", "is_correct": true, "explanation": "“旧派”与“新派”相对，指旧风格、旧思想的一派，是这个义项的反义词。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容态度温和友好，与“新派”的新旧对立无关。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容明白、分明，与“新派”的风格、思想无关。"}], "correct_answer": "旧派", "explanations": {"高大": "“高大”形容身材或体积，与“新派”的新旧风格无关，不是反义词。", "旧派": "“旧派”与“新派”相对，指旧风格、旧思想的一派，是这个义项的反义词。", "热情": "“热情”形容态度温和友好，与“新派”的新旧对立无关。", "清楚": "“清楚”形容明白、分明，与“新派”的风格、思想无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有新风格、新思想的；与旧派相对。", "primary_collocate": null, "pronunciation": "xīn pài", "ipa": "ɕin˥ pʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他是一位新派画家，画法和老画家很不同。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位新派作家的想法和老一辈不一样。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长是新派人物，常常改变学校的旧规矩。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部新派电影用了很多新办法讲故事。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷是老派人，我叔叔却很新派。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的教学方法很新派，和旧派老师完全不同。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家报纸的新派文章常常让老读者不高兴。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新派诗人不喜欢照老办法写诗。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位新派导演的思路很超前，看的人都很吃惊。", "target_word": "新派", "complexity_tier": "T3", "furigana": "zhè wèi xīn pài dǎo yǎn de sī lù hěn chāo qián, kàn de rén dōu hěn chī jīng.", "sentence_source": "generated"}, {"text": "他的思想很新派，不喜欢旧规矩。", "target_word": "新派", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "新派人物", "label": "复合词"}], "register": "中性", "sense_fingerprint": "有新风格、新思想，和旧派、老派对立", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b30465e8-a764-427e-9db7-903b0f509c2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精致", "is_correct": false, "explanation": "搭配：“精致”形容物品和工艺，不能用来形容一个画家。"}, {"text": "豪华", "is_correct": false, "explanation": "搭配：“豪华”形容物品或场所，不能用来形容画家。"}, {"text": "新派", "is_correct": true, "explanation": "“新派”指有新风格、新思想，与“他是一位新派画家，画法和老画家很不同”相符。"}, {"text": "旧式", "is_correct": false, "explanation": "语义：“旧式”指旧的、过时的，与“画法和老画家很不同”的新意矛盾。"}], "explanations": {"精致": "搭配：“精致”形容物品和工艺，不能用来形容一个画家。", "豪华": "搭配：“豪华”形容物品或场所，不能用来形容画家。", "新派": "“新派”指有新风格、新思想，与“他是一位新派画家，画法和老画家很不同”相符。", "旧式": "语义：“旧式”指旧的、过时的，与“画法和老画家很不同”的新意矛盾。"}, "sentence_index": 0, "correct_answer": "新派"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些水果很新派，吃起来很甜。", "explanation": "这里应该用〈新鲜〉。新派指风格和思想的新，水果的鲜嫩要用新鲜。"}, {"text": "山里的空气很新派，让人心情很好。", "explanation": "这里应该用〈清新〉。清新形容空气和环境，不能用新派。"}, {"text": "她的声音很新派，听起来很温柔。", "explanation": "这里应该用〈甜美〉。甜美形容声音和外貌，新派指风格或思想的新。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容温度，不能用来形容文章。"}, {"text": "陡峭", "is_correct": false, "explanation": "体貌：“陡峭”形容山坡等地形，不能用来形容文章。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”形容质地，文章不能这样形容。"}, {"text": "新派", "is_correct": true, "explanation": "“新派”指有新风格、新思想，与“这家报纸的新派文章”相符。"}], "explanations": {"寒冷": "语义：“寒冷”形容温度，不能用来形容文章。", "陡峭": "体貌：“陡峭”形容山坡等地形，不能用来形容文章。", "柔软": "语义：“柔软”形容质地，文章不能这样形容。", "新派": "“新派”指有新风格、新思想，与“这家报纸的新派文章”相符。"}, "sentence_index": 6, "correct_answer": "新派"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只鸟的叫声很新派，每天都能听到。", "explanation": "这里应该用〈清脆〉。新派形容风格或思想，叫声的清亮要用清脆。"}, {"text": "这杯水很新派。", "explanation": "这里应该用〈烫〉。新派形容风格或思想的新，水的温度要用烫。"}, {"text": "这条河很新派，船可以通过。", "explanation": "这里应该用〈宽阔〉。新派形容风格或思想，河面的宽窄要用宽阔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影拍很新派。", "corrected_sentence": "这部电影拍得很新派。", "error_description": "缺少“得”：动词“拍”后面表示状态的补语要用“拍得很新派”，不能说“拍很新派”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92816, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家的画风新派。", "corrected_sentence": "这位画家的画风很新派。", "error_description": "缺少程度副词：性质形容词作陈述句谓语时一般要加“很”，应说“画风很新派”，不能只说“画风新派”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6957fec2-0e25-4d56-80e6-7584c118f6bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
