INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "没错是说你说对了。", "primary_collocate": null, "pronunciation": "méi cuò", "ipa": "mei³⁵ tsʰuo⁵¹", "syllable_count": 2, "sentences": [{"text": "你是小王吗？没错，我是小王。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这家店的菜很好吃。”“没错！”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你说得对吧？”“没错，我也这么想。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，今天是我的生日。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“他是你哥哥吧？”“没错。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，这就是我要找的书。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“明天不上课吧？”“没错，明天不上课。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，我昨天去过那里。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你想家了吧？”“没错，很想。”", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没错，他就是我们的新老师。", "target_word": "没错", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "回应对方，表示对方说得对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3f02719e-3c90-40e7-bbaa-c6aefb6742c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示对方说得对，是肯定的回应，与后句“我是小王”一致。"}, {"text": "不对", "is_correct": false, "explanation": "语义：“不对”否定了对方的问话，与后句“我是小王”的肯定相矛盾。"}, {"text": "不是", "is_correct": false, "explanation": "语义：“不是”否定了身份，与后句“我是小王”直接矛盾。"}, {"text": "胡说", "is_correct": false, "explanation": "语域：“胡说”带有指责意味，用来回应对方的问题很不礼貌，且与后句矛盾。"}], "explanations": {"没错": "没错表示对方说得对，是肯定的回应，与后句“我是小王”一致。", "不对": "语义：“不对”否定了对方的问话，与后句“我是小王”的肯定相矛盾。", "不是": "语义：“不是”否定了身份，与后句“我是小王”直接矛盾。", "胡说": "语域：“胡说”带有指责意味，用来回应对方的问题很不礼貌，且与后句矛盾。"}, "sentence_index": 0, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“这个多少钱？”“没错。”", "explanation": "这里应该用〈十块〉。“没错”只用于确认对方说的内容正确，不用于回答价格、数量等具体问题。"}, {"text": "我们去公园吧，没错。", "explanation": "这里应该用〈好的〉。“没错”只用于确认对方说的内容正确，不用于接受别人的提议。"}, {"text": "谢谢你送我的礼物，没错。", "explanation": "这里应该用〈不客气〉。“没错”是对对方说法的肯定，不用来回应别人的感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "没错", "is_correct": true, "explanation": "没错表示对方说得对，与“明天不上课”的确认语气一致。"}, {"text": "没用", "is_correct": false, "explanation": "语义：“没用”说对方的话无效，与句中“明天不上课”的确认语气不符。"}, {"text": "没意思", "is_correct": false, "explanation": "语义：“没意思”评价对方的话乏味，与后句的通知语气不协调。"}, {"text": "不行", "is_correct": false, "explanation": "语义：“不行”表示不允许、不可以，与对方确认“明天不上课”的语气不合。"}], "explanations": {"没错": "没错表示对方说得对，与“明天不上课”的确认语气一致。", "没用": "语义：“没用”说对方的话无效，与句中“明天不上课”的确认语气不符。", "没意思": "语义：“没意思”评价对方的话乏味，与后句的通知语气不协调。", "不行": "语义：“不行”表示不允许、不可以，与对方确认“明天不上课”的语气不合。"}, "sentence_index": 6, "correct_answer": "没错"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我要走了，没错。", "explanation": "这里应该用〈再见〉。“没错”只用于确认对方说法正确，不能用于告别。"}, {"text": "你要喝水吗？没错。", "explanation": "这里应该用〈谢谢〉。“没错”是确认对方说法正确，不用来回应别人提出的好意或提议。"}, {"text": "“我回来了。”“没错！”", "explanation": "这里应该用〈欢迎回来〉。“没错”不用来回应对方的问候或告知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你是张经理吗？不没错，我是张经理。", "corrected_sentence": "你是张经理吗？没错，我是张经理。", "error_description": "错误：“不没错”，正确：“没错”。“没错”本身已是否定，前面不能再加“不”，否则双重否定，意思相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92837, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你说明天下雨，很没错，天气预报也这么说。", "corrected_sentence": "你说明天下雨，没错，天气预报也这么说。", "error_description": "错误：“很没错”，正确：“没错”。“没错”是表示对方说对了的固定回应，本身不能再受“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c61a23a8-bfa8-4117-ac61-b41df8ac63df') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
